-- SRS review-card backfill — BATCH 6 of 10 (764 rows).
-- Run each batch on its own in the Supabase SQL Editor; order does not matter and
-- each is idempotent. Together the 10 batches equal backfill_srs_payload.sql.
-- Covers Top 2 preboards/mocks/reviewer + main-app banks + Top 2 banks.
WITH d(qid, patch) AS (
  VALUES
  ('5b0a0602-14','{"options": ["Plasma pseudo-cholinesterase", "Kidney", "Corneal epithelium", "Liver"], "correct": 3, "decode": "Amides = LIVER; esters = plasma cholinesterase. Pick the hepatic option for amides.", "ow": ["That is the ester route.", "Not the metabolism site.", "Not a metabolic organ.", "Correct. Amides are hepatically metabolized."]}'),
  ('ed8b7c67-21','{"options": ["Extends the duration safely", "Adds only toxicity and stinging", "Shortens the onset time", "Deepens the block further"], "correct": 1, "decode": "Above the effective dose you gain nothing but harm: more concentration = toxicity and stinging, not a better, safer, or faster block. Reject the improvement options.", "ow": ["No; excess adds toxicity, not safe duration.", "Correct. Past the effective dose it only harms.", "Onset is not meaningfully improved.", "The block plateaus; extra drug just harms."]}'),
  ('0ed2a314-1z','{"options": ["After the culture is taken", "Before the culture, for comfort", "Only if the patient objects", "At the same time as the swab"], "correct": 0, "decode": "Anesthetic drops and their preservatives can inhibit organisms, so take the culture FIRST, then anesthetize. ''Before, for comfort'' is the tempting trap.", "ow": ["Correct. Avoids the anesthetic inhibiting the organisms.", "Preservatives can suppress growth and spoil the culture.", "Not the clinical rule.", "Still risks contaminating the sample."]}'),
  ('bfc6e9cb-1o','{"options": ["Elevated", "Depressed or pitted", "Fully denuded", "Infected"], "correct": 0, "decode": "Negative staining is where dye is EXCLUDED because tissue is raised (elevated). Positive staining (pooling) marks a depression/defect, the opposite.", "ow": ["Correct. Raised areas exclude the dye (negative staining).", "That gives positive staining (pooling).", "A frank defect pools dye (positive staining).", "Infection is not defined by negative staining."]}'),
  ('fab4fc92-1m','{"options": ["Proparacaine", "Benoxinate", "Lidocaine", "Tetracaine"], "correct": 1, "decode": "Benoxinate (oxybuprocaine) is the anesthetic with an antibacterial property. Proparacaine, tetracaine and lidocaine lack it; recall benoxinate specifically.", "ow": ["The routine anesthetic, but no antibacterial property.", "Correct. Carries an antibacterial property.", "An amide anesthetic, no antibacterial action.", "An ester anesthetic, no antibacterial action."]}'),
  ('34bf3d74-1j','{"options": ["Topical beta blockers", "Intravenous mannitol", "Laser peripheral iridotomy", "Oral acetazolamide"], "correct": 2, "decode": "Medical measures (mannitol, acetazolamide, beta blockers) buy time; the DEFINITIVE fix that relieves pupillary block is laser peripheral iridotomy.", "ow": ["Temporizing, not definitive.", "Lowers IOP acutely, not the definitive cure.", "Correct. Relieves the pupillary block definitively.", "A temporizing production-cutter, not definitive."]}'),
  ('ae8aa8db-18','{"options": ["Cornea verticillata", "Reduced acuity and color change", "Optic disc pallor", "The bull''s-eye maculopathy"], "correct": 1, "decode": "The BULL''S-EYE is a LATE sign; the EARLIEST chloroquine toxicity is subtle reduced acuity and a color (tritan) change. ''Earliest'' rules out the classic late finding.", "ow": ["A corneal deposit, not the earliest retinal toxicity.", "Correct. The earliest functional signs.", "A late/nonspecific finding.", "The classic but LATE sign."]}'),
  ('8cc30e8e-1b','{"options": ["Leukotriene synthesis", "Cyclo-oxygenase only", "Both COX and lipoxygenase", "Phospholipase A2"], "correct": 1, "decode": "NSAIDs block COX ONLY (downstream); steroids block phospholipase A2 (upstream, both pathways). ''Only COX'' = NSAID.", "ow": ["That is the lipoxygenase arm, not NSAIDs.", "Correct. NSAIDs inhibit COX alone.", "Broader than NSAIDs.", "That is the steroid target."]}'),
  ('0f3c12fe-1j','{"options": ["Cornea verticillata", "Anterior stellate cataract", "Optic neuropathy", "Colored halos"], "correct": 2, "decode": "Verticillata and halos are benign; the SIGHT-THREATENING amiodarone effect is optic NEUROPATHY. ''Genuinely threatens sight'' rules out the corneal and lens findings.", "ow": ["Common but benign deposit.", "That is phenothiazines, not amiodarone.", "Correct. The sight-threatening amiodarone toxicity.", "A benign visual symptom."]}'),
  ('ee6ed624-1c','{"options": ["Posterior subcapsular", "Cortical spoke", "Anterior stellate", "Nuclear sclerotic"], "correct": 0, "decode": "Steroids = POSTERIOR subcapsular cataract (paired with steroid glaucoma). Anterior stellate is phenothiazines; nuclear/cortical are age-related. ''Steroid'' = posterior.", "ow": ["Correct. The classic steroid cataract.", "An age-related/diabetic pattern.", "That is phenothiazines.", "The common age-related cataract."]}'),
  ('3c47ca2b-18','{"options": ["Fluorescein strips", "Cyclopentolate 0.5%", "Tropicamide 0.5%", "Phenylephrine 10%"], "correct": 3, "decode": "Avoid the high cardiovascular load: phenylephrine 10%. Low-strength tropicamide/cyclopentolate are preferred; fluorescein is not a dilator. ''Avoided'' = the 10% sympathomimetic.", "ow": ["A dye, not a dilator.", "A low-strength, acceptable option.", "The preferred pregnancy dilator.", "Correct. High cardiovascular load; avoided."]}'),
  ('d2931ccd-30','{"options": ["Low potency, low efficacy", "Low potency, high efficacy", "High potency, high efficacy", "High potency, low efficacy"], "correct": 2, "decode": "Split the sentence: ''maximum possible effect'' = high EFFICACY; ''at a low dose'' = high POTENCY. Both high, so pick the both-high option.", "ow": ["Would need a big dose for a small effect.", "Big effect but only at a high dose.", "Correct. Big effect at a small dose.", "Small dose but a low ceiling."]}'),
  ('04a25e9f-2a','{"options": ["Sublingual", "Oral", "Rectal", "Intravenous"], "correct": 3, "decode": "100% to systemic circulation = no absorption step = IV. Sublingual, oral and rectal all cross a membrane and lose fraction.", "ow": ["Bypasses first-pass but still absorbs, under 100%.", "Lowest, due to absorption and first-pass.", "Partial absorption only.", "Correct. Straight into the bloodstream."]}'),
  ('5e86735a-2p','{"options": ["Phenobarbital", "Tropicamide", "Atropine", "Penicillin"], "correct": 2, "decode": "The ''excreted unchanged + urine toxicity test'' fingerprint tags atropine. Penicillin is the renal-excretion trap but not the toxicity-test drug.", "ow": ["Hepatically metabolized; not the tested drug.", "A short-acting antimuscarinic, not the fingerprint.", "Correct. Excreted unchanged; basis of its urine toxicity test.", "Renally cleared (the trap) but not the toxicity-test drug."]}'),
  ('52a55d4c-2v','{"options": ["Potentiation", "Synergism", "Additive effect", "Antagonism"], "correct": 0, "decode": "0 + 1 > 1 is potentiation (an inactive drug boosts an active one). Synergism needs both active; additive is a plain sum.", "ow": ["Correct. Inactive X magnifies active Y.", "Requires both drugs to be active.", "Two active drugs simply summing.", "One drug reduces the other."]}'),
  ('35e3ddd2-19','{"options": ["Combines with the agonist to form an inactive compound", "Forms an irreversible covalent bond and cannot be displaced", "Reversibly competes at the same receptor and is overcome by more agonist", "Binds a different receptor to produce an opposite effect"], "correct": 2, "decode": "Match the definition to the word ''competitive'': same receptor, reversible, beaten by more agonist. Options with ''irreversible/covalent,'' ''forms a compound,'' or ''different receptor'' describe other antagonism types.", "ow": ["That is chemical antagonism.", "That is non-competitive antagonism.", "Correct. The competitive definition.", "That is physiologic antagonism."]}'),
  ('1388e0e3-2n','{"options": ["β2 receptors", "Nicotinic receptors", "α1 adrenergic receptors", "M3 muscarinic receptors"], "correct": 2, "decode": "Dilation WITH intact near vision means the ciliary muscle is untouched, so it is an α1 (dilator) drug, not an antimuscarinic (which would also cycloplege). ''Near vision preserved'' points to α1.", "ow": ["Not a pupil-dilating receptor.", "Ganglionic; not the iris dilator here.", "Correct. Dilates via the dilator, sparing accommodation.", "Blocking M3 would dilate AND cycloplege (blur near)."]}'),
  ('0848518f-2c','{"options": ["Argyll Robertson pupil", "Third nerve palsy", "Horner''s syndrome", "Adie''s tonic pupil"], "correct": 3, "decode": "Constriction to weak 0.1% pilocarpine is the Adie''s supersensitivity signature. Argyll Robertson, third nerve palsy and Horner''s do not show this dilute-pilocarpine response.", "ow": ["Light-near dissociation from neurosyphilis, not this test.", "A down-and-out eye with a fixed dilated pupil, different picture.", "A small pupil that fails to dilate to cocaine, not this.", "Correct. Denervation supersensitivity to 0.1% pilocarpine."]}'),
  ('343bdca6-1w','{"options": ["The affected pupil constricts with pilocarpine", "Both pupils dilate equally with hydroxyamphetamine", "The affected pupil dilates widely with 4% cocaine", "The affected pupil fails to dilate with 4% cocaine"], "correct": 3, "decode": "Confirmation = FAILS to dilate with cocaine (no NE to potentiate). Options with pilocarpine or hydroxyamphetamine are the wrong test or the localizing step.", "ow": ["That is the Adie''s test, not Horner''s.", "Hydroxyamphetamine localizes, and equal dilation is not the confirmer.", "A normal response, which rules Horner''s out.", "Correct. No NE to potentiate confirms Horner''s."]}'),
  ('06ed8871-2s','{"options": ["Tropicamide 1%", "Cyclopentolate 1%", "Atropine 1%", "Phenylephrine 2.5%"], "correct": 1, "decode": "Balancing strength and duration for routine cycloplegic refraction = cyclopentolate 1%. Tropicamide is too weak, atropine too long, phenylephrine has no cycloplegia.", "ow": ["Too weak a cycloplegic; it is the routine mydriatic.", "Correct. Reliable cycloplegia with manageable duration.", "Too long (up to 14 days) for routine use.", "A dilator with no cycloplegic action."]}'),
  ('2909e9ff-2e','{"options": ["Levobunolol", "Carteolol", "Timolol", "Betaxolol"], "correct": 3, "decode": "Asthma comorbidity = choose the cardio-selective (β1) blocker: betaxolol. The other three are non-selective and risk bronchospasm.", "ow": ["Non-selective; airway risk in asthma.", "Non-selective (with ISA); still airway risk.", "Non-selective, the classic asthma contraindication.", "Correct. Cardio-selective, spares the airways."]}'),
  ('b1fb8c37-2l','{"options": ["Acidic tissue ionizes the drug", "Bacteria metabolize the anesthetic", "Inflammation washes the drug away", "Infection destroys the sodium channels"], "correct": 0, "decode": "Same acid rule: infected tissue is acidic, ionizing the anesthetic so it cannot cross the nerve. The bacterial/washout options are not the mechanism.", "ow": ["Correct. The charged form cannot penetrate the nerve.", "Not a real mechanism.", "Not the reason it fails.", "The channels are intact; the drug just cannot reach them."]}'),
  ('535abec8-2h','{"options": ["Indocyanine green", "Rose bengal", "Trypan blue", "Fluorescein"], "correct": 1, "decode": "Early dry eye (KCS) devitalized cells = rose bengal (or lissamine). Fluorescein shows defects, not devitalized cells; ICG and trypan blue are unrelated.", "ow": ["A choroidal angiography dye.", "Correct. Stains devitalized cells in early KCS.", "A surgical capsule stain.", "Stains epithelial defects, not devitalized cells."]}'),
  ('f3b84c18-2c','{"options": ["Lidocaine and lissamine green", "Cocaine and rose bengal", "Tetracaine and ICG", "Proparacaine and fluorescein"], "correct": 3, "decode": "Goldmann needs an anesthetic PLUS fluorescein to see the mires: proparacaine + fluorescein. Any combo missing fluorescein or using cocaine is wrong.", "ow": ["Wrong anesthetic and wrong dye for the mires.", "Cocaine softens the cornea; rose bengal is not for mires.", "ICG is a choroidal dye, not for applanation.", "Correct. The standard Goldmann combination."]}'),
  ('da04b722-4i','{"options": ["Schirmer test", "TBUT", "Seidel test", "Jones I test"], "correct": 2, "decode": "A green stream from an incision against yellow-orange dye = positive Seidel (aqueous leak). TBUT/Schirmer/Jones assess tears or drainage, not wound leaks.", "ow": ["Measures tear production.", "Measures tear-film stability.", "Correct. A streaming leak of aqueous through the wound.", "Assesses lacrimal drainage."]}'),
  ('da5af682-1r','{"options": ["Esters are metabolized by plasma cholinesterase", "Esters have two i''s in their generic name", "Amides are metabolized by plasma cholinesterase", "Amides are shorter acting than esters"], "correct": 0, "decode": "Anchor the true facts: esters = plasma cholinesterase, amides = liver, esters have ONE i. Test each option against those rules.", "ow": ["Correct. Esters use plasma (pseudo)cholinesterase.", "False; esters have one i.", "No; amides are hepatic.", "Generally amides last longer, not shorter."]}'),
  ('6b6c4e72-1y','{"options": ["Beta blockers", "Alpha-2 agonists", "Carbonic anhydrase inhibitors", "Prostaglandin analogs"], "correct": 3, "decode": "UVEOSCLERAL outflow = prostaglandin analogs. Beta blockers, alpha-2s and CAIs all cut production instead.", "ow": ["Cut production.", "Cut production (plus minor outflow).", "Cut production.", "Correct. Raise uveoscleral outflow."]}'),
  ('7ba410f0-45','{"options": ["Swelling of the ciliary body", "Pupillary block from iris bombe", "Increased aqueous production", "GAG buildup in the meshwork"], "correct": 3, "decode": "Steroid-response glaucoma is OUTFLOW obstruction: glycosaminoglycans accumulate in the trabecular meshwork. It is not increased production or pupillary block.", "ow": ["Not the steroid mechanism.", "That is angle-closure, not steroid response.", "Steroids obstruct outflow, they do not boost production.", "Correct. GAG accumulation reduces trabecular outflow."]}'),
  ('d64f8985-1f','{"options": ["Polymyxin B", "Penicillin", "Gentamicin", "Tetracycline"], "correct": 3, "decode": "Trachoma DOC = tetracycline (or azithromycin). Polymyxin/penicillin/gentamicin are not the chlamydial choice.", "ow": ["A gram-negative surface agent, not for trachoma.", "Ineffective against chlamydia.", "An aminoglycoside, not the trachoma DOC.", "Correct. The drug of choice for trachoma."]}'),
  ('508ffcf8-1s','{"options": ["Timolol", "Latanoprost", "Acetazolamide", "Pilocarpine"], "correct": 2, "decode": "Sulfa allergy = avoid the sulfonamide, acetazolamide (and topical dorzolamide/brinzolamide). Timolol/latanoprost/pilocarpine are not sulfonamides.", "ow": ["A beta blocker, not a sulfonamide.", "A prostaglandin, not a sulfonamide.", "Correct. A sulfonamide to avoid in sulfa allergy.", "A miotic, not a sulfonamide."]}'),
  ('6cf358d2-2i','{"options": ["Betamethasone", "Prednisolone", "Fluorometholone", "Dexamethasone"], "correct": 2, "decode": "When you must use a steroid in a pressure-prone eye, pick the least IOP-raising one: fluorometholone. The potent steroids raise IOP more.", "ow": ["A potent steroid, more IOP rise.", "Raises IOP more.", "Correct. Least IOP rise.", "A potent steroid, more IOP rise."]}'),
  ('c764dea6-39','{"options": ["Bull''s-eye maculopathy", "Cotton-wool spots", "Disc neovascularization", "Cherry-red spot"], "correct": 0, "decode": "Hydroxychloroquine + central vision loss = bull''s-eye maculopathy. Cotton-wool, neovascularization and cherry-red are vascular signs, not the antimalarial toxicity.", "ow": ["Correct. The hydroxychloroquine signature.", "Ischemic infarcts (diabetes/hypertension).", "An ischemic retinopathy sign.", "CRAO or storage disease."]}'),
  ('b9c2e84b-2b','{"options": ["Chloropsia", "Xanthopsia", "Cyanopsia", "Erythropsia"], "correct": 1, "decode": "Yellow (''snowy'') vision on digitalis = xanthopsia. Decode the roots: xanth- yellow, chlor- green, cyan- blue, erythr- red.", "ow": ["Green vision, not yellow.", "Correct. Yellow vision, the digitalis sign.", "Blue vision.", "Red vision."]}'),
  ('e7ecf97c-2s','{"options": ["Posterior subcapsular cataract", "Acute angle-closure glaucoma", "Pigmentary retinopathy", "Optic neuritis, red-green defect"], "correct": 3, "decode": "Ethambutol hits the optic nerve: dimming vision plus red-green loss. The cataract/angle/pigmentary options are other drug toxicities.", "ow": ["That is steroids.", "That is anticholinergics.", "That is thioridazine/phenothiazines.", "Correct. The ethambutol optic neuropathy."]}'),
  ('a07a5df2-1z','{"options": ["Cyclopentolate 2%", "Atropine 1%", "Tropicamide 0.5%", "Phenylephrine 10%"], "correct": 2, "decode": "Pregnancy dilation = the shortest, lowest-load agent: tropicamide 0.5%. Cyclopentolate 2%, atropine and phenylephrine 10% carry more exposure.", "ow": ["Longer, stronger; more exposure.", "Very long-acting; most exposure.", "Correct. Shortest-acting, least load.", "High cardiovascular load; avoided."]}'),
  ('d7424c05-28','{"options": ["Acute angle-closure glaucoma", "An allergic drug reaction", "Local anesthetic overdose", "Anticholinergic CNS toxicity"], "correct": 3, "decode": "Cyclopentolate is an antimuscarinic, so systemic CNS ANTICHOLINERGIC toxicity explains disorientation and hallucination. Not angle-closure, allergy, or anesthetic overdose.", "ow": ["Would cause pain/red eye, not this CNS picture.", "This is dose toxicity, not allergy.", "Cyclopentolate is not an anesthetic.", "Correct. Central antimuscarinic toxicity."]}'),
  ('601ac2c4-1u','{"options": ["Sympathomimetic", "Cycloplegia", "Parasympatholytic", "Miosis"], "correct": 3, "decode": "Match the definition to the vocabulary word. Pupil constriction = miosis. The other terms name dilation, accommodation loss, or a drug class, not constriction.", "ow": ["That dilates, the opposite of constriction.", "Loss of accommodation, not pupil size.", "Blocks parasympathetics, causing dilation.", "Correct. The word for pupil constriction."]}'),
  ('3521db6e-1v','{"options": ["Sympathomimetic", "Parasympatholytic", "Cycloplegia", "Miosis"], "correct": 2, "decode": "Definition-to-term: paralysis of accommodation = cycloplegia (cyclo = ciliary). The others name pupil size or a drug class.", "ow": ["An adrenergic action, not accommodation loss.", "The mechanism that causes cycloplegia, but not the named effect.", "Correct. Ciliary paralysis and loss of accommodation.", "Pupil constriction, not accommodation."]}'),
  ('049a48bd-1v','{"options": ["Sympathomimetic", "Cycloplegia", "Miosis", "Parasympatholytic"], "correct": 0, "decode": "Adrenergic agonist that dilates but spares accommodation = sympathomimetic (like phenylephrine). Cycloplegia and miosis are effects, not the class.", "ow": ["Correct. Adrenergic agonist; dilates without cycloplegia.", "An effect (accommodation loss), not this class.", "Pupil constriction, the opposite of dilation.", "Also dilates, but WITH cycloplegia, so not this."]}'),
  ('3efd1f80-1y','{"options": ["Sympathomimetic", "Agonist", "Cycloplegia", "Miosis"], "correct": 1, "decode": "Definition match: binds AND activates = agonist (''push your muscle''). The pupil/accommodation words are effects, not this term.", "ow": ["A specific adrenergic agonist, but ''agonist'' is the general term asked.", "Correct. Binds and activates the receptor.", "An effect, not a binding term.", "An effect, not a binding term."]}'),
  ('6f61ff38-1p','{"options": ["Cycloplegia", "Antagonist", "Sympathomimetic", "Miosis"], "correct": 1, "decode": "Blocks the receptor (''release the opponent'') = antagonist. The other options are effects or a specific agonist class.", "ow": ["An effect, not a binding term.", "Correct. Binds and blocks the receptor.", "An agonist class, the opposite of blocking.", "An effect, not a binding term."]}'),
  ('0d584169-21','{"options": ["Denervation supersensitivity", "Cycloplegic action", "Sympathomimetic effect", "Pharmacologic miosis"], "correct": 0, "decode": "The reason a weak dose works is denervation supersensitivity (the denervated muscle over-responds). The other options are effects or classes, not the mechanism.", "ow": ["Correct. The denervated sphincter over-responds to weak agonist.", "Unrelated to the supersensitivity mechanism.", "Adie''s involves parasympathetic denervation, not this.", "Describes the effect, not why weak doses work."]}'),
  ('9d4bdbcd-1z','{"options": ["Miosis", "Cycloplegia", "Sympathomimetic", "ISA"], "correct": 3, "decode": "''Partial agonist'' property of a beta blocker = ISA (intrinsic sympathomimetic activity). The pupil/accommodation words are unrelated.", "ow": ["A pupil effect, unrelated.", "Accommodation loss, unrelated.", "Too general; the specific term is ISA.", "Correct. Intrinsic sympathomimetic activity (partial agonism)."]}'),
  ('af74844c-1w','{"options": ["Miosis", "MSA", "Cycloplegia", "Sympathomimetic"], "correct": 1, "decode": "The membrane-stabilizing (local-anesthetic) property = MSA. Do not confuse it with ISA (partial agonism). Match the property to its abbreviation.", "ow": ["A pupil effect, unrelated.", "Correct. Membrane-stabilizing (local anesthetic) activity.", "Accommodation loss, unrelated.", "An agonist property, not the anesthetic one."]}'),
  ('63660fbe-1t','{"options": ["Cycloplegia", "Sympathomimetic", "Decongestant", "Miosis"], "correct": 2, "decode": "An α1 agonist that whitens the eye = decongestant (the -zolines: naphazoline, tetrahydrozoline). The other terms are effects or too general.", "ow": ["Accommodation loss, unrelated to vasoconstriction.", "True but too general; the specific use is decongestant.", "Correct. α1 vasoconstrictor that blanches the conjunctiva.", "Pupil constriction, not vessel blanching."]}'),
  ('12b722dd-28','{"options": ["Non-ionized form", "Ester anesthetic", "Fluorescein", "Amide anesthetic"], "correct": 1, "decode": "Match the definition to the term: plasma-cholinesterase metabolism and shorter action = ester anesthetic. The dye and ''form'' options are not classes.", "ow": ["The form that crosses the nerve, not a class.", "Correct. Metabolized by plasma cholinesterase; shorter acting.", "A dye, not an anesthetic class.", "Amides are liver-metabolized and longer acting."]}'),
  ('8f4d2742-1s','{"options": ["Ester anesthetic", "Fluorescein", "Non-ionized form", "Amide anesthetic"], "correct": 3, "decode": "Definition-to-term: liver-metabolized and longer acting = amide (two i''s). Esters are plasma-metabolized and shorter.", "ow": ["Plasma-metabolized and shorter, the opposite.", "A dye, not an anesthetic class.", "The membrane-crossing form, not a class.", "Correct. Liver-metabolized, longer acting."]}'),
  ('8d585ea2-1u','{"options": ["Fluorescein", "Amide anesthetic", "Non-ionized form", "Ester anesthetic"], "correct": 2, "decode": "Only the NON-ionized (uncharged) form crosses the nerve membrane. The named classes and the dye are not ''the form'' asked.", "ow": ["A dye, not a drug form.", "A class, not the membrane-crossing form.", "Correct. The uncharged form penetrates the nerve.", "A class, not the form."]}'),
  ('7051c14e-1y','{"options": ["Ester anesthetic", "Fluorescein", "Amide anesthetic", "Non-ionized form"], "correct": 1, "decode": "Definition match: stains epithelial defects and glows under cobalt blue = fluorescein. The anesthetic classes and ''form'' are not dyes.", "ow": ["An anesthetic class, not a dye.", "Correct. Stains defects, glows under cobalt blue.", "An anesthetic class, not a dye.", "A drug form, not a dye."]}'),
  ('fb46fd6d-1x','{"options": ["Amide anesthetic", "Ester anesthetic", "Rose bengal", "Non-ionized form"], "correct": 2, "decode": "Devitalized cells + mucus + early dry eye = rose bengal. Fluorescein does defects; the anesthetic terms are irrelevant.", "ow": ["An anesthetic class, not a dye.", "An anesthetic class, not a dye.", "Correct. Stains devitalized cells/mucus in early dry eye.", "A drug form, not a dye."]}'),
  ('7401bd66-20','{"options": ["Non-ionized form", "Amide anesthetic", "Devitalized cells", "Ester anesthetic"], "correct": 2, "decode": "The target these dyes stain = devitalized cells (and mucus). The anesthetic classes and ''form'' are not tissue targets.", "ow": ["A drug form, not a tissue.", "An anesthetic class, not a tissue target.", "Correct. What rose bengal / lissamine stain.", "An anesthetic class, not a tissue target."]}'),
  ('22d1bb90-1v','{"options": ["Ester anesthetic", "Quenching", "Non-ionized form", "Amide anesthetic"], "correct": 1, "decode": "Fluorescein self-QUENCHES (stops glowing) at high pH (>8) or high concentration. The anesthetic terms and ''form'' do not fit this fluorescence behavior.", "ow": ["An anesthetic class, unrelated to fluorescence.", "Correct. Fluorescein self-quenches at high pH or concentration.", "A drug form, not this phenomenon.", "An anesthetic class, unrelated."]}'),
  ('fa49125f-20','{"options": ["TBUT", "Amide anesthetic", "Ester anesthetic", "Non-ionized form"], "correct": 0, "decode": "Time to first dry spot = tear break-up time (TBUT), the tear-film stability test. The anesthetic terms and ''form'' are not tear tests.", "ow": ["Correct. Time to first dry spot; measures tear-film stability.", "An anesthetic class, not a tear test.", "An anesthetic class, not a tear test.", "A drug form, not a tear test."]}'),
  ('5c665ebb-21','{"options": ["Amide anesthetic", "Ester anesthetic", "Non-ionized form", "Applanation"], "correct": 3, "decode": "Goldmann tonometry that flattens the cornea and needs fluorescein plus anesthetic = applanation. The anesthetic classes and ''form'' are not the technique.", "ow": ["An anesthetic class, not the technique.", "An anesthetic class, not the technique.", "A drug form, not the technique.", "Correct. Goldmann applanation uses fluorescein plus anesthetic."]}'),
  ('75c6b88c-1z','{"options": ["Osmotic agent", "Uveoscleral outflow", "Carbonic anhydrase inhibitor", "Prostaglandin analog"], "correct": 2, "decode": "Definition match: cuts secretion AND is a sulfonamide = carbonic anhydrase inhibitor. Osmotic/outflow/prostaglandin do not fit both clues.", "ow": ["Pulls water, not a sulfonamide secretion-cutter.", "An outflow route, not a production-cutter.", "Correct. Sulfonamide that cuts aqueous secretion.", "An outflow drug, not a sulfonamide."]}'),
  ('e8f1dc6a-1w','{"options": ["Osmotic agent", "Uveoscleral outflow", "Prostaglandin analog", "Carbonic anhydrase inhibitor"], "correct": 0, "decode": "Pulling water out of the eye = osmotic agent (mannitol). The outflow and production terms do not dehydrate the vitreous.", "ow": ["Correct. Dehydrates the vitreous to lower IOP acutely.", "An outflow route, not water-pulling.", "An outflow drug, not an osmotic.", "Cuts production, does not pull water."]}'),
  ('de55e04b-22','{"options": ["Osmotic agent", "Uveoscleral outflow", "Prostaglandin analog", "Carbonic anhydrase inhibitor"], "correct": 1, "decode": "The route that BYPASSES the meshwork and is the prostaglandin target = uveoscleral outflow. The other terms are agents, not that route.", "ow": ["A drug type, not an outflow route.", "Correct. The prostaglandin route that bypasses the meshwork.", "The drug, but the term asked is the route.", "A production-cutter, not an outflow route."]}'),
  ('249aa85c-22','{"options": ["Corticosteroid", "Carbonic anhydrase inhibitor", "Prostaglandin analog", "Osmotic agent"], "correct": 0, "decode": "Inhibits phospholipase A2 AND risks glaucoma/PSC cataract = corticosteroid. The glaucoma-drug terms do not fit that mechanism or those side effects.", "ow": ["Correct. Blocks phospholipase A2; risks glaucoma and PSC cataract.", "A production-cutter, not an anti-inflammatory.", "An outflow drug, not a steroid.", "A water-puller, not an anti-inflammatory."]}'),
  ('cfb28120-1m','{"options": ["NSAID", "Prostaglandin analog", "Osmotic agent", "Carbonic anhydrase inhibitor"], "correct": 0, "decode": "Inhibits cyclooxygenase and does NOT change IOP = NSAID. Steroids (which raise IOP) are the contrast; the glaucoma terms do not fit.", "ow": ["Correct. COX inhibitor with no IOP effect.", "A glaucoma drug, not a COX inhibitor.", "A water-puller, unrelated.", "A production-cutter, unrelated."]}'),
  ('34c3bae1-22','{"options": ["Osmotic agent", "Phospholipase A2", "Carbonic anhydrase inhibitor", "Prostaglandin analog"], "correct": 1, "decode": "The upstream enzyme whose blockade stops BOTH prostaglandins and leukotrienes = phospholipase A2 (the steroid target). The drug-class terms are not enzymes.", "ow": ["A drug type, not an enzyme.", "Correct. Upstream target; blocking it stops both pathways.", "A drug class, not this enzyme.", "A drug, not the enzyme target."]}'),
  ('691d64bd-1w','{"options": ["Prostaglandin analog", "Osmotic agent", "Carbonic anhydrase inhibitor", "Steroid-response glaucoma"], "correct": 3, "decode": "IOP rise after weeks of steroids in an open angle = steroid-response glaucoma. The drug-class terms do not name this condition.", "ow": ["A drug, not this condition.", "A drug, not this condition.", "A drug, not this condition.", "Correct. Delayed IOP rise from steroids."]}'),
  ('cf70d139-1y','{"options": ["Aminoglycoside", "Prostaglandin analog", "Carbonic anhydrase inhibitor", "Osmotic agent"], "correct": 0, "decode": "Gram-negative cover with oto/nephrotoxicity beyond 5 days = aminoglycoside. The glaucoma terms do not fit an antibiotic class.", "ow": ["Correct. Gram-negative cover; oto/nephrotoxic with prolonged use.", "A glaucoma drug, not an antibiotic.", "A glaucoma drug, not an antibiotic.", "A glaucoma drug, not an antibiotic."]}'),
  ('1344f3e7-1s','{"options": ["Osmotic agent", "Mast-cell stabilizer", "Carbonic anhydrase inhibitor", "Prostaglandin analog"], "correct": 1, "decode": "Cromolyn prevents mast-cell calcium influx and degranulation = mast-cell stabilizer (allergy). The glaucoma terms do not fit.", "ow": ["A glaucoma drug type, unrelated.", "Correct. Cromolyn prevents mast-cell degranulation.", "A glaucoma drug, unrelated.", "A glaucoma drug, unrelated."]}'),
  ('e2fae67e-1r','{"options": ["Xanthopsia", "Bull''s-eye maculopathy", "Amphiphilic drug", "Pseudotumor cerebri"], "correct": 0, "decode": "Definition-to-term: yellow vision from digitalis = xanthopsia. The maculopathy/drug-property/ICP terms are different concepts.", "ow": ["Correct. Yellow vision (digitalis).", "A chloroquine retinal sign, not a color term.", "A drug property, not a symptom.", "Raised intracranial pressure, not yellow vision."]}'),
  ('bab6be05-1p','{"options": ["Bull''s-eye maculopathy", "Pseudotumor cerebri", "Xanthopsia", "Amphiphilic drug"], "correct": 0, "decode": "Late chloroquine retina = bull''s-eye maculopathy. The color/drug-property/ICP terms do not name that finding.", "ow": ["Correct. The late chloroquine retinal finding.", "A vitamin A/OCP/tetracycline effect.", "Yellow vision (digitalis).", "A drug property, not a retinal finding."]}'),
  ('3695a536-20','{"options": ["Amphiphilic drug", "Pseudotumor cerebri", "Xanthopsia", "Bull''s-eye maculopathy"], "correct": 1, "decode": "Papilledema from vitamin A excess, OCPs, tetracycline = pseudotumor cerebri. The color/finding/property terms do not fit.", "ow": ["A drug property, not a condition.", "Correct. Raised ICP with papilledema.", "Yellow vision, unrelated.", "A chloroquine sign, not this."]}'),
  ('abd256e7-1t','{"options": ["Bull''s-eye maculopathy", "Xanthopsia", "Pseudotumor cerebri", "Amphiphilic drug"], "correct": 3, "decode": "A drug that binds lipids and deposits as whorl keratopathy = amphiphilic drug (CATI). The symptom/condition terms are not drug properties.", "ow": ["A retinal sign, not a drug property.", "A color symptom, not a drug property.", "A condition, not a drug property.", "Correct. Lipid-binding drugs cause verticillata."]}'),
  ('0f39b618-1r','{"options": ["Bull''s-eye maculopathy", "FDA Category C", "Pseudotumor cerebri", "Xanthopsia"], "correct": 1, "decode": "Essentially all ocular drugs are pregnancy FDA Category C. The retinal/symptom terms are not a pregnancy class.", "ow": ["A retinal sign, not a pregnancy class.", "Correct. The default pregnancy class for ocular drugs.", "A condition, not a class.", "A symptom, not a class."]}'),
  ('334f6a8a-1t','{"options": ["Idiosyncratic reaction", "Xanthopsia", "Pseudotumor cerebri", "Bull''s-eye maculopathy"], "correct": 0, "decode": "An illogical, unexpected response (a mydriatic causing miosis) = idiosyncratic reaction. The retinal/symptom/ICP terms do not describe this.", "ow": ["Correct. An unpredictable, paradoxical response.", "A color symptom, unrelated.", "A condition, unrelated.", "A retinal sign, unrelated."]}'),
  ('186e14c4-1x','{"options": ["Xanthopsia", "Pseudotumor cerebri", "Bull''s-eye maculopathy", "Tritan defect"], "correct": 3, "decode": "The earliest color change in many drug toxicities is a TRITAN (blue-yellow) defect. The other terms are signs or conditions, not a color-defect type.", "ow": ["Yellow vision (specifically digitalis), not the general early sign.", "A condition, not a color defect.", "A retinal sign, not a color defect.", "Correct. The early blue-yellow color change."]}'),
  ('55aeabf2-1w','{"options": ["Xanthopsia", "Bull''s-eye maculopathy", "Polypharmacy", "Pseudotumor cerebri"], "correct": 2, "decode": "Many concurrent drugs = polypharmacy, which raises interaction and toxicity risk in the elderly. The retinal/symptom/ICP terms do not fit.", "ow": ["A color symptom, unrelated.", "A retinal sign, unrelated.", "Correct. Multiple drugs raising interaction/toxicity risk.", "A condition, unrelated."]}'),
  ('b3d708c8-1m','{"options": ["Retrobulbar neuritis", "Pseudotumor cerebri", "Bull''s-eye maculopathy", "Xanthopsia"], "correct": 0, "decode": "Ethambutol/INH optic toxicity is a RETROBULBAR neuritis (inflammation behind the globe, normal disc early). The color/condition terms do not name it.", "ow": ["Correct. The ethambutol/INH optic toxicity pattern.", "A vitamin A/OCP/tetracycline effect.", "A chloroquine sign.", "Yellow vision (digitalis)."]}'),
  ('130144a0-1z','{"options": ["Both dilate", "Both constrict", "1 constricts, 2 dilates", "2 constricts, 1 dilates"], "correct": 2, "decode": "Same number rule: 1 constricts, 2 dilates. This single line sorts α1 (constrict) versus β2 (dilate) across the autonomic table.", "ow": ["The 1-receptors constrict.", "The 2-receptors dilate.", "Correct. The autonomic number rule.", "Reversed."]}'),
  ('c0a05e0e-1f','{"options": ["Atropine, scopolamine, homatropine, tropicamide, cyclopentolate", "Cyclopentolate, atropine, tropicamide, homatropine, scopolamine", "Atropine, homatropine, scopolamine, cyclopentolate, tropicamide", "Tropicamide, cyclopentolate, scopolamine, homatropine, atropine"], "correct": 2, "decode": "Order by strength: Atropine > Homatropine > Scopolamine > Cyclopentolate > Tropicamide (''A Home So Cool Today''). Atropine must be first and tropicamide last, which eliminates the rest.", "ow": ["Right ends, but the middle order and tail are wrong.", "Does not start with the strongest.", "Correct. Strongest to weakest.", "Reversed (weakest first)."]}'),
  ('82cbc866-3m','{"options": ["0.1% tropicamide", "0.1% atropine", "0.1% pilocarpine", "0.1% epinephrine"], "correct": 3, "decode": "Horner''s is a denervated DILATOR, so a weak sympathomimetic (0.1% epinephrine) dilates it. Pair it with Adie''s (0.1% pilocarpine constricts). Read which muscle is denervated.", "ow": ["An antimuscarinic, not the supersensitivity agent for the dilator.", "Antimuscarinic; not the Horner''s confirmer.", "That is the Adie''s test (sphincter), not Horner''s.", "Correct. Weak adrenergic dilates the supersensitive Horner''s dilator."]}'),
  ('df8c909e-1f','{"options": ["Beta blocker", "An alpha-2 agonist", "AChE inhibitor", "Antimuscarinic"], "correct": 1, "decode": "Suffix decoder: -onidine = α2 agonist (brimonidine, apraclonidine). Do not confuse with -olol (beta blocker) or -zoline (α1 decongestant).", "ow": ["That is the -olol ending.", "Correct. -onidine tags the α2 agonists.", "That is -stigmine.", "That is -tropine (atropine, homatropine)."]}'),
  ('69a4f2c9-1f','{"options": ["Alpha-1 decongestant", "AChE inhibitor", "Alpha-2 agonist", "Antimuscarinic"], "correct": 0, "decode": "Suffix decoder: -zoline = α1 decongestant (naphazoline, tetrahydrozoline), the get-the-red-out drops. Do not confuse it with -onidine (α2).", "ow": ["Correct. -zoline marks the α1 vasoconstrictor decongestants.", "That is -stigmine.", "That is -onidine.", "That is -tropine."]}'),
  ('8aea7f8f-1h','{"options": ["Acetylcholinesterase inhibitors", "Alpha-1 decongestants", "Antimuscarinics", "Beta blockers"], "correct": 0, "decode": "Suffix decoder: -stigmine = AChE inhibitor (physostigmine, neostigmine). It raises ACh; the opposite -tropine blocks it.", "ow": ["Correct. -stigmine tags the AChE inhibitors.", "That is -zoline.", "That is -tropine.", "That is -olol."]}'),
  ('29a6af0d-27','{"options": ["0.1%", "0.5%", "2.5%", "10%"], "correct": 2, "decode": "Phenylephrine 2.5% prevents and reverses the echothiophate iris cysts. The 10% is avoided (cardiovascular load) and 0.1/0.5% are too weak.", "ow": ["Too weak to reverse the cysts.", "Still too weak.", "Correct. The standard strength that prevents and reverses iris cysts.", "Avoided for its cardiovascular load; not the standard here."]}'),
  ('5bef050a-1o','{"options": ["A carbonic anhydrase inhibitor", "A prostaglandin analog", "A miotic", "A beta blocker"], "correct": 1, "decode": "Cap-color code: turquoise = prostaglandin. Recall the map (orange CAI, green miotic, yellow/blue beta blocker, turquoise prostaglandin, red mydriatic).", "ow": ["That is the orange cap.", "Correct. Turquoise marks prostaglandins.", "That is the green cap.", "That is the yellow/blue cap."]}'),
  ('9366abc4-15','{"options": ["Steroid", "Mydriatic", "Beta blocker", "Miotic"], "correct": 3, "decode": "Cap-color code: green = miotic (pilocarpine). Red is the mydriatic, its mirror. Learn green/red as a pair.", "ow": ["That is the pink cap.", "That is the red cap.", "That is the yellow/blue cap.", "Correct. Green marks the miotics."]}'),
  ('ffc5fe93-3m','{"options": ["Kidney", "Lungs", "Liver", "Thyroid"], "correct": 0, "decode": "CAI side effects (paresthesia, metallic taste, stones) come from inhibiting carbonic anhydrase in the KIDNEY. The other organs are not the source.", "ow": ["Correct. Renal carbonic anhydrase inhibition causes those effects.", "Not the source of these side effects.", "Not the source.", "Not involved."]}'),
  ('f56933cd-2e','{"options": ["Two down, three out", "Three down, two out", "Four down, one out", "One down, four out"], "correct": 1, "decode": "IOP = made minus drained. Three classes cut production (beta blockers, alpha-2, CAIs); two boost outflow (prostaglandins, miotics). ''Three down, two out.''", "ow": ["Reversed count.", "Correct. Three cut production, two boost outflow.", "Miscounts the outflow drugs.", "Miscounts the production-cutters."]}'),
  ('664d8e13-2c','{"options": ["Alkaline", "Protein-bound", "Acidic", "Ionized"], "correct": 0, "decode": "The absorbable chain is ''lipid = uncharged = alkaline (basic) = absorbable.'' Acidic/ionized are the opposite end, which is why anesthetics fail in acidic infected tissue.", "ow": ["Correct. A basic, non-ionized environment favors absorption.", "Bound drug cannot cross.", "Ionizes the drug and blocks penetration.", "The charged, non-absorbable form."]}'),
  ('6a2f1028-2m','{"options": ["Lung", "Immature liver", "Brain", "Kidney"], "correct": 1, "decode": "Special-population toxicity is a one-organ story: children = immature LIVER (cannot clear drugs), elderly = failing liver/kidney, pregnancy = shared fetus. For kids, pick the liver.", "ow": ["Not the pediatric clearance organ.", "Correct. Poor hepatic clearance in children.", "The site of toxicity, not the clearance organ.", "The elderly story; for children it is the liver."]}'),
  ('2f54034e-1k','{"options": ["Heart", "Liver", "Kidney", "Spleen"], "correct": 1, "decode": "Metabolism = liver; excretion = kidney. Odd organs (heart, spleen) are noise.", "ow": ["No drug-metabolizing role.", "Correct. The principal biotransformation site (P-450).", "The excretion organ, not metabolism.", "Filters blood cells, not drugs."]}'),
  ('8b2324f2-28','{"options": ["Lung", "Kidney", "Pancreas", "Liver"], "correct": 1, "decode": "Elimination/excretion = kidney (urine). Liver is the metabolism trap here; pick the excretory organ.", "ow": ["Excretes volatile gases only.", "Correct. The main route for drugs and metabolites (urine).", "Makes digestive enzymes, not drug excretion.", "Metabolizes, then hands off to the kidney."]}'),
  ('170e9ff2-1y','{"options": ["Antagonist", "Inhibitor", "Agonist", "Antidote"], "correct": 2, "decode": "Two verbs decide it: ''binds AND produces a response'' = agonist. Binds and blocks = antagonist. Read the second verb.", "ow": ["Binds but blocks the response.", "Reduces activity; not the receptor-activation term.", "Correct. Binds and activates the receptor.", "Reverses a poison; not a receptor definition."]}'),
  ('b155d35c-1t','{"options": ["Agonist", "Hormone", "Antagonist", "Enzyme"], "correct": 2, "decode": "''Binds but blocks'' is the antagonist definition, the mirror of agonist. Enzyme and hormone are not receptor-blocking terms.", "ow": ["Binds and activates, the opposite.", "A signaling molecule, not this definition.", "Correct. Occupies the receptor without activating it.", "A catalyst, not a receptor blocker."]}'),
  ('01e4bee7-22','{"options": ["Expiration date", "Color", "Potency", "Solubility only"], "correct": 2, "decode": "''Amount required for an effect'' = potency (dose sensitivity). Do not confuse it with efficacy (maximum effect).", "ow": ["A shelf-life property, unrelated.", "Irrelevant to dose-response.", "Correct. Defined by the dose needed.", "Affects absorption, not the potency definition."]}'),
  ('8e09da7b-1f','{"options": ["Half-life", "Efficacy", "Toxicity", "Potency"], "correct": 1, "decode": "''Maximum effect'' = efficacy (the ceiling). Potency is how little you need. Pick the ceiling term.", "ow": ["An elimination time, not an effect size.", "Correct. The greatest achievable effect.", "A harmful effect, not the therapeutic ceiling.", "The dose needed, not the maximum effect."]}'),
  ('5811691b-29','{"options": ["Duration of action", "Onset time", "Peak time", "Half-life"], "correct": 3, "decode": "''Decrease by 50%'' literally spells half-life. The 50% is the giveaway; onset, peak and duration describe other points on the curve.", "ow": ["How long the effect lasts, not a halving time.", "Time to first effect.", "Time to maximum concentration.", "Correct. Time for concentration to fall by half."]}'),
  ('0ce38cea-28','{"options": ["Drug tolerance", "Therapeutic effect", "Side effect/adverse effect", "Placebo effect"], "correct": 2, "decode": "''Unwanted but predictable at a normal dose'' = side/adverse effect. Placebo (inert), therapeutic (intended) and tolerance (waning) do not fit.", "ow": ["A falling response over time, not an unwanted effect.", "The intended benefit.", "Correct. An expected, unwanted effect at a normal dose.", "A response to an inert treatment."]}'),
  ('8d859918-1x','{"options": ["Metabolite", "Toxin", "Antigen", "Drug"], "correct": 3, "decode": "''Given to produce a therapeutic effect'' = drug, by definition. Toxin harms; antigen triggers immunity; metabolite is a breakdown product.", "ow": ["A product of biotransformation, not the given substance.", "Causes harm, the opposite intent.", "Provokes an immune response.", "Correct. A substance given for a therapeutic effect."]}'),
  ('11aa6f79-u','{"options": ["Two drugs are always chemically identical", "A patient refuses medication", "A drug has no effect", "One drug alters the effect of another drug"], "correct": 3, "decode": "''Interaction'' = one drug changing another''s effect. Identical chemistry, no effect, or refusal are not interactions.", "ow": ["Identity is not interaction.", "A compliance issue, not an interaction.", "Absence of effect is not interaction.", "Correct. The definition of a drug interaction."]}'),
  ('4afd5e11-1z','{"options": ["Timolol", "Pilocarpine", "Tropicamide", "Brimonidine"], "correct": 2, "decode": "''Dilate for exam'' = tropicamide (short mydriatic). The glaucoma drugs (timolol, brimonidine) lower IOP and pilocarpine constricts, so none dilate.", "ow": ["A beta blocker; it does not dilate.", "A miotic; it constricts.", "Correct. Short-acting mydriatic for dilation.", "An α2 agonist for IOP, not a dilator."]}'),
  ('f7a07e4b-v','{"options": ["Carbonic anhydrase inhibitor", "Prostaglandin analog", "Beta blocker", "Muscarinic antagonist"], "correct": 3, "decode": "Tropicamide dilates by BLOCKING the sphincter, so it is a muscarinic antagonist (anticholinergic). The glaucoma classes do not dilate.", "ow": ["A production-cutter, not a dilator.", "An outflow drug, not a dilator.", "Lowers IOP, does not dilate.", "Correct. Blocks the sphincter to dilate."]}'),
  ('c530d60c-g','{"options": ["Beta blocker", "Prostaglandin analog", "Alpha-2 antagonist", "Muscarinic agonist"], "correct": 3, "decode": "Pilocarpine constricts, the opposite of tropicamide, so it is a muscarinic AGONIST. The adrenergic/prostaglandin options do not fit a miotic.", "ow": ["A production-cutter, not a miotic agonist.", "An outflow drug, not a cholinergic.", "Not pilocarpine''s class.", "Correct. Stimulates the sphincter (miosis) and ciliary muscle."]}'),
  ('ae8afb3a-k','{"options": ["Miosis and accommodation", "Mydriasis and cycloplegia", "Mydriasis only", "Cycloplegia only"], "correct": 0, "decode": "A muscarinic agonist contracts the sphincter (miosis) and the ciliary muscle (accommodation). Mydriasis and cycloplegia are the OPPOSITE (antimuscarinic) effects.", "ow": ["Correct. Sphincter and ciliary contraction.", "That is atropine''s antimuscarinic profile.", "Pilocarpine constricts, not dilates.", "It causes accommodation, not paralysis."]}'),
  ('c3a5c4c5-2j','{"options": ["Atropine", "Tropicamide", "Phenylephrine", "Latanoprost"], "correct": 3, "decode": "''Increases uveoscleral outflow'' is the prostaglandin signature = latanoprost. Atropine/tropicamide/phenylephrine are pupil drugs, not IOP-outflow agents.", "ow": ["An antimuscarinic dilator, not an outflow drug.", "A mydriatic, not an IOP drug.", "A dilator, not an outflow drug.", "Correct. Prostaglandin that raises uveoscleral outflow."]}'),
  ('1b22fb26-y','{"options": ["Anticholinergic", "Miotic", "Prostaglandin analog", "Beta blocker"], "correct": 2, "decode": "The -prost stem = prostaglandin analog. Not anticholinergic, miotic, or beta blocker.", "ow": ["That is atropine/tropicamide.", "That is pilocarpine.", "Correct. The -prost ending marks it.", "That is the -olol drugs."]}'),
  ('87668898-1t','{"options": ["Timolol", "Latanoprost", "Tropicamide", "Pilocarpine"], "correct": 0, "decode": "The -olol ending marks a beta blocker: timolol. Latanoprost (prostaglandin), tropicamide (mydriatic) and pilocarpine (miotic) are other classes.", "ow": ["Correct. The -olol beta blocker for IOP.", "A prostaglandin analog.", "A mydriatic.", "A miotic."]}'),
  ('6c2a0afe-s','{"options": ["Dilating the pupil", "Decreasing aqueous humor production", "Increasing aqueous humor production", "Increasing accommodation"], "correct": 1, "decode": "Beta blockade turns the aqueous tap DOWN (less production). Pupil/accommodation options are wrong; ''increasing production'' is the opposite.", "ow": ["Timolol does not dilate.", "Correct. Beta blockade cuts secretion.", "The opposite; that would raise IOP.", "Unrelated to beta blockade."]}'),
  ('7737ebb2-1e','{"options": ["Latanoprost", "Timolol", "Dorzolamide", "Tropicamide"], "correct": 2, "decode": "The -zolamide ending marks a carbonic anhydrase inhibitor: dorzolamide. Latanoprost (prostaglandin), timolol (beta blocker), tropicamide (mydriatic) are other classes.", "ow": ["A prostaglandin analog.", "A beta blocker.", "Correct. The -zolamide CAI.", "A mydriatic."]}'),
  ('7972e3f8-1h','{"options": ["Decreasing aqueous humor production", "Paralyzing accommodation", "Increasing pupil size", "Increasing aqueous production"], "correct": 0, "decode": "Like timolol, CAIs cut aqueous PRODUCTION (block carbonic anhydrase in the ciliary body). Pupil/accommodation and ''increasing production'' are wrong.", "ow": ["Correct. CAIs reduce secretion.", "That is a cycloplegic, unrelated.", "Not a CAI action.", "The opposite of the mechanism."]}'),
  ('cf6d1156-14','{"options": ["Beta blocker", "Alpha-2 adrenergic agonist", "Prostaglandin antagonist", "Muscarinic agonist"], "correct": 1, "decode": "Brimonidine is the classic α2 agonist of glaucoma therapy (cuts production, adds outflow). Learn it by class since the name has no obvious stem.", "ow": ["That is the -olol drugs.", "Correct. Brimonidine''s class.", "Not a real glaucoma class.", "That is pilocarpine."]}'),
  ('15db020c-21','{"options": ["Antihistamines", "Cycloplegics", "Mydriatics", "Antibiotics"], "correct": 3, "decode": "''Bacterial infection'' maps straight to antibiotics. The other classes act on allergy (antihistamine) or the pupil and accommodation (mydriatic, cycloplegic).", "ow": ["For allergy, not bacterial infection.", "Paralyze accommodation; no antibacterial action.", "Dilate the pupil; not anti-infective.", "Correct. The class that treats bacterial infection."]}'),
  ('903e864a-1a','{"options": ["Atropine", "Moxifloxacin", "Timolol", "Latanoprost"], "correct": 1, "decode": "The -floxacin ending marks a fluoroquinolone antibiotic: moxifloxacin. Atropine, timolol and latanoprost are non-antibiotic classes.", "ow": ["An antimuscarinic, not an antibiotic.", "Correct. A fluoroquinolone antibiotic.", "A beta blocker.", "A prostaglandin analog."]}'),
  ('1af17195-1i','{"options": ["Cataract", "Bacterial ocular infections", "Glaucoma exclusively", "Presbyopia"], "correct": 1, "decode": "Antibiotic class = infection target: fluoroquinolones treat bacterial ocular infection (keratitis, conjunctivitis). Cataract/glaucoma/presbyopia are non-infective decoys.", "ow": ["A lens opacity, not an infection.", "Correct. The antibiotic''s target.", "A pressure disease, not treated by antibiotics.", "An age-related focusing change."]}'),
  ('b56c991d-1v','{"options": ["Miotics", "Mydriatics", "Beta agonists", "Corticosteroids"], "correct": 3, "decode": "''Reduce inflammation'' = corticosteroids. Miotics/mydriatics act on the pupil; beta agonists are not anti-inflammatory.", "ow": ["Constrict the pupil, not anti-inflammatory.", "Dilate the pupil, not anti-inflammatory.", "Not an ocular anti-inflammatory class.", "Correct. The anti-inflammatory class."]}'),
  ('857df9fd-10','{"options": ["Pilocarpine", "Timolol", "Latanoprost", "Proparacaine"], "correct": 3, "decode": "The -caine ending marks a local anesthetic: proparacaine. Pilocarpine (miotic), timolol (beta blocker) and latanoprost (prostaglandin) are other classes.", "ow": ["A miotic (muscarinic agonist), not an anesthetic.", "A beta blocker for IOP.", "A prostaglandin analog for IOP.", "Correct. The -caine ending marks the anesthetic."]}'),
  ('012a3674-1n','{"options": ["Controlled clinical examination", "Measuring corneal sensation", "Prolonged unsupervised self-treatment", "Short-term diagnostic procedures"], "correct": 2, "decode": "A ''should NOT'' stem seeks the unsafe use: chronic unsupervised drops cause epithelial toxicity and melting. Brief clinical and diagnostic uses are fine.", "ow": ["An appropriate brief use.", "A legitimate diagnostic use.", "Correct. Chronic use causes epithelial toxicity and melting.", "An appropriate brief use."]}'),
  ('bb5d880d-r','{"options": ["Muscarinic agonist", "Prostaglandin analog", "Muscarinic antagonist", "Beta blocker"], "correct": 2, "decode": "Atropine dilates and paralyzes accommodation, the classic antimuscarinic (muscarinic antagonist) profile. Agonist/beta/prostaglandin do not fit.", "ow": ["That would constrict; atropine dilates.", "An outflow drug, unrelated.", "Correct. Long-acting antimuscarinic.", "A production-cutter, not atropine''s class."]}'),
  ('c71bdee9-1h','{"options": ["No measurable effect on accommodation at all", "Only miosis with no cycloplegic action", "Stronger and longer-lasting cycloplegia", "Only a reduction in intraocular pressure"], "correct": 2, "decode": "Both are antimuscarinics, but atropine is the long, strong one (up to 14 days) versus tropicamide''s few hours. ''Compared with tropicamide'' is asking about strength and duration.", "ow": ["False; atropine strongly cyclopleges.", "Atropine dilates and cyclopleges, it does not cause miosis.", "Correct. Atropine outlasts and outstrengths tropicamide.", "Atropine is not an IOP drug."]}'),
  ('f91c542c-w','{"options": ["Miosis", "Cycloplegia", "Mydriasis", "Corneal anesthesia"], "correct": 2, "decode": "Phenylephrine is an α1 agonist on the dilator, so mydriasis WITHOUT cycloplegia. It does not constrict or anesthetize.", "ow": ["That is a cholinergic effect, the opposite of α1.", "Phenylephrine spares the ciliary muscle.", "Correct. α1 dilation without cycloplegia.", "That is a -caine, not phenylephrine."]}'),
  ('f21cd65c-s','{"options": ["Alpha-adrenergic agonist", "Carbonic anhydrase inhibitor", "Beta blocker", "Muscarinic antagonist"], "correct": 0, "decode": "A sympathomimetic dilator with no cycloplegia = α-adrenergic agonist. Its dilation-without-cycloplegia signals the α (not antimuscarinic) route.", "ow": ["Correct. A direct α1 agonist.", "A production-cutter, unrelated.", "An IOP drug, not a dilator.", "Would also cycloplege; phenylephrine does not."]}'),
  ('a1c004a0-2y','{"options": ["Carbonic anhydrase inhibitors", "Alpha agonists", "Prostaglandin analogs", "Beta blockers"], "correct": 2, "decode": "Iris darkening plus periocular pigmentation (and lash growth) = prostaglandin analogs. Beta blockers, CAIs and alpha agonists do not cause this.", "ow": ["No pigment change.", "Cause allergy/redness, not pigmentation.", "Correct. Iris and periocular pigmentation, longer lashes.", "No pigment change."]}'),
  ('3b760bd6-1c','{"options": ["Bradycardia and bronchospasm", "Severe miosis only", "Iris pigmentation", "Increased accommodation"], "correct": 0, "decode": "Beta blocker systemic effects hit HEART and LUNGS: bradycardia and bronchospasm (danger in asthma/heart block). Miosis/pigmentation/accommodation are not timolol effects.", "ow": ["Correct. Systemic beta blockade slows the heart and constricts airways.", "Not a timolol effect.", "That is a prostaglandin effect.", "Not a beta-blocker effect."]}'),
  ('cf87b503-38','{"options": ["1 hour in all cases", "Several minutes", "No interval is needed", "1 second"], "correct": 1, "decode": "Wait about 5 minutes so the second drop does not wash out the first. Pick the sensible middle value; ''no interval'' and ''1 hour'' are the extremes.", "ow": ["Impractically long.", "Correct. About 5 minutes prevents washout.", "The second drop would flush the first.", "Too short to prevent washout."]}'),
  ('3f53dcad-23','{"options": ["Reduce systemic absorption", "Dilate the pupil", "Increase evaporation", "Increase systemic absorption"], "correct": 0, "decode": "Pressing the puncta blocks nasolacrimal drainage, keeping drug in the eye and OUT of the bloodstream, so it reduces systemic absorption. The opposite and pupil/evaporation options are wrong.", "ow": ["Correct. Blocks drainage into the systemic circulation.", "Punctal occlusion has no dilating effect.", "It does not affect evaporation.", "The opposite; it reduces it."]}'),
  ('cf31d6ac-s','{"options": ["The design and steps of common surgical procedures", "Only the microorganisms that cause disease", "Drugs and their effects on living organisms", "The gross and microscopic anatomy of the eye"], "correct": 2, "decode": "Pharmacology is the study of DRUGS and their effects on living organisms.", "ow": ["Surgical procedure design is surgery, not pharmacology.", "Studying only microorganisms is microbiology.", "Correct. Pharmacology studies drugs and their effects.", "Gross and microscopic eye structure is anatomy."]}'),
  ('f72508e8-21','{"options": ["Pharmacokinetics", "Toxicology", "Pharmacy", "Pharmacodynamics"], "correct": 0, "decode": "PHARMACOKINETICS is what the body does to a drug (absorption, distribution, metabolism, excretion).", "ow": ["Correct. Pharmacokinetics is the body''s handling of the drug (ADME).", "Toxicology studies poisons and adverse effects, not ADME generally.", "Pharmacy is the preparation and dispensing of drugs, not this branch.", "Pharmacodynamics is the reverse: what the drug does to the body."]}'),
  ('fea9044b-10','{"options": ["Drug excretion", "Drug distribution", "Drug absorption", "Drug effects on the body"], "correct": 3, "decode": "PHARMACODYNAMICS refers to the DRUG''S EFFECTS on the body (receptor binding and response).", "ow": ["Drug excretion is a kinetic (ADME) step, not dynamics.", "Drug distribution is a kinetic step, not dynamics.", "Drug absorption is a kinetic step, not dynamics.", "Correct. Pharmacodynamics is the drug''s effect on the body."]}'),
  ('8f60a65b-1r','{"options": ["Intramuscular", "Subcutaneous", "Intravenous", "Oral"], "correct": 2, "decode": "The INTRAVENOUS route gives the fastest systemic effect: the drug enters the blood directly with no absorption step.", "ow": ["Intramuscular dosing still requires absorption, so it is slower.", "Subcutaneous dosing requires absorption, so it is slower.", "Correct. IV bypasses absorption, acting fastest.", "Oral dosing requires absorption, so it is slower."]}'),
  ('729e3e2f-2d','{"options": ["Metabolism", "Absorption", "Excretion", "Distribution"], "correct": 1, "decode": "ABSORPTION is the movement of a drug from its administration site into the bloodstream (the first ADME step).", "ow": ["Metabolism chemically changes the drug after it is in the blood.", "Correct. Absorption moves the drug into the bloodstream.", "Excretion removes the drug from the body.", "Distribution carries the drug from blood to tissues, after absorption."]}'),
  ('32cb52e3-w','{"options": ["Optometry Law of 1955", "Revised Optometry Law of 1995", "Philippine Health Act", "Professional Regulation Act"], "correct": 1, "decode": "RA 8050 is the Revised Optometry Law of 1995 (it repealed the older RA 1998).", "ow": ["The Optometry Law of 1955 is not RA 8050.", "Correct. RA 8050 is the Revised Optometry Law of 1995.", "The Philippine Health Act is a different statute.", "The Professional Regulation Act is a different statute."]}'),
  ('728ee5d4-y','{"options": ["RA 7722", "RA 8051", "RA 9484", "RA 1998"], "correct": 3, "decode": "RA 8050 (1995) repealed RA 1998, despite the confusing numbering.", "ow": ["RA 7722 is the Higher Education Act, not the repealed optometry law.", "RA 8051 is not the repealed optometry law.", "RA 9484 is the Dental Act, not the repealed optometry law.", "Correct. RA 8050 repealed RA 1998."]}'),
  ('7d0ae82d-1i','{"options": ["3", "5", "7", "9"], "correct": 1, "decode": "The Board of Optometry has 5 members, appointed by the President from 10 nominees.", "ow": ["3 undercounts the Board.", "Correct. Five members.", "7 overcounts the Board.", "9 overcounts the Board."]}'),
  ('acfee63f-1o','{"options": ["5", "10", "15", "20"], "correct": 1, "decode": "The accredited national organization submits 10 nominees for the 5 Board seats.", "ow": ["5 is the number of seats, not the nominee list.", "Correct. Board members come from 10 nominees.", "15 is not the nominee count.", "20 is not the nominee count."]}'),
  ('4f081cf1-1g','{"options": ["3 years, renewable", "4 years, non-renewable", "5 years, non-renewable", "6 years, renewable"], "correct": 2, "decode": "A Board member serves a 5-year, NON-renewable term (staggered).", "ow": ["The term is 5 years and non-renewable, not 3 renewable.", "The term is 5 years, not 4.", "Correct. 5 years, non-renewable.", "The term is 5 years and non-renewable, not 6 renewable."]}'),
  ('3a590de1-2i','{"options": ["2", "3", "4", "5"], "correct": 1, "decode": "Three members form a quorum and 3 votes decide an administrative case.", "ow": ["2 is below the quorum.", "Correct. Quorum and admin vote are 3.", "4 exceeds the required number.", "5 is the full Board, not the quorum."]}'),
  ('e385e165-1l','{"options": ["A 75% average, none below 50%", "An 80% average, none below 70%", "A 70% average, none below 50%", "A 75% average, none below 60%"], "correct": 0, "decode": "To pass (Sec 20): at least a 75% general average AND no subject below 50%.", "ow": ["Correct. 75% average, none below 50%.", "80%/70% is not the passing rule.", "The average is 75%, not 70%.", "The subject floor is 50%, not 60%."]}'),
  ('f3d7a467-28','{"options": ["Four times", "Three times", "Five times", "Twice"], "correct": 1, "decode": "After failing three times, a refresher course is required before re-examination.", "ow": ["The trigger is three failures, not four.", "Correct. Fail 3 times then take a refresher.", "The trigger is three, not five.", "The trigger is three, not two."]}'),
  ('bc100881-1n','{"options": ["5 years", "3 years", "1 year", "10 years"], "correct": 1, "decode": "The professional license is renewed every 3 years (with continuing education).", "ow": ["Renewal is every 3 years, not 5.", "Correct. Renew every 3 years.", "Renewal is every 3 years, not yearly.", "Renewal is every 3 years, not 10."]}'),
  ('9656cb4e-1o','{"options": ["30 days", "90 days", "15 days", "60 days"], "correct": 2, "decode": "A revocation or suspension may be appealed to the PRC within 15 days (Sec 27).", "ow": ["The window is 15 days, not 30.", "The window is 15 days, not 90.", "Correct. Appeal within 15 days.", "The window is 15 days, not 60."]}'),
  ('bc312206-1g','{"options": ["License suspension only", "1–8 years, P10,000–40,000, or both", "A fine only, up to P5,000", "Imprisonment of 10–20 years"], "correct": 1, "decode": "The penalty for prohibited acts (Sec 33) is 1 to 8 years, P10,000 to P40,000, or both.", "ow": ["It is more than suspension alone.", "Correct. 1 to 8 years, P10,000 to P40,000, or both.", "It is more than a fine only.", "It is 1 to 8 years, not 10 to 20."]}'),
  ('ffb0d895-2c','{"options": ["Cataract extraction surgery", "Visual acuity screening only", "Full refraction and dispensing", "Instillation of DPAs"], "correct": 1, "decode": "A trained public health worker (Sec 5) may perform VISUAL ACUITY screening only.", "ow": ["Cataract surgery is far outside their scope.", "Correct. Visual acuity/screening only.", "Full refraction and dispensing exceed their scope.", "Instilling DPAs exceeds their scope."]}'),
  ('fb58cbad-1a','{"options": ["Professional Regulation Commission", "Department of Health", "Department of Labor and Employment", "Philippine Drug Enforcement Agency"], "correct": 0, "decode": "The Board of Optometry operates under the supervision of the PRC.", "ow": ["Correct. The Board is under the PRC.", "The DOH handles health services, not Board supervision.", "The DOLE handles labor, not the Board.", "The PDEA handles drug enforcement, not the Board."]}'),
  ('bb6d7a64-2a','{"options": ["Allowed only in print", "Allowed if the claim is true", "Committing a prohibited act", "Allowed with Board approval"], "correct": 2, "decode": "Advertising ''lower fees than any other clinic'' is a PROHIBITED ACT (Sec 32c); truth is no defense.", "ow": ["It is not allowed even in print.", "Truth does not make comparative/price advertising allowed.", "Correct. Comparative/price advertising is a prohibited act.", "Board approval does not permit it."]}'),
  ('2469a325-2p','{"options": ["2-year course", "5-year course", "4-year course", "6-year course"], "correct": 3, "decode": "Eligibility requires a Doctor of Optometry degree after a 6-year course (Sec 19).", "ow": ["A 2-year course is far too short.", "The course is 6 years, not 5.", "The course is 6 years, not 4.", "Correct. A 6-year O.D. course."]}'),
  ('3c9ac819-28','{"options": ["A physician with eye training", "A contact lens vendor", "A licensed optician", "A registered pharmacist"], "correct": 0, "decode": "A PHYSICIAN with post-graduate eye training may examine the eye without an optometry license (Sec 5).", "ow": ["Correct. A trained physician is exempt.", "A contact lens vendor is not exempt.", "A licensed optician is not exempt to examine.", "A registered pharmacist is not exempt."]}'),
  ('dab70589-25','{"options": ["A course and certification exam", "A second optometry degree", "A one-year surgical fellowship", "No extra requirement at all"], "correct": 0, "decode": "An optometrist trained before the law must pass a COURSE and CERTIFICATION exam in pharmacology before using DPAs (Sec 31).", "ow": ["Correct. Pharmacology course and certification.", "A second optometry degree is not required.", "A surgical fellowship is not required.", "There is an extra requirement; it is not ''none''."]}'),
  ('3dd73257-u','{"options": ["The national optometric organization directly", "The DOH Secretary", "The President of the Philippines", "The PRC Commissioner alone"], "correct": 2, "decode": "Board members are appointed by the PRESIDENT (on PRC recommendation, from the 10 nominees).", "ow": ["The organization nominates but does not appoint directly.", "The DOH Secretary does not appoint the Board.", "Correct. The President appoints the Board.", "The PRC Commissioner alone does not appoint them."]}'),
  ('aeb87800-17','{"options": ["On demand", "Once a year", "Twice a year", "Once every 5 years"], "correct": 1, "decode": "The licensure examination is given at least once a year (Sec 17).", "ow": ["It is scheduled at least yearly, not on demand.", "Correct. At least once a year.", "The minimum is once a year, not twice.", "It is at least once a year, not once every 5 years."]}'),
  ('d0cb9f3c-1j','{"options": ["15 days", "30 days", "90 days", "60 days"], "correct": 3, "decode": "The Board reports examination ratings to the PRC within 60 days (Sec 21).", "ow": ["The window is 60 days, not 15.", "The window is 60 days, not 30.", "The window is 60 days, not 90.", "Correct. Ratings reported within 60 days."]}'),
  ('d1e84335-2d','{"options": ["Ten", "Six", "Three", "Twelve"], "correct": 1, "decode": "The Code of Professional Ethics (Sec 40) requires SIX duties of an optometrist.", "ow": ["It lists six duties, not ten.", "Correct. Six ethical duties.", "It lists six duties, not three.", "It lists six duties, not twelve."]}'),
  ('e765dfcc-10','{"options": ["One national organization", "Multiple competing boards", "No organization", "The PRC staff"], "correct": 0, "decode": "RA 8050 integrates all optometrists into ONE national organization (which promulgates the Code).", "ow": ["Correct. One national organization.", "It is one organization, not multiple competing boards.", "Integration means one organization, not none.", "It is a professional organization, not PRC staff."]}'),
  ('fd9aa516-2m','{"options": ["Display only the diplomas", "Display nothing at all", "Display the certificate", "Keep the certificate hidden"], "correct": 2, "decode": "In the clinic the optometrist must DISPLAY the certificate (COR) conspicuously (Sec 6).", "ow": ["More than diplomas: the COR must be displayed.", "The COR must be displayed, not nothing.", "Correct. Display the certificate.", "The COR must be shown, not hidden."]}'),
  ('c7eb62da-20','{"options": ["The PRC clerk", "A court only", "The national organization", "The President of the Philippines"], "correct": 3, "decode": "A Board member may be removed for cause by the PRESIDENT after due process (Sec 10).", "ow": ["A PRC clerk cannot remove a Board member.", "Removal for cause is by the President, not solely a court.", "The national organization does not remove Board members.", "Correct. The President removes for cause."]}'),
  ('5712c856-1g','{"options": ["An optional health service", "A purely commercial trade", "A surgical subspecialty", "Part of primary health care"], "correct": 3, "decode": "RA 8050 (Sec 2) declares optometry part of PRIMARY HEALTH CARE.", "ow": ["It is declared essential, not optional.", "It is a profession, not a purely commercial trade.", "It is not a surgical subspecialty.", "Correct. Optometry is part of primary health care."]}'),
  ('9980615e-25','{"options": ["Section 40 only", "Section 19", "Section 5", "Not covered"], "correct": 2, "decode": "Unauthorized practice of optometry is prohibited under Section 5 (and punishable under Sec 32).", "ow": ["Section 40 is the Code of Ethics, not the unauthorized-practice provision.", "Section 19 is the exam qualifications.", "Correct. Section 5 addresses unauthorized practice.", "It is covered, not uncovered."]}'),
  ('992f91bf-16','{"options": ["3", "5", "7", "10"], "correct": 1, "decode": "RA 8050 authorizes 5 DPAs: phenylephrine, tropicamide, cyclopentolate, proparacaine, fluorescein.", "ow": ["3 undercounts the authorized DPAs.", "Correct. Five authorized DPAs (as originally listed).", "7 overcounts them.", "10 overcounts them."]}'),
  ('04bbcfd5-1u','{"options": ["Join the PRC as staff", "Open a clinic immediately", "Pay a facilitation fee", "Take an oath before the Board"], "correct": 3, "decode": "Before registration, the successful examinee must TAKE AN OATH before the Board (Sec 23).", "ow": ["Passing does not make one PRC staff.", "The oath, not opening a clinic, precedes registration.", "No facilitation fee is required.", "Correct. Take an oath before registration."]}'),
  ('f98e43ca-1u','{"options": ["Permanent resident alien", "Filipino of good moral character", "Foreign optometry expert", "Licensed medical physician"], "correct": 1, "decode": "An exam applicant must be a FILIPINO of good moral character (Sec 19).", "ow": ["A permanent resident alien does not meet the citizenship requirement.", "Correct. A Filipino citizen of good moral character.", "Foreign expertise does not substitute for the citizenship requirement.", "A medical physician license is not the optometry-exam requirement."]}'),
  ('84ad4cc6-3p','{"options": ["WTR is steep at 90°", "Hyperopia needs plus lenses", "RA 8050 sets the Board at 5 members", "Latent + manifest = total"], "correct": 2, "decode": "The only LAW fact here is that RA 8050 sets the Board at 5 members; the others are clinical facts.", "ow": ["WTR being steep at 90 is a clinical optics fact, not jurisprudence.", "Hyperopia needing plus lenses is a clinical fact.", "Correct. The 5-member Board is the law fact.", "Latent + manifest = total is a clinical refraction fact."]}'),
  ('e6adfc27-1m','{"options": ["Encouraged for competition", "Prohibited, degrading acts", "Required by the PRC rules", "Allowed once every year"], "correct": 1, "decode": "Comparative advertising and offering free examinations are PROHIBITED, degrading acts (Sec 32).", "ow": ["They are prohibited, not encouraged.", "Correct. They are prohibited, degrading acts.", "They are not required by PRC rules.", "They are not allowed even once a year."]}'),
  ('4a3e47d7-1o','{"options": ["A criminal felony only", "Not a punishable matter", "A minor private matter", "Unethical, punishable conduct"], "correct": 3, "decode": "A Code violation is UNETHICAL, PUNISHABLE conduct (suspension/prohibition under Sec 26).", "ow": ["It is not only a criminal felony.", "It is punishable, not unpunishable.", "It is not a minor private matter.", "Correct. Unethical, punishable conduct."]}'),
  ('4c0200ac-13','{"options": ["Diagnosis, treatment, billing, referral", "Profit, efficiency, speed, comfort", "Honesty, charity, courage, loyalty", "Autonomy, beneficence, non-maleficence, justice"], "correct": 3, "decode": "The four core bioethical principles are AUTONOMY, BENEFICENCE, NON-MALEFICENCE, JUSTICE.", "ow": ["Diagnosis, treatment, billing, referral are clinical steps, not the principles.", "Profit, efficiency, speed, comfort are not bioethical principles.", "Honesty, charity, courage, loyalty are virtues, not the four principles.", "Correct. Autonomy, beneficence, non-maleficence, justice."]}'),
  ('8a7bc865-1o','{"options": ["Justice", "Beneficence", "Non-maleficence", "Autonomy"], "correct": 3, "decode": "Informed consent is the direct expression of AUTONOMY.", "ow": ["Justice is fair distribution, not consent.", "Beneficence is acting for good, not consent itself.", "Non-maleficence is avoiding harm, not consent.", "Correct. Informed consent expresses autonomy."]}'),
  ('ff5f070e-1i','{"options": ["Beneficence", "Non-maleficence", "Autonomy", "Justice"], "correct": 1, "decode": "''Primum non nocere'' (first, do no harm) is NON-MALEFICENCE.", "ow": ["Beneficence is doing good, not the do-no-harm maxim.", "Correct. Primum non nocere is non-maleficence.", "Autonomy is the right to decide, not this maxim.", "Justice is fairness, not this maxim."]}'),
  ('4725b0f3-2o','{"options": ["Beneficence", "Justice", "Autonomy", "Non-maleficence"], "correct": 1, "decode": "Giving a charity patient a lesser exam than a private patient violates JUSTICE.", "ow": ["Beneficence is acting for the patient''s good, not the equal-standard issue.", "Correct. Unequal care violates justice.", "Autonomy concerns the patient''s right to decide, not equal standard.", "Non-maleficence is avoiding harm, not the equal-standard issue."]}'),
  ('0168783c-28','{"options": ["Beneficence", "Justice", "Collegiality", "Autonomy"], "correct": 3, "decode": "Instilling a DPA without explanation or permission violates AUTONOMY.", "ow": ["Beneficence is acting for good, not the consent issue.", "Justice is fairness, not the consent issue.", "Collegiality concerns colleagues, not patient consent.", "Correct. No consent for a DPA violates autonomy."]}'),
  ('86964b17-22','{"options": ["Autonomy", "Justice", "Beneficence", "Non-maleficence"], "correct": 2, "decode": "Recommending an unnecessary upgrade for profit violates BENEFICENCE (acting in the patient''s best interest).", "ow": ["Autonomy is the patient''s right to decide, not this profit issue.", "Justice is fairness across patients, not this profit issue.", "Correct. Acting against the patient''s best interest violates beneficence.", "Non-maleficence is avoiding harm; the core breach here is failing to do good."]}'),
  ('4b3959b9-1t','{"options": ["The diagnosis and implications", "The treatment options and risks", "The clinician''s personal income", "The alternatives"], "correct": 2, "decode": "Informed consent requires understanding of diagnosis, options, risks, and alternatives, but NOT the clinician''s personal income.", "ow": ["The diagnosis and implications are part of consent.", "The treatment options and risks are part of consent.", "Correct. The clinician''s income is not part of consent.", "The alternatives are part of consent."]}'),
  ('9b5d5e77-16','{"options": ["A parent or guardian", "The optometrist", "The minor alone", "No one is needed"], "correct": 0, "decode": "For a minor, consent is provided by a PARENT or GUARDIAN (the child gives assent).", "ow": ["Correct. A parent or guardian consents.", "The optometrist does not provide the minor''s consent.", "The minor alone cannot legally consent.", "Someone must consent; it is not ''no one''."]}'),
  ('0224603a-21','{"options": ["May be waived under the doctrine", "Is still mandatory in writing", "May be ignored in all cases", "Must be obtained from the PRC"], "correct": 0, "decode": "In a true emergency where delay would cause serious harm, consent MAY BE WAIVED (emergency doctrine).", "ow": ["Correct. Consent may be waived in a genuine emergency.", "It is not still mandatory in writing in a true emergency.", "It may be waived only in true emergencies, not in all cases.", "It is not obtained from the PRC."]}'),
  ('cf1be5ee-2p','{"options": ["Discharge the patient", "Document, re-counsel, monitor", "Override and refer anyway", "Report them to the Board"], "correct": 1, "decode": "When a competent adult refuses referral, the ethical action is to DOCUMENT, RE-COUNSEL, and MONITOR (do not abandon).", "ow": ["Discharging the patient is abandonment.", "Correct. Document, re-counsel, keep monitoring.", "Overriding refusal violates autonomy.", "Reporting the patient to the Board is not appropriate."]}'),
  ('9a2d0db6-2w','{"options": ["Justice", "Autonomy", "Confidentiality", "Non-maleficence"], "correct": 3, "decode": "Declining to fit risky extended-wear lenses in a non-compliant patient with prior keratitis reflects NON-MALEFICENCE (avoiding foreseeable harm).", "ow": ["Justice is fairness, not the avoid-harm issue.", "Autonomy is the patient''s right to decide, not the clinician''s avoid-harm duty here.", "Confidentiality concerns privacy, not this decision.", "Correct. Avoiding foreseeable harm is non-maleficence."]}'),
  ('d1c1ddf8-l','{"options": ["Never accepting any risk", "Treating everyone identically", "Benefit must outweigh harm", "Always referring onward"], "correct": 2, "decode": "Non-maleficence means the BENEFIT must outweigh the harm (a balance, not a ban on all risk).", "ow": ["It does not mean never accepting any risk.", "Treating everyone identically is justice, not non-maleficence.", "Correct. Benefit must outweigh harm.", "It does not mean always referring onward."]}'),
  ('edb053b1-17','{"options": ["Florence Nightingale", "Hippocrates", "Beauchamp and Childress", "RA 8050"], "correct": 2, "decode": "The four-principle framework is credited to BEAUCHAMP and CHILDRESS.", "ow": ["Florence Nightingale is associated with nursing, not this framework.", "Hippocrates is associated with the oath, not the four principles.", "Correct. Beauchamp and Childress.", "RA 8050 is a statute, not the framework''s authors."]}'),
  ('9bbf4596-1o','{"options": ["Collegiality", "Confidentiality", "Beneficence", "Justice"], "correct": 1, "decode": "Keeping patient records and diagnoses private is CONFIDENTIALITY.", "ow": ["Collegiality concerns relations with colleagues, not privacy.", "Correct. Privacy of records is confidentiality.", "Beneficence is doing good, not privacy.", "Justice is fairness, not privacy."]}'),
  ('bbfb7446-23','{"options": ["Confidentiality", "Non-maleficence", "Autonomy", "Justice"], "correct": 1, "decode": "Referring a condition beyond your competence reflects NON-MALEFICENCE (preventing harm).", "ow": ["Confidentiality concerns privacy, not referral.", "Correct. Referring beyond scope prevents harm.", "Autonomy is the patient''s right to decide, not referral.", "Justice is fairness, not referral."]}'),
  ('4b0efff2-2m','{"options": ["Confidentiality", "Justice and beneficence", "Collegiality", "Autonomy"], "correct": 1, "decode": "Declining a gift to prescribe a product exclusively is supported by JUSTICE and BENEFICENCE (patient need and fairness over kickbacks).", "ow": ["Confidentiality concerns privacy, not product selection.", "Correct. Reject kickbacks: justice and beneficence.", "Collegiality concerns colleagues, not this decision.", "Autonomy is the patient''s right to decide, not the clinician''s product choice."]}'),
  ('c449712a-11','{"options": ["The optometrist''s own decision", "A legal loophole for the clinic", "Agreement based on understanding", "A signature on a form"], "correct": 2, "decode": "Informed consent is AGREEMENT BASED ON UNDERSTANDING, not merely a signature.", "ow": ["It is the patient''s decision, not the optometrist''s.", "It is not a legal loophole for the clinic.", "Correct. Agreement based on understanding.", "A signature alone without understanding is not consent."]}'),
  ('7870bd1d-2y','{"options": ["Beneficence", "Autonomy", "Confidentiality", "Justice"], "correct": 3, "decode": "''Equal diligence to all regardless of race, creed or status'' (Sec 40) maps to JUSTICE.", "ow": ["Beneficence is doing good, not the equal-diligence duty.", "Autonomy is the patient''s right to decide, not equal diligence.", "Confidentiality concerns privacy, not equal diligence.", "Correct. Equal diligence to all is justice."]}'),
  ('56131fc9-2r','{"options": ["Justice", "Autonomy", "Beneficence", "Confidentiality"], "correct": 2, "decode": "''Consider the visual welfare of the public as the primary responsibility'' (Sec 40) maps to BENEFICENCE.", "ow": ["Justice is fairness, not the best-interest duty.", "Autonomy is the patient''s right to decide, not this duty.", "Correct. Visual welfare of the public is beneficence.", "Confidentiality concerns privacy, not this duty."]}'),
  ('35535653-28','{"options": ["Defer until a guardian consents", "Fit the lenses immediately", "Refuse all care outright", "Report the parents to DSWD"], "correct": 0, "decode": "A minor arriving alone for a contact lens fitting means DEFER until a guardian consents.", "ow": ["Correct. Defer until a guardian consents.", "Fitting immediately skips required consent.", "Refusing all care outright is not required; defer instead.", "Reporting the parents to DSWD is not warranted."]}'),
  ('2649ae36-2t','{"options": ["Habeas corpus", "Respondeat superior", "Caveat emptor", "Informed consent"], "correct": 1, "decode": "''Let the master answer'', making a superior responsible for a subordinate''s acts, is RESPONDEAT SUPERIOR.", "ow": ["Habeas corpus concerns unlawful detention, not vicarious liability.", "Correct. Respondeat superior is ''let the master answer''.", "Caveat emptor is ''let the buyer beware''.", "Informed consent is a patient-rights doctrine, not vicarious liability."]}'),
  ('b64a8d8e-27','{"options": ["Autonomy", "Confidentiality", "Justice", "Continuous competence"], "correct": 3, "decode": "The obligation to keep current through continuing education is CONTINUOUS COMPETENCE (Sec 40).", "ow": ["Autonomy is the patient''s right to decide, not staying current.", "Confidentiality concerns privacy, not competence.", "Justice is fairness, not competence.", "Correct. Staying current is continuous competence."]}'),
  ('8ce0e746-t','{"options": ["They are wholly identical", "Law is enforceable; ethics moral", "Ethics is enforced by courts", "Law carries no penalties"], "correct": 1, "decode": "Law is ENFORCEABLE under penalty; ethics is a MORAL obligation (though RA 8050 makes Code violations punishable).", "ow": ["They are not wholly identical.", "Correct. Law is enforceable; ethics is moral.", "Ethics is generally not enforced by courts.", "Law does carry penalties."]}'),
  ('4233de99-2m','{"options": ["Non-maleficence", "Justice", "Confidentiality", "Collegiality"], "correct": 0, "decode": "Scenarios about contraindications and referral most commonly test NON-MALEFICENCE (avoid harm).", "ow": ["Correct. Contraindication/referral scenarios test non-maleficence.", "Justice is fairness, less commonly the contraindication theme.", "Confidentiality concerns privacy, not contraindications.", "Collegiality concerns colleagues, not contraindications."]}'),
  ('f308ba5b-1z','{"options": ["Mayor → DTI → BIR → Barangay", "Barangay → BIR → DTI → Mayor", "DTI → Barangay → Mayor → BIR", "BIR → Mayor → Barangay → DTI"], "correct": 2, "decode": "To register a sole-proprietorship clinic: DTI (name) then Barangay (location) then Mayor (permit) then BIR (taxes).", "ow": ["Mayor first is out of order; DTI comes first.", "Barangay first is out of order.", "Correct. DTI then Barangay then Mayor then BIR.", "BIR first is out of order; taxes come last."]}'),
  ('8804bea5-x','{"options": ["Barangay clearance", "Business name registration", "Tax identification number", "Mayor''s permit"], "correct": 1, "decode": "DTI registration provides the BUSINESS NAME registration (5-year certificate).", "ow": ["Barangay clearance is a separate step.", "Correct. DTI registers the business name.", "The TIN comes from the BIR.", "The Mayor''s permit is a separate step."]}'),
  ('cf321f27-12','{"options": ["TIN and books of accounts", "Registered business name", "The sanitary permit", "The CPD certificate"], "correct": 0, "decode": "BIR registration provides the TIN and BOOKS OF ACCOUNTS.", "ow": ["Correct. BIR gives the TIN and books of accounts.", "The business name is from the DTI.", "The sanitary permit is from local government, not the BIR.", "The CPD certificate is unrelated to BIR registration."]}'),
  ('55a50fd9-2s','{"options": ["30 days", "15 days", "1 year", "60 days"], "correct": 0, "decode": "Under Board Resolution No. 11 (2016), the clinic location must be reported to the Board within 30 days.", "ow": ["Correct. Notify the Board within 30 days.", "The window is 30 days, not 15.", "The window is 30 days, not 1 year.", "The window is 30 days, not 60."]}'),
  ('a3884906-19','{"options": ["20 sq m", "5 sq m", "10 sq m", "8 sq m"], "correct": 2, "decode": "The minimum examination room area is 10 square meters (test distance at least 3 m).", "ow": ["20 sq m exceeds the required minimum.", "5 sq m is below the minimum.", "Correct. At least 10 square meters.", "8 sq m is below the minimum."]}'),
  ('e93c3cc3-1h','{"options": ["1 m", "3 m", "6 m", "10 m"], "correct": 1, "decode": "The minimum test distance for the examination room is 3 meters.", "ow": ["1 m is below the minimum.", "Correct. At least 3 meters.", "6 m is achieved optically with mirrors; the room minimum is 3 m.", "10 m is far above the minimum."]}'),
  ('e03f958d-1v','{"options": ["Decided by the PRC board", "The optometrist''s discretion", "Fixed by law at 15 minutes", "Set by the optical owner"], "correct": 1, "decode": "Chair time and choice of method are the OPTOMETRIST''S sole discretion (Board Resolution No. 11).", "ow": ["The PRC board does not decide chair time per patient.", "Correct. Chair time is the optometrist''s discretion.", "It is not fixed by law at 15 minutes.", "The optical owner does not set chair time."]}'),
  ('f56f65b2-16','{"options": ["Self-laudatory and competitive", "Focused on the lowest prices", "True, honest, fair, dignified", "Anything that attracts patients"], "correct": 2, "decode": "Permissible advertising must be TRUE, HONEST, FAIR, and DIGNIFIED.", "ow": ["Self-laudatory, competitive ads are prohibited.", "Lowest-price focus is prohibited.", "Correct. True, honest, fair, dignified.", "Not anything that attracts patients; content is restricted."]}'),
  ('4cc60e49-x','{"options": ["A dignified statement of services offered", "''Free eye exam with every purchase''", "Clinic hours and location", "The optometrist''s name and specialization"], "correct": 1, "decode": "''Free eye exam with every purchase'' is a PROHIBITED advertisement (free/discounted service).", "ow": ["A dignified statement of services is permitted.", "Correct. Free-service advertising is prohibited.", "Clinic hours and location may be stated.", "The optometrist''s name and specialization may be stated."]}'),
  ('52e10d85-1o','{"options": ["Valid certificates of registration", "Updated professional ID cards", "CPD certificates of completion", "Competitors'' price lists"], "correct": 3, "decode": "A clinic must display CORs, PICs, and CPD certificates, but NOT competitors'' price lists.", "ow": ["Valid CORs must be displayed.", "Updated professional ID cards must be displayed.", "CPD certificates are displayed.", "Correct. Competitors'' price lists are not displayed."]}'),
  ('4295b417-1b','{"options": ["Be the main feature identifying the practice", "NOT be used to highlight or identify the practice", "Be the largest area", "Replace the exam room"], "correct": 1, "decode": "The product (frames/sunglasses) display area must NOT be used to highlight or identify the practice.", "ow": ["Products must not be the main feature identifying the practice.", "Correct. Product display must not identify the practice.", "It must not be the largest area.", "It cannot replace the exam room."]}'),
  ('0ada9e0a-22','{"options": ["No contributions are required", "DTI, BIR, and SEC fees", "PRC, DOH, and PDEA dues", "SSS, PhilHealth, Pag-IBIG"], "correct": 3, "decode": "Mandatory employee government contributions include SSS, PhilHealth, and Pag-IBIG.", "ow": ["Contributions are required.", "DTI, BIR, and SEC are business-registration bodies, not employee-benefit funds.", "PRC, DOH, and PDEA are not employee-benefit contributions.", "Correct. SSS, PhilHealth, Pag-IBIG."]}'),
  ('9ecda2c4-1x','{"options": ["DOH", "DTI", "DOLE", "PRC"], "correct": 2, "decode": "The Occupational Safety and Health Standards are administered by DOLE.", "ow": ["The DOH handles health, not OSHS.", "The DTI handles trade, not OSHS.", "Correct. OSHS falls under DOLE.", "The PRC handles licensure, not OSHS."]}'),
  ('81618fb0-1f','{"options": ["Manned by a licensed optometrist", "Left unattended", "Run by a salesperson", "Closed for exams"], "correct": 0, "decode": "During operating hours the clinic must be MANNED by a licensed optometrist (Board Resolution No. 11).", "ow": ["Correct. A licensed optometrist must be on-site.", "It must not be left unattended.", "A salesperson cannot run the clinic.", "It is not closed for exams during operating hours."]}'),
  ('b4eb3ce6-1q','{"options": ["Slit-lamp biomicroscope", "Direct ophthalmoscope", "Retinoscope and phoropter", "A cash register"], "correct": 3, "decode": "Required instruments are clinical (slit lamp, ophthalmoscope, retinoscope, phoropter, etc.); a CASH REGISTER is not clinical equipment.", "ow": ["A slit-lamp biomicroscope is required.", "A direct ophthalmoscope is required.", "A retinoscope and phoropter are required.", "Correct. A cash register is not clinical equipment."]}'),
  ('8d0864fb-y','{"options": ["Open-plan with sales counters", "Shared with a retail store", "Exclusive, enclosed, separate", "Inside a supermarket aisle"], "correct": 2, "decode": "The clinic space must be EXCLUSIVE, ENCLOSED, and SEPARATE from commercial concerns.", "ow": ["It must not be open-plan with sales counters.", "It must not be shared with a retail store.", "Correct. Exclusive, enclosed, separate.", "It must not be inside a supermarket aisle."]}'),
  ('b47b9b7e-y','{"options": ["Conduct the subjective refraction independently", "Sign prescriptions", "Perform the acts constituting the practice of optometry", "Not perform acts that constitute the practice of optometry"], "correct": 3, "decode": "A non-optometrist staff member may NOT perform the acts constituting the practice of optometry.", "ow": ["They cannot conduct subjective refraction independently.", "They cannot sign prescriptions.", "They cannot perform the acts of optometric practice.", "Correct. Non-optometrists may not practice optometry."]}'),
  ('363b53ca-20','{"options": ["Required by the law", "Prohibited, unprofessional", "Encouraged by the Board", "Allowed once every year"], "correct": 1, "decode": "Soliciting patients by canvassing or employing agents/solicitors is PROHIBITED, unprofessional conduct.", "ow": ["It is prohibited, not required.", "Correct. Soliciting patients is prohibited.", "It is not encouraged by the Board.", "It is not allowed even once a year."]}'),
  ('e3772d0e-1o','{"options": ["The Mayor''s office", "The DTI", "The BIR", "The Barangay"], "correct": 0, "decode": "The local business permit to operate is issued by the MAYOR''S OFFICE (after inspections).", "ow": ["Correct. The Mayor''s office issues the business permit.", "The DTI registers the business name, not the permit.", "The BIR handles taxes, not the permit.", "The Barangay issues a clearance, not the business permit."]}'),
  ('bc33e324-2c','{"options": ["5 members from 10 nominees", "3 members from 6 nominees", "5 members from 15 nominees", "7 members from 14 nominees"], "correct": 0, "decode": "The Board of Optometry is 5 members chosen from 10 nominees (appointed by the President).", "ow": ["Correct. 5 members from 10 nominees.", "It is 5 from 10, not 3 from 6.", "It is 5 from 10, not 5 from 15.", "It is 5 from 10, not 7 from 14."]}'),
  ('6fcf3632-16','{"options": ["5 years, non-renewable", "2 years, renewable twice", "3 years, renewable once", "5 years, renewable once"], "correct": 0, "decode": "A Board member serves a single 5-year, NON-renewable term.", "ow": ["Correct. 5 years, non-renewable.", "It is 5 years non-renewable, not 2 renewable twice.", "It is 5 years, not 3 renewable once.", "It is non-renewable, not renewable once."]}'),
  ('1e0602f6-1n','{"options": ["10 years", "5 years", "3 years", "Year"], "correct": 2, "decode": "The professional license is renewed every 3 years (with CPD).", "ow": ["Renewal is every 3 years, not 10.", "Renewal is every 3 years, not 5.", "Correct. Every 3 years.", "Renewal is every 3 years, not yearly."]}'),
  ('dfb49217-1s','{"options": ["Take a refresher course", "Be permanently barred", "Repeat the whole degree", "Wait five years"], "correct": 0, "decode": "A candidate who fails the exam three times must take a REFRESHER course before re-admission.", "ow": ["Correct. Take a refresher course.", "They are not permanently barred.", "They do not repeat the whole degree.", "There is no 5-year wait; a refresher is required."]}'),
  ('9e193865-14','{"options": ["15 days", "60 days", "5 days", "30 days"], "correct": 0, "decode": "The window to appeal a Board decision is 15 days.", "ow": ["Correct. 15 days.", "The window is 15 days, not 60.", "The window is 15 days, not 5.", "The window is 15 days, not 30."]}'),
  ('cd001f19-1e','{"options": ["The Department of Health", "The Commission on Higher Education", "The Professional Regulation Commission", "The Department of Education"], "correct": 2, "decode": "The Board of Optometry operates under the PRC.", "ow": ["The DOH handles health services, not the Board.", "CHED handles higher education, not the Board.", "Correct. The Board is under the PRC.", "The Department of Education is unrelated."]}'),
  ('9d82bd4e-1n','{"options": ["Winslow and Snow", "Kant and Mill", "Beauchamp and Childress", "Hippocrates and Galen"], "correct": 2, "decode": "The four principles of biomedical ethics were formulated by BEAUCHAMP and CHILDRESS.", "ow": ["Winslow and Snow are not the framework''s authors.", "Kant and Mill are moral philosophers, not the four-principles authors.", "Correct. Beauchamp and Childress.", "Hippocrates and Galen predate the four-principle framework."]}'),
  ('6c7e3bfc-1o','{"options": ["Autonomy", "Beneficence", "Non-maleficence", "Justice"], "correct": 0, "decode": "Informed consent is chiefly an expression of AUTONOMY.", "ow": ["Correct. Consent expresses autonomy.", "Beneficence is acting for good, not consent.", "Non-maleficence is avoiding harm, not consent.", "Justice is fair distribution, not consent."]}'),
  ('b058b547-v','{"options": ["First, do no harm", "Respect the patient''s wishes", "Treat all alike", "Do good always"], "correct": 0, "decode": "''Primum non nocere'' translates as FIRST, DO NO HARM.", "ow": ["Correct. First, do no harm.", "Respecting the patient''s wishes is autonomy, not this maxim.", "Treating all alike is justice, not this maxim.", "Doing good always is beneficence, not this maxim."]}'),
  ('40432dfc-26','{"options": ["Non-maleficence", "Justice", "Veracity", "Autonomy"], "correct": 0, "decode": "Referring a patient beyond your scope expresses NON-MALEFICENCE (avoiding harm).", "ow": ["Correct. Referring beyond scope is non-maleficence.", "Justice is fairness, not the avoid-harm referral.", "Veracity is truth-telling, not referral.", "Autonomy is the patient''s right to decide, not referral."]}'),
  ('d9e54a1e-21','{"options": ["Distributive justice", "Beneficence", "Autonomy", "Fidelity"], "correct": 0, "decode": "Treating every patient equally regardless of status is DISTRIBUTIVE JUSTICE.", "ow": ["Correct. Equal care regardless of status is distributive justice.", "Beneficence is acting for good, not equal allocation.", "Autonomy is the patient''s right to decide, not equal allocation.", "Fidelity is faithfulness/promise-keeping, not equal allocation."]}'),
  ('0b0fedcb-1w','{"options": ["Nothing further", "A waiver", "Assent", "Written consent"], "correct": 2, "decode": "For a minor, the parent gives consent and the child gives ASSENT.", "ow": ["The child gives assent, not nothing.", "The child gives assent, not a waiver.", "Correct. The child gives assent.", "The child gives assent; written consent is the guardian''s role."]}'),
  ('b2fef710-1o','{"options": ["RA 8050 Section 26", "RA 8050 Section 31", "RA 8050 Section 32", "RA 8050 Section 40"], "correct": 3, "decode": "The Code of Professional Ethics is in RA 8050 SECTION 40 (penalty in Sec 26).", "ow": ["Section 26 carries the penalty for a Code violation, not the Code itself.", "Section 31 covers DPA certification, not the Code.", "Section 32 lists prohibited acts, not the Code of Ethics.", "Correct. Section 40 contains the Code of Ethics."]}'),
  ('a684885f-1o','{"options": ["DTI → Barangay → Mayor → BIR", "Mayor → DTI → BIR → Barangay", "BIR → DTI → Mayor → Barangay", "Barangay → BIR → DTI → Mayor"], "correct": 0, "decode": "To set up a practice as a business: DTI then Barangay then Mayor then BIR.", "ow": ["Correct. DTI then Barangay then Mayor then BIR.", "Mayor first is out of order.", "BIR first is out of order.", "Barangay first is out of order."]}'),
  ('46f2efa1-1g','{"options": ["1 year", "10 years", "5 years", "3 years"], "correct": 2, "decode": "The DTI business name certificate is valid for 5 years.", "ow": ["It is valid 5 years, not 1.", "It is valid 5 years, not 10.", "Correct. 5 years.", "It is valid 5 years, not 3."]}'),
  ('a9ec7069-1s','{"options": ["60 days", "30 days", "15 days", "7 days"], "correct": 1, "decode": "The Board must be notified of a change of clinic location within 30 days.", "ow": ["The window is 30 days, not 60.", "Correct. Within 30 days.", "The window is 30 days, not 15.", "The window is 30 days, not 7."]}'),
  ('b776ca9b-1o','{"options": ["15 sq m", "5 sq m", "20 sq m", "10 sq m"], "correct": 3, "decode": "The minimum examination room floor area is 10 square meters (Board Resolution No. 11, 2016).", "ow": ["15 sq m exceeds the required minimum.", "5 sq m is below the minimum.", "20 sq m exceeds the minimum.", "Correct. At least 10 square meters."]}'),
  ('e88d39da-1r','{"options": ["2 m", "3 m", "4 m", "6 m"], "correct": 1, "decode": "The minimum testing distance is 3 meters (mirrors give the optical equivalent of 6 m in short rooms).", "ow": ["2 m is below the minimum.", "Correct. At least 3 meters.", "4 m exceeds the minimum requirement.", "6 m is the optical equivalent achieved with mirrors, not the room minimum."]}'),
  ('10355972-17','{"options": ["RA 8050 Section 40", "Board Resolution No. 1", "Board Resolution No. 5", "Board Resolution No. 11"], "correct": 3, "decode": "Optometric office standards are governed by BOARD RESOLUTION NO. 11 (2016).", "ow": ["Section 40 is the Code of Ethics, not the office standards.", "Board Resolution No. 1 (2008) governs advertising, not office standards.", "Board Resolution No. 5 is not the office-standards resolution.", "Correct. Board Resolution No. 11 (2016)."]}'),
  ('b63ba423-2u','{"options": ["4", "5", "6", "8"], "correct": 2, "decode": "Counting the 2008 IRR, the CURRENT number of DPAs is 6 (cyclopentolate was added to the original five).", "ow": ["4 undercounts the current list.", "5 is the original RA 8050 count, not the current list.", "Correct. Six current DPAs.", "8 overcounts them."]}'),
  ('9a10aac3-2d','{"options": ["DOLE", "BFAD", "PRC", "CHED"], "correct": 1, "decode": "The DPA list is set by the Board, RECOMMENDED by BFAD, and approved by the DOH.", "ow": ["The DOLE handles labor, not the DPA list.", "Correct. BFAD recommends the DPA list.", "The PRC supervises the Board but does not recommend the drug list.", "CHED handles education, not the DPA list."]}'),
  ('0f4a08b8-1c','{"options": ["Fidel V. Ramos", "Joseph Estrada", "Ferdinand Marcos", "Corazon Aquino"], "correct": 0, "decode": "RA 8050 was approved on June 7, 1995 by President FIDEL V. RAMOS.", "ow": ["Correct. Approved by Fidel V. Ramos.", "Joseph Estrada was president later, not in 1995.", "Ferdinand Marcos was out of office by 1995.", "Corazon Aquino''s term ended in 1992."]}'),
  ('b818fdeb-1e','{"options": ["30", "35", "40", "45"], "correct": 1, "decode": "The minimum age for a Board of Optometry member is 35.", "ow": ["30 is below the minimum.", "Correct. At least 35 years old.", "The minimum is 35, not 40.", "The minimum is 35, not 45."]}'),
  ('8baaedb2-22','{"options": ["3 years", "15 years", "5 years", "10 years"], "correct": 3, "decode": "A Board member must have at least 10 years of active practice.", "ow": ["3 years is below the requirement.", "15 years exceeds the requirement.", "5 years is below the requirement.", "Correct. At least 10 years of active practice."]}'),
  ('84178369-1v','{"options": ["An officer of an optometric association", "An optometrist in private practice", "A natural-born Filipino optometrist", "A practitioner aged 40"], "correct": 0, "decode": "An OFFICER of an optometric association is DISQUALIFIED from the Board.", "ow": ["Correct. An association officer is disqualified.", "An optometrist in private practice is eligible.", "A natural-born Filipino optometrist is eligible.", "A practitioner aged 40 meets the age requirement."]}'),
  ('37a53d95-1o','{"options": ["2", "3", "4", "5"], "correct": 1, "decode": "A Board quorum requires 3 members (3 votes decide an administrative case).", "ow": ["2 is below the quorum.", "Correct. Quorum is 3.", "4 exceeds the quorum requirement.", "5 is the full Board, not the quorum."]}'),
  ('46e550d3-22','{"options": ["15 days", "90 days", "60 days", "30 days"], "correct": 2, "decode": "The President may suspend a Board member during an investigation for up to 60 days.", "ow": ["15 days understates the cap.", "90 days exceeds the cap.", "Correct. Up to 60 days.", "30 days understates the cap."]}'),
  ('d770ee09-1t','{"options": ["A PRC Commissioner", "Chairperson", "Ineligible to vote", "Vice-chairperson"], "correct": 1, "decode": "A Board member in the LAST year of his term automatically becomes CHAIRPERSON.", "ow": ["He does not become a PRC Commissioner.", "Correct. He automatically chairs the Board.", "He remains able to vote.", "He becomes chairperson, not vice-chairperson."]}'),
  ('5b9f2e21-1o','{"options": ["60 days", "90 days", "15 days", "30 days"], "correct": 0, "decode": "Board examination ratings must be reported to the PRC within 60 days.", "ow": ["Correct. Within 60 days.", "The window is 60 days, not 90.", "The window is 60 days, not 15.", "The window is 60 days, not 30."]}'),
  ('01c0c4b4-1c','{"options": ["Every two years", "Once a year", "Twice a year", "Every quarter"], "correct": 1, "decode": "The licensure examination must be given at least once a year (Sec 17).", "ow": ["It is at least yearly, not every two years.", "Correct. At least once a year.", "The minimum is once a year, not twice.", "It is at least yearly, not quarterly."]}'),
  ('d89741b5-2z','{"options": ["6 years", "8 years", "4 years", "5 years"], "correct": 0, "decode": "The Doctor of Optometry degree must come from a 6-year course.", "ow": ["Correct. A 6-year course.", "It is 6 years, not 8.", "It is 6 years, not 4.", "It is 6 years, not 5."]}'),
  ('7686c742-21','{"options": ["Being under 35 years of age", "Not belonging to an association", "Conviction of moral turpitude", "Practicing outside Metro Manila"], "correct": 2, "decode": "Conviction of a crime involving MORAL TURPITUDE disqualifies registration (Sec 24).", "ow": ["Being under 35 concerns Board membership, not registration disqualification.", "Not belonging to an association is not a Sec 24 disqualification.", "Correct. Moral turpitude conviction disqualifies.", "Practicing outside Metro Manila is not a disqualification."]}'),
  ('d419c430-1y','{"options": ["DOH Secretary", "CHED Chairperson", "PRC Commissioner", "President of the Philippines"], "correct": 2, "decode": "The certificate of registration is signed by all Board members and the PRC COMMISSIONER.", "ow": ["The DOH Secretary does not sign it.", "The CHED Chairperson does not sign it.", "Correct. The PRC Commissioner signs it.", "The President does not sign the certificate."]}'),
  ('a9a530c2-22','{"options": ["Under a registered optometrist", "After passing the board exam", "During supervised summer terms", "Inside government clinics only"], "correct": 0, "decode": "Under Section 5, a student or graduate may examine patients only UNDER a registered optometrist''s direct supervision.", "ow": ["Correct. Only under direct supervision.", "Supervised practice is allowed before passing the board, under supervision.", "It is not limited to supervised summer terms.", "It is not limited to government clinics."]}'),
  ('6741fc4f-1p','{"options": ["Whether DPAs were instilled", "Whether payment was received", "Whether a clinic was used", "The nature of the act itself"], "correct": 3, "decode": "Whether an act is the practice of optometry depends on the NATURE OF THE ACT itself (Sec 4), not payment.", "ow": ["It does not depend on whether DPAs were instilled.", "Free service is still practice; payment is irrelevant.", "It does not depend on whether a clinic was used.", "Correct. The nature of the act defines practice."]}'),
  ('d82e274d-1v','{"options": ["The Board of Optometry", "The PRC", "The DOH", "CHED"], "correct": 3, "decode": "The Technical Panel on Optometric Education (Sec 30) is convened by CHED (under RA 7722).", "ow": ["The Board of Optometry does not convene it.", "The PRC does not convene it.", "The DOH does not convene it.", "Correct. CHED convenes the Technical Panel."]}'),
  ('b9861b77-1x','{"options": ["No one, it is a juridical person", "The PRC", "Its managing officers", "The corporation''s shareholders"], "correct": 2, "decode": "Under Section 33, when a corporation violates RA 8050, its MANAGING OFFICERS are liable.", "ow": ["A corporation cannot hide behind its legal personality.", "The PRC is a regulator, not the liable party.", "Correct. The managing officers are liable.", "Not the shareholders; the managing officers are liable."]}'),
  ('a86e79c1-16','{"options": ["Charging a professional fee", "Advertising that one charges lower fees", "Referring a patient onward", "Displaying the registration certificate"], "correct": 1, "decode": "Advertising that one charges LOWER FEES is a prohibited act under Section 32.", "ow": ["Charging a professional fee is not prohibited.", "Correct. Lower-fee advertising is prohibited.", "Referring a patient onward is not prohibited.", "Displaying the registration certificate is required, not prohibited."]}'),
  ('41861820-22','{"options": ["30 days", "60 days", "15 days", "Immediately"], "correct": 0, "decode": "The IRR takes effect 30 days after publication (the law itself took effect 15 days after publication).", "ow": ["Correct. IRR effective 30 days after publication.", "The IRR is 30 days, not 60.", "15 days is the law''s effectivity, not the IRR''s.", "It is not immediate."]}'),
  ('0245f7dc-2o','{"options": ["1 year", "5 years", "10 years", "3 years"], "correct": 3, "decode": "Already-registered optometrists had 3 years to join the integrated national organization (Sec 36).", "ow": ["The window is 3 years, not 1.", "The window is 3 years, not 5.", "The window is 3 years, not 10.", "Correct. A 3-year integration window."]}'),
  ('5923cee7-1s','{"options": ["He holds a Philippine O.D. degree", "He is over 35 years of age", "His country reciprocates", "He is endorsed by the DOH"], "correct": 2, "decode": "A foreigner may sit the licensure examination only if his country RECIPROCATES (Sec 34).", "ow": ["Holding a Philippine O.D. degree is not the reciprocity condition.", "Being over 35 concerns Board membership, not foreign examinees.", "Correct. Only on reciprocity.", "DOH endorsement is not the reciprocity condition."]}'),
  ('9704ec8e-1v','{"options": ["1902", "1917", "1957", "1995"], "correct": 1, "decode": "The first regulatory optometry law in the Philippines was passed in 1917.", "ow": ["1902 was R.M. Clark''s clinic, not the first law.", "Correct. The 1917 Optometry Law.", "1957 is RA 1998, not the first law.", "1995 is RA 8050, the current law."]}'),
  ('558f13d6-1f','{"options": ["The Council of Deans", "The Board of Optometry", "The PRC", "The Junta Examinadora"], "correct": 3, "decode": "The 1917 Optometry Law created the JUNTA EXAMINADORA.", "ow": ["The Council of Deans is a later body.", "The Board of Optometry came later.", "The PRC came much later.", "Correct. The 1917 law created the Junta Examinadora."]}'),
  ('297391f9-1e','{"options": ["R.M. Clark", "Otto Becker", "Louis de Wecker", "Ernst Fuchs"], "correct": 2, "decode": "Jose Rizal trained in ophthalmology in Paris under LOUIS DE WECKER (1885).", "ow": ["R.M. Clark set up the Manila clinic; he did not train Rizal.", "Otto Becker trained Rizal in Germany, not Paris.", "Correct. Louis de Wecker in Paris.", "Ernst Fuchs trained Rizal in Vienna, not Paris."]}'),
  ('c82f8c16-37','{"options": ["Justo Gonzalez", "Federico Sarabia Sr.", "R.M. Clark", "William G. Moore"], "correct": 2, "decode": "The first refracting clinic and lens-grinding shop in Manila (1902) were established by R.M. CLARK.", "ow": ["Justo Gonzalez is not credited with the 1902 clinic.", "Federico Sarabia Sr. is cited as the reputed first Filipino optometrist, not the 1902 clinic founder.", "Correct. R.M. Clark, 1902.", "William G. Moore is not credited with the 1902 clinic."]}'),
  ('c83dcf37-20','{"options": ["De Ocampo Memorial College", "Manila College of Optometry", "Centro Escolar University", "The Philippine College of Optometry"], "correct": 2, "decode": "The first university-affiliated optometry college was CENTRO ESCOLAR UNIVERSITY (1928).", "ow": ["De Ocampo Memorial College is not the first university-affiliated one.", "The Manila College of Optometry is not the first university-affiliated one.", "Correct. CEU (1928).", "The Philippine College of Optometry was the first school overall, not university-affiliated."]}'),
  ('9ac803b0-1f','{"options": ["Dr. Manuel Sabater", "Bibiana Roxas de Jesus", "Justo Gonzalez", "Federico Sarabia Sr."], "correct": 0, "decode": "Registration Certificate No. 1 (1918) was issued to Dr. MANUEL SABATER.", "ow": ["Correct. Manuel Sabater (1918).", "Bibiana Roxas de Jesus did not hold Certificate No. 1.", "Justo Gonzalez did not hold Certificate No. 1.", "Federico Sarabia Sr. is the reputed first, but Certificate No. 1 went to Sabater."]}'),
  ('d87aed5a-19','{"options": ["APCO", "WCO", "IFAPAO", "SOP"], "correct": 3, "decode": "The 1979 merger of OAP, PODA, and PROA produced the SOP.", "ow": ["APCO is a later regional body, not the 1979 merger result.", "The WCO is the world council, not the 1979 merger.", "IFAPAO is the Asian-Pacific federation, not the 1979 merger.", "Correct. OAP + PODA + PROA = SOP (1979)."]}'),
  ('c84082ee-27','{"options": ["Toronto", "Bali", "Sydney", "Manila"], "correct": 3, "decode": "IFAPAO was founded at the 1st Asian-Pacific Optometric Congress in 1978 in MANILA.", "ow": ["Toronto did not host the 1st APOC.", "Bali hosted the 2nd APOC, not the founding.", "Sydney did not host the 1st APOC.", "Correct. Manila, 1978."]}'),
  ('611710bd-1n','{"options": ["Svein Hommerstad", "Henry W. Hofstetter", "Claro M. Cinco", "Justo Gonzalez"], "correct": 2, "decode": "The first International Optometrist of the Year (1988) was Dr. CLARO M. CINCO.", "ow": ["Svein Hommerstad was a later recipient.", "Henry W. Hofstetter was a later recipient.", "Correct. Claro M. Cinco (1988).", "Justo Gonzalez did not receive the first award."]}'),
  ('370cce5c-21','{"options": ["Approved by the Board first", "Qualified with ''optometrist''", "Preceded by the license number", "Used only inside the clinic"], "correct": 1, "decode": "Using the title ''Doctor'' is unethical unless QUALIFIED with ''optometrist'' (so the public is not misled).", "ow": ["Board approval is not the requirement.", "Correct. ''Dr.'' must be qualified with optometry/optometrist.", "The license number is not the qualifier.", "It is not merely limited to clinic use."]}'),
  ('c97d767d-27','{"options": ["Six inches", "Two inches", "Four inches", "Twelve inches"], "correct": 0, "decode": "Street-level lettering is unethical when the letters exceed SIX inches.", "ow": ["Correct. The limit is six inches.", "The limit is six inches, not two.", "The limit is six inches, not four.", "The limit is six inches, not twelve."]}'),
  ('bc7fcccb-1d','{"options": ["Return the patient to the referrer", "Bill the referring optometrist", "Report the referrer to the Board", "Take over the patient''s care"], "correct": 0, "decode": "A consultant who receives a referred patient must RETURN the patient to the referrer.", "ow": ["Correct. Return the patient to the referrer.", "The consultant does not bill the referring optometrist.", "The consultant does not report the referrer to the Board.", "The consultant does not take over the patient''s care."]}'),
  ('e7386a47-1u','{"options": ["Shared with the next practitioner", "Reportable to the association", "Recorded in the public register", "Held in trust, disclosed only by law"], "correct": 3, "decode": "A patient''s character flaws learned during care are HELD IN TRUST, disclosed only when the law requires.", "ow": ["They are not shared with the next practitioner freely.", "They are not reportable to the association.", "They are not recorded in the public register.", "Correct. Held in trust, disclosed only by law."]}'),
  ('1fe9a1d4-1b','{"options": ["Letting a lay person examine", "Referring a difficult case onward", "Charging by skill and time spent", "Joining a professional association"], "correct": 0, "decode": "Letting a LAY PERSON examine is expressly unethical under the Code.", "ow": ["Correct. A lay person must never do the visual examination.", "Referring a difficult case onward is proper.", "Charging by skill and time spent is proper.", "Joining a professional association is proper."]}'),
  ('cca5dd17-29','{"options": ["Say nothing, out of collegiality", "Advertise the fact publicly", "Expose them to the Board", "Confront them privately only"], "correct": 2, "decode": "On discovering a corrupt or dishonest colleague, the optometrist should EXPOSE them to the Board.", "ow": ["Saying nothing out of collegiality is not the duty.", "Advertising the fact publicly is improper.", "Correct. Expose them to the Board.", "Confronting privately only is insufficient."]}'),
  ('0f796ab4-2b','{"options": ["Only with prior Board approval", "No, refusal is always unethical", "No, never in an emergency", "Yes, he chooses his patients"], "correct": 3, "decode": "An optometrist MAY refuse to accept a patient (he chooses his patients), even as the only practitioner in town.", "ow": ["Prior Board approval is not required to decline.", "Refusal is not always unethical.", "Nothing in the Code compels service even in an emergency.", "Correct. He may choose his patients."]}'),
  ('4a4e8583-18','{"options": ["Owned by the PRC", "Transferable only to optometrists", "Exempt from execution as tools of the trade", "Taxable as inventory"], "correct": 2, "decode": "An optometrist''s instruments and library are EXEMPT FROM EXECUTION as tools of the trade.", "ow": ["They are not owned by the PRC.", "They are not transferable only to optometrists.", "Correct. Exempt from execution as tools of the trade.", "They are not taxable as inventory in this context."]}'),
  ('e7ed0848-23','{"options": ["People v. Pomar", "Schloendorff", "Safian v. Aetna", "Picart v. Smith"], "correct": 1, "decode": "The classic statement of the patient''s right to self-determination comes from SCHLOENDORFF (Cardozo, 1914).", "ow": ["People v. Pomar concerns police power, not self-determination.", "Correct. Schloendorff (Cardozo, 1914).", "Safian v. Aetna concerns breach of contract, not self-determination.", "Picart v. Smith is the negligence foreseeability test."]}'),
  ('7ae71b5b-2d','{"options": ["Professional courtesy", "A written fee agreement", "Trust and full disclosure", "Statutory duty alone"], "correct": 2, "decode": "The optometrist-patient relationship is FIDUCIARY, built on TRUST and full disclosure.", "ow": ["Professional courtesy is not the fiduciary basis.", "A written fee agreement is not the fiduciary basis.", "Correct. Built on trust and full disclosure.", "It rests on more than statutory duty alone."]}'),
  ('10c1f6dd-1z','{"options": ["Compulsory immunization", "A cycloplegic refraction", "A contact lens fitting", "A vision screening"], "correct": 0, "decode": "Consent is not required when the law compels a procedure, such as COMPULSORY IMMUNIZATION (RA 3573, PD 996).", "ow": ["Correct. Compulsory immunization needs no consent.", "A cycloplegic refraction requires consent.", "A contact lens fitting requires consent.", "A vision screening requires consent."]}'),
  ('f504c9c5-1d','{"options": ["May be reported to the Board", "May refuse; he is master of his own body", "Loses the right to any care", "Must be treated anyway"], "correct": 1, "decode": "A competent patient who refuses sight-saving care MAY REFUSE; he is master of his own body.", "ow": ["Refusing care is not itself a reportable matter.", "Correct. He may refuse; he is master of his own body.", "He does not lose the right to any care.", "He must not be treated against his refusal."]}'),
  ('f0380198-1d','{"options": ["Continue care for 30 days", "Obtain Board clearance first", "Refund all fees already paid", "Hand over records and inform"], "correct": 3, "decode": "When an optometrist withdraws from a case, he must HAND OVER records and INFORM the patient.", "ow": ["He is not obliged to continue care for a fixed 30 days.", "Board clearance is not required to withdraw.", "He need not refund all fees already paid.", "Correct. Hand over records and inform the patient."]}'),
  ('67a94ead-1t','{"options": ["Two", "Four", "One", "Three"], "correct": 0, "decode": "The PRC is composed of one Chairperson and TWO Commissioners.", "ow": ["Correct. One Chair and two Commissioners.", "There are two Commissioners, not four.", "There are two Commissioners, not one.", "There are two Commissioners, not three."]}'),
  ('8495917e-1c','{"options": ["7 years, no reappointment", "6 years, renewable once", "5 years, non-renewable", "3 years, renewable"], "correct": 0, "decode": "A PRC Chairperson or Commissioner serves a 7-year term with NO reappointment.", "ow": ["Correct. 7 years, no reappointment.", "It is 7 years no reappointment, not 6 renewable once.", "5 years non-renewable is the Board of Optometry term, not the PRC.", "It is 7 years, not 3 renewable."]}'),
  ('40feec77-1k','{"options": ["30", "35", "40", "45"], "correct": 2, "decode": "The minimum age for a PRC Chairperson or Commissioner is 40 (the Board of Optometry minimum is 35).", "ow": ["30 is below the PRC minimum.", "35 is the Board of Optometry minimum, not the PRC.", "Correct. At least 40 years old.", "45 exceeds the minimum."]}'),
  ('5cfc095e-z','{"options": ["PD 996", "RA 7722", "RA 3573", "PD 223"], "correct": 3, "decode": "The PRC was created by PD 223 (modernized by RA 8981, 2000).", "ow": ["PD 996 concerns compulsory immunization, not the PRC.", "RA 7722 is the Higher Education Act.", "RA 3573 concerns reporting of communicable diseases.", "Correct. PD 223 created the PRC."]}'),
  ('79af9188-21','{"options": ["RA 8050", "PD 223", "RA 8981", "RA 1998"], "correct": 1, "decode": "PD 223 (as amended by PD 657) renamed the body the BOARD OF OPTOMETRY.", "ow": ["RA 8050 governs the Board''s present functions but did not rename it.", "Correct. PD 223/657 renamed it.", "RA 8981 modernized the PRC but did not rename the Board.", "RA 1998 is the old optometry law, not the renaming decree."]}'),
  ('ec20e854-2f','{"options": ["Office of the President", "Supreme Court", "Court of Appeals", "Regional Trial Court"], "correct": 0, "decode": "An administrative decision, once appealed to the PRC, may be elevated to the OFFICE OF THE PRESIDENT.", "ow": ["Correct. Board then PRC then Office of the President.", "The Supreme Court is not the next administrative step.", "The Court of Appeals handles criminal/civil, not this administrative chain.", "The Regional Trial Court is not the administrative appeal path."]}'),
  ('5802f192-10','{"options": ["Barred from rejecting nominees", "Bound to appoint the top nominee", "Required to consult the DOH", "Not bound by the association''s nominees"], "correct": 3, "decode": "Under PMA v. Dr. Cruz, the President is NOT BOUND by the association''s nominees (a recommendation is only advice).", "ow": ["He is not barred from rejecting nominees.", "He is not bound to appoint the top nominee.", "He is not required to consult the DOH.", "Correct. The President is not bound by the nominees."]}'),
  ('9ea2318f-33','{"options": ["Provincial or City Fiscal", "PRC Legal Division", "Court of Appeals", "Board of Optometry"], "correct": 0, "decode": "Under PRC Resolution No. 114, a criminal action against an illegal (non-professional) practitioner is filed with the PROVINCIAL or CITY FISCAL.", "ow": ["Correct. File with the Provincial or City Fiscal.", "The PRC Legal Division does not file the criminal information.", "The Court of Appeals is an appellate court, not where it is filed.", "The Board starts the action but files it with the Fiscal."]}'),
  ('20290302-1v','{"options": ["Power of eminent domain", "Police power", "Parens patriae doctrine", "Power of taxation"], "correct": 1, "decode": "The practice of optometry is a privilege the state grants under its POLICE POWER.", "ow": ["Eminent domain concerns taking property, not licensing.", "Correct. Under police power.", "Parens patriae concerns the state as guardian, not licensing generally.", "The power of taxation is not the licensing basis."]}'),
  ('45d84965-18','{"options": ["It is barred by the Corporation Code", "It cannot own instruments", "It cannot afford the license fees", "It cannot meet the personal qualifications"], "correct": 3, "decode": "A corporation cannot practice optometry because it cannot meet the PERSONAL qualifications (good moral character, a degree, an oath).", "ow": ["The bar is the lack of personal qualifications, not merely a Corporation Code prohibition.", "Owning instruments is not the reason.", "License-fee affordability is not the reason.", "Correct. It cannot meet the personal qualifications."]}'),
  ('80e124e2-1r','{"options": ["Walk-in patients only", "Anyone, if a license is shown", "The employer''s own employees", "The general public in the store"], "correct": 2, "decode": "An optometrist employed by a non-optometrist may lawfully serve the EMPLOYER''S OWN EMPLOYEES, not the general public.", "ow": ["Not walk-in patients generally.", "Not anyone merely because a license is shown.", "Correct. The employer''s own employees.", "Not the general public in the store."]}'),
  ('515e7ea0-2e','{"options": ["Engaged in illegal practice", "Committing only an ethical breach", "Exempt under RA 8050 Section 5", "Protected by religious freedom"], "correct": 0, "decode": "A faith healer who prays and then picks up DIAGNOSTIC INSTRUMENTS is engaged in ILLEGAL PRACTICE (prayer is religion; instruments cross into practice).", "ow": ["Correct. Using instruments makes it illegal practice.", "It is more than an ethical breach; it is illegal practice.", "Section 5 does not exempt a faith healer using instruments.", "Religious freedom protects belief, not unlicensed practice with instruments."]}'),
  ('0747cde3-1k','{"options": ["A specialist would have done better", "A prudent person would have foreseen the harm", "The patient consented", "The result was unfavorable"], "correct": 1, "decode": "The test for negligence (Picart v. Smith) asks whether a PRUDENT PERSON would have foreseen the harm.", "ow": ["It is the prudent-person standard, not a specialist-comparison test.", "Correct. Whether a prudent person would foresee the harm.", "Patient consent is a separate issue, not the negligence test.", "An unfavorable result alone is not negligence."]}'),
  ('889c6940-1m','{"options": ["Charged an excessive fee", "Did not refer promptly", "Specifically promised a cure or result", "Failed to cure the patient"], "correct": 2, "decode": "An optometrist is liable for breach of contract only if he SPECIFICALLY PROMISED a cure or result.", "ow": ["An excessive fee is a fee dispute, not a breach of a promised result.", "Failing to refer promptly may be negligence, not breach of a promised result.", "Correct. Breach of contract needs a promised result.", "Failing to cure is not a breach when no cure was contracted."]}'),
  ('a50d38ab-20','{"options": ["Quasi-delict", "Administrative offence only", "Breach of contract", "Criminal felony"], "correct": 0, "decode": "Damage from fault or negligence with NO prior contract is a QUASI-DELICT (Civil Code Art. 2176).", "ow": ["Correct. No contract plus negligence is a quasi-delict.", "It is a civil wrong, not merely an administrative offence.", "Breach of contract requires a prior contract.", "It is a quasi-delict, not necessarily a criminal felony."]}'),
  ('45b4e950-1c','{"options": ["Slander", "Fraud", "Perjury", "Deceit"], "correct": 0, "decode": "Written defamation is libel; SPOKEN defamation is SLANDER.", "ow": ["Correct. Spoken defamation is slander.", "Fraud is deceit for gain, not spoken defamation.", "Perjury is lying under oath, not defamation.", "Deceit is misrepresentation, not spoken defamation."]}'),
  ('3c54c0e3-1p','{"options": ["Nearest descendant", "Spouse", "Nearest ascendant", "Brothers and sisters"], "correct": 1, "decode": "If a patient dies owing fees, the claim runs first against the SPOUSE (Civil Code Art. 291 order: spouse, descendant, ascendant, siblings).", "ow": ["The nearest descendant comes after the spouse.", "Correct. The spouse is first in the order.", "The nearest ascendant comes after descendants.", "Brothers and sisters come last."]}'),
  ('0b839ef9-15','{"options": ["He has no money at present", "A third party promised to pay", "The result was disappointing", "A contingent fee did not succeed"], "correct": 3, "decode": "A patient may lawfully refuse to pay when a CONTINGENT FEE did not succeed (despite the patient''s cooperation).", "ow": ["Having no money at present is not a lawful ground to refuse.", "A third party''s promise never releases the patient.", "A disappointing result alone is not a ground to refuse.", "Correct. A failed contingent fee is a valid ground."]}'),
  ('f52cc244-1e','{"options": ["The integrated organization", "The PRC", "The referring optometrist", "The patient"], "correct": 3, "decode": "On a referral, the consultant''s fee is owed by the PATIENT (not the referring optometrist).", "ow": ["The integrated organization does not owe the fee.", "The PRC does not owe the fee.", "The referring optometrist is not liable for the consultant''s fee.", "Correct. The patient owes the consultant''s fee."]}'),
  ('767ecaeb-27','{"options": ["PD 223", "RA 8050", "RA 7722", "RA 8981"], "correct": 3, "decode": "Section 29''s continuing-education-for-renewal condition was repealed by RA 8981 (PRC Modernization Act, 2000).", "ow": ["PD 223 created the PRC; it did not repeal Sec 29.", "RA 8050 wrote the rule; it did not repeal it.", "RA 7722 is the Higher Education Act.", "Correct. RA 8981 repealed Sec 29''s CPD-for-renewal rule."]}'),
  ('c7cc62ba-2m','{"options": ["Passes", "Passes conditionally", "Fails", "Must retake only that subject"], "correct": 2, "decode": "A 78% average with a 48% in one subject FAILS: Sec 20 requires at least 75% AND no rating below 50%.", "ow": ["The 48% disqualifies despite the high average.", "There is no conditional pass; the 48% fails.", "Correct. Fails on the sub-50% subject.", "There is no single-subject retake; the candidate fails."]}'),
  ('92fdee1f-29','{"options": ["3 members from 6 nominees", "7 members from 14 nominees", "5 members from 5 nominees", "5 members from 10 nominees"], "correct": 3, "decode": "The Board of Optometry is 5 members from 10 nominees (appointed by the President on PRC recommendation).", "ow": ["It is 5 from 10, not 3 from 6.", "It is 5 from 10, not 7 from 14.", "It is 5 from 10, not 5 from 5.", "Correct. 5 members from 10 nominees."]}'),
  ('70b32ae8-2l','{"options": ["Allowed only in print media", "Allowed with Board approval", "A prohibited act", "Allowed if the claim is true"], "correct": 2, "decode": "An ad claiming ''lower fees than any clinic'' is a PROHIBITED ACT (Sec 32c); truth is no defense.", "ow": ["It is not allowed only in print media.", "Board approval does not permit it.", "Correct. A prohibited act.", "Truth does not make it allowed."]}'),
  ('9730a401-23','{"options": ["Community service order", "License suspension only", "1–8 years or P10,000–40,000", "A fine only, up to P5,000"], "correct": 2, "decode": "Unauthorized practice is punished under Sec 33: 1 to 8 years, or P10,000 to P40,000, or both.", "ow": ["A community service order is not the statutory penalty.", "It is more than license suspension alone.", "Correct. 1 to 8 years or P10,000 to P40,000 (or both).", "It is more than a P5,000 fine."]}'),
  ('a65b7244-4y','{"options": ["Collegiality", "Autonomy", "Justice", "Beneficence"], "correct": 1, "decode": "Instilling a dilating drop without disclosing effects or asking permission violates AUTONOMY.", "ow": ["Collegiality concerns colleagues, not patient consent.", "Correct. It violates the patient''s autonomy.", "Justice is fairness, not the consent issue.", "Beneficence is doing good, not the consent issue."]}'),
  ('a480a98f-3w','{"options": ["Autonomy", "Non-maleficence", "Justice", "Confidentiality"], "correct": 1, "decode": "Declining extended-wear lenses in a non-compliant patient with prior microbial keratitis reflects NON-MALEFICENCE.", "ow": ["Autonomy is the patient''s right to decide, not the clinician''s avoid-harm duty.", "Correct. Avoiding foreseeable harm is non-maleficence.", "Justice is fairness, not the avoid-harm issue.", "Confidentiality concerns privacy, not this decision."]}'),
  ('08e16d8a-2h','{"options": ["Refuse to see the patient again", "Report the patient to the Board", "Override the refusal and refer anyway", "Document, re-counsel, keep monitoring"], "correct": 3, "decode": "When a competent adult refuses referral for a suspicious disc, the ethical action is DOCUMENT, RE-COUNSEL, and keep MONITORING.", "ow": ["Refusing to see the patient again is abandonment.", "Reporting the patient to the Board is inappropriate.", "Overriding the refusal violates autonomy.", "Correct. Document, re-counsel, keep monitoring."]}'),
  ('c98cd55c-3c','{"options": ["Beneficence", "Non-maleficence", "Justice", "Autonomy"], "correct": 2, "decode": "Giving a PhilHealth patient a lesser examination than a private patient violates JUSTICE (equal standard of care).", "ow": ["Beneficence is doing good, not the equal-standard issue.", "Non-maleficence is avoiding harm, not the equal-standard issue.", "Correct. It violates distributive justice.", "Autonomy is the patient''s right to decide, not equal standard."]}'),
  ('f025cbcc-2p','{"options": ["Consider the visual welfare of the public as the primary responsibility", "Refer for medical attention when indicated", "Respect confidentiality", "Render services with equal diligence to all"], "correct": 1, "decode": "The Sec 40 duty ''refer for medical attention when indicated'' maps to NON-MALEFICENCE (referring beyond competence prevents harm).", "ow": ["Visual welfare of the public is beneficence.", "Correct. Referring when indicated is non-maleficence.", "Confidentiality protects trust/privacy, not referral.", "Equal diligence to all is justice."]}'),
  ('485365e5-2h','{"options": ["Mayor → DTI → BIR → Barangay", "DTI → Barangay → Mayor → BIR", "Barangay → BIR → DTI → Mayor", "BIR → Mayor → Barangay → DTI"], "correct": 1, "decode": "To open a sole-proprietorship clinic: DTI then Barangay then Mayor then BIR.", "ow": ["Mayor first is out of order.", "Correct. DTI then Barangay then Mayor then BIR.", "Barangay first is out of order.", "BIR first is out of order."]}'),
  ('0709a882-3a','{"options": ["Nothing; the owner runs the business", "Labor law on working hours", "Chair time is the doctor''s discretion", "Advertising rules on service claims"], "correct": 2, "decode": "An owner ordering ten-minute exams violates the rule that CHAIR TIME is the doctor''s discretion (Board Resolution No. 11, Sec 48).", "ow": ["It is a violation, not ''nothing''.", "It is not primarily a working-hours labor-law issue.", "Correct. Chair time is the optometrist''s discretion.", "It is not an advertising-rule issue."]}'),
  ('5b2f2e97-1c','{"options": ["\"The best optometrist in the region\"", "\"Lowest eyeglass prices in the city\"", "\"Free eye exam with every purchase\"", "A dignified statement of services"], "correct": 3, "decode": "A DIGNIFIED statement of services is the permitted advertisement.", "ow": ["''The best optometrist in the region'' is a prohibited superiority claim.", "''Lowest eyeglass prices'' is a prohibited price claim.", "''Free eye exam with every purchase'' is a prohibited free-service offer.", "Correct. A dignified statement of services is permitted."]}'),
  ('e20161f6-1s','{"options": ["5 sq m and 6 m", "8 sq m and 4 m", "20 sq m and 6 m", "10 sq m and 3 m"], "correct": 3, "decode": "The minimum examination room area and test distance are 10 square meters and 3 meters (Board Resolution No. 11).", "ow": ["5 sq m and 6 m are not the required minimums.", "8 sq m and 4 m are not the required minimums.", "20 sq m and 6 m are not the required minimums.", "Correct. 10 sq m and 3 m."]}'),
  ('05bb894f-2x','{"options": ["15 days", "60 days", "90 days", "30 days"], "correct": 3, "decode": "After securing premises, the optometrist must notify the Board of the location within 30 days.", "ow": ["The window is 30 days, not 15.", "The window is 30 days, not 60.", "The window is 30 days, not 90.", "Correct. Within 30 days."]}'),
  ('f398145c-23','{"options": ["Professional license", "Certificate of registration", "PRC", "Board of Optometry"], "correct": 2, "decode": "The government body that supervises the Board of Optometry is the PRC (Professional Regulation Commission).", "ow": ["A professional license is a credential, not a supervising body.", "A certificate of registration is a document, not a supervising body.", "Correct. The PRC supervises the Board.", "The Board of Optometry is what is supervised, not the supervisor."]}'),
  ('566eb04c-1y','{"options": ["Certificate of registration", "PRC", "Board of Optometry", "Professional license"], "correct": 2, "decode": "5 members with a 5-year non-renewable term under the PRC describes the BOARD OF OPTOMETRY.", "ow": ["A certificate of registration is a document, not the Board.", "The PRC is the supervising commission, not the 5-member board.", "Correct. The Board of Optometry.", "A professional license is a credential, not the Board."]}'),
  ('4fab2289-21','{"options": ["Certificate of registration", "PRC", "Professional license", "Board of Optometry"], "correct": 0, "decode": "The document issued by the PRC after the oath and displayed in the clinic is the CERTIFICATE OF REGISTRATION.", "ow": ["Correct. The certificate of registration.", "The PRC is the issuing commission, not the document.", "A professional license is the renewable card, not the post-oath certificate.", "The Board of Optometry is a body, not the document."]}'),
  ('e04745c6-1w','{"options": ["Professional license", "Board of Optometry", "PRC", "Certificate of registration"], "correct": 0, "decode": "The credential renewed every 3 years with continuing education is the PROFESSIONAL LICENSE.", "ow": ["Correct. The professional license.", "The Board of Optometry is a body, not the renewed credential.", "The PRC is the commission, not the credential.", "The certificate of registration is issued once after the oath, not renewed every 3 years."]}'),
  ('fce566bd-1y','{"options": ["Certificate of registration", "Board of Optometry", "PRC", "DPA"], "correct": 3, "decode": "The agent requiring pharmacology certification (Sec 31) to use is the DPA (Diagnostic Pharmaceutical Agent).", "ow": ["A certificate of registration is a document, not a drug.", "The Board of Optometry is a body, not a drug.", "The PRC is the commission, not a drug.", "Correct. The DPA."]}'),
  ('45435f20-24','{"options": ["Board of Optometry", "Certificate of registration", "Orthoptics", "PRC"], "correct": 2, "decode": "Eye-muscle and vision training within optometry''s scope is ORTHOPTICS.", "ow": ["The Board of Optometry is a regulatory body, not the training.", "A certificate of registration is a document, not the training.", "Correct. Orthoptics.", "The PRC is the commission, not the training."]}'),
  ('a394ff54-21','{"options": ["PRC", "Board of Optometry", "Certificate of registration", "Primary health care"], "correct": 3, "decode": "RA 8050 declares optometry a regular component of PRIMARY HEALTH CARE.", "ow": ["The PRC is the commission, not the health-care category.", "The Board of Optometry is a body, not the category.", "A certificate of registration is a document, not the category.", "Correct. Primary health care."]}'),
  ('2fd89619-21','{"options": ["Certificate of registration", "Board of Optometry", "Integration", "PRC"], "correct": 2, "decode": "All ODs are integrated into one national organization that promulgates the Code: INTEGRATION (Sec 36).", "ow": ["A certificate of registration is a document, not the integration.", "The Board of Optometry is a body, not the integration.", "Correct. Integration (Sec 36).", "The PRC is the commission, not the integration."]}'),
  ('1b400914-20','{"options": ["Certificate of registration", "Prohibited act", "Board of Optometry", "PRC"], "correct": 1, "decode": "Comparative/price advertising and untrained DPA use are examples of a PROHIBITED ACT (Sec 32).", "ow": ["A certificate of registration is a document, not a prohibited act.", "Correct. A prohibited act (Sec 32).", "The Board of Optometry is a body, not a prohibited act.", "The PRC is the commission, not a prohibited act."]}'),
  ('dafdb65e-1m','{"options": ["Justice", "Non-maleficence", "Informed consent", "Beneficence"], "correct": 3, "decode": "Acting in the patient''s best interest is BENEFICENCE.", "ow": ["Justice is equal treatment, not acting for good.", "Non-maleficence is avoiding harm, not acting for good.", "Informed consent expresses autonomy, not acting for good.", "Correct. Beneficence."]}'),
  ('1de02d92-1m','{"options": ["Informed consent", "Beneficence", "Justice", "Non-maleficence"], "correct": 3, "decode": "''Do no harm'' where benefit must outweigh harm is NON-MALEFICENCE.", "ow": ["Informed consent expresses autonomy, not do-no-harm.", "Beneficence is doing good, not do-no-harm.", "Justice is fairness, not do-no-harm.", "Correct. Non-maleficence."]}'),
  ('114c3458-1s','{"options": ["Non-maleficence", "Informed consent", "Justice", "Beneficence"], "correct": 2, "decode": "An equal standard of care regardless of status is JUSTICE.", "ow": ["Non-maleficence is avoiding harm, not equal standard.", "Informed consent expresses autonomy, not equal standard.", "Correct. Justice.", "Beneficence is doing good, not equal standard."]}'),
  ('b9fcb40d-27','{"options": ["Justice", "Informed consent", "Beneficence", "Non-maleficence"], "correct": 1, "decode": "Understanding diagnosis, options, and risks (not just a signature) is INFORMED CONSENT.", "ow": ["Justice is fairness, not consent.", "Correct. Informed consent.", "Beneficence is doing good, not consent.", "Non-maleficence is avoiding harm, not consent."]}'),
  ('9a94a4cf-1v','{"options": ["Assent", "Beneficence", "Non-maleficence", "Justice"], "correct": 0, "decode": "A child''s agreement alongside parental consent is ASSENT.", "ow": ["Correct. Assent.", "Beneficence is doing good, not the child''s agreement.", "Non-maleficence is avoiding harm, not the child''s agreement.", "Justice is fairness, not the child''s agreement."]}'),
  ('1089ddac-1t','{"options": ["Confidentiality", "Justice", "Beneficence", "Non-maleficence"], "correct": 0, "decode": "Patient records and diagnoses being privileged is CONFIDENTIALITY.", "ow": ["Correct. Confidentiality.", "Justice is fairness, not privacy.", "Beneficence is doing good, not privacy.", "Non-maleficence is avoiding harm, not privacy."]}'),
  ('2d76305b-24','{"options": ["Informed consent", "Beneficence", "Non-maleficence", "Distributive justice"], "correct": 3, "decode": "The same standard for PhilHealth and private patients alike is DISTRIBUTIVE JUSTICE.", "ow": ["Informed consent expresses autonomy, not equal allocation.", "Beneficence is doing good, not equal allocation.", "Non-maleficence is avoiding harm, not equal allocation.", "Correct. Distributive justice."]}'),
  ('5090cf82-1y','{"options": ["Justice", "Non-maleficence", "Beneficence", "Beauchamp & Childress"], "correct": 3, "decode": "The four-principles model of bioethics originated with BEAUCHAMP & CHILDRESS.", "ow": ["Justice is one of the principles, not the authors.", "Non-maleficence is one of the principles, not the authors.", "Beneficence is one of the principles, not the authors.", "Correct. Beauchamp & Childress."]}'),
  ('6cb3a146-1q','{"options": ["BIR", "Mayor''s permit", "TIN", "Barangay clearance"], "correct": 0, "decode": "The body that registers the TIN and books of accounts (taxes) is the BIR.", "ow": ["Correct. The BIR.", "The Mayor''s permit is a business permit, not the tax registrar.", "The TIN is issued by the BIR; it is not itself the body.", "Barangay clearance is a location clearance, not tax registration."]}'),
  ('59b6a88c-1o','{"options": ["Barangay clearance", "Mayor''s permit", "BIR", "TIN"], "correct": 0, "decode": "The clearance of the clinic''s location to operate is the BARANGAY CLEARANCE.", "ow": ["Correct. Barangay clearance.", "The Mayor''s permit comes after and is a business permit.", "The BIR handles taxes, not location clearance.", "The TIN is a tax number, not a location clearance."]}'),
  ('89a453f0-1z','{"options": ["TIN", "BIR", "Barangay clearance", "Mayor''s permit"], "correct": 3, "decode": "The permit allowing operation after fire/sanitation inspections is the MAYOR''S PERMIT.", "ow": ["The TIN is a tax number, not the operating permit.", "The BIR handles taxes, not the operating permit.", "Barangay clearance is a location clearance, not the operating permit.", "Correct. The Mayor''s permit."]}'),
  ('25d21ea9-1u','{"options": ["TIN", "Barangay clearance", "BIR", "COR"], "correct": 3, "decode": "The proof of registration displayed in the clinic is the COR (Certificate of Registration).", "ow": ["The TIN is a tax number, not the registration proof.", "Barangay clearance is a location clearance, not registration proof.", "The BIR handles taxes, not this proof.", "Correct. The COR."]}'),
  ('8a5e02ba-1q','{"options": ["TIN", "PIC", "Barangay clearance", "BIR"], "correct": 1, "decode": "The current PRC ID displayed and kept updated is the PIC (Professional Identification Card).", "ow": ["The TIN is a tax number, not the PRC ID.", "Correct. The PIC.", "Barangay clearance is a location clearance, not the PRC ID.", "The BIR handles taxes, not the PRC ID."]}'),
  ('f284f2af-1v','{"options": ["Barangay clearance", "BIR", "CPD", "TIN"], "correct": 2, "decode": "The certificates displayed that support 3-year renewal are CPD (Continuing Professional Development).", "ow": ["Barangay clearance is a location clearance, not CPD.", "The BIR handles taxes, not CPD.", "Correct. CPD.", "The TIN is a tax number, not CPD."]}'),
  ('b017cd29-20','{"options": ["Barangay clearance", "TIN", "BIR", "Respondeat superior"], "correct": 3, "decode": "The optometrist being responsible for delegated staff acts is RESPONDEAT SUPERIOR.", "ow": ["Barangay clearance is a location clearance, not this doctrine.", "The TIN is a tax number, not this doctrine.", "The BIR handles taxes, not this doctrine.", "Correct. Respondeat superior."]}'),
  ('0c6a0599-1w','{"options": ["BIR", "Board Resolution", "Barangay clearance", "TIN"], "correct": 1, "decode": "Res 11 (2016) governs clinic rules and Res 1 (2008) advertising: these are BOARD RESOLUTIONS.", "ow": ["The BIR handles taxes, not these issuances.", "Correct. Board Resolution.", "Barangay clearance is a location clearance, not these issuances.", "The TIN is a tax number, not these issuances."]}'),
  ('1b5f856f-20','{"options": ["BIR", "Commercialization", "TIN", "Barangay clearance"], "correct": 1, "decode": "What the office and advertising rules guard against is COMMERCIALIZATION (turning care into retail).", "ow": ["The BIR handles taxes, not what the rules guard against.", "Correct. Commercialization.", "The TIN is a tax number, not what the rules guard against.", "Barangay clearance is a location clearance, not what the rules guard against."]}'),
  ('f1b44cfb-1u','{"options": ["The cost of materials", "The optometrist''s standing", "The value of the result to the patient", "The customary local fee"], "correct": 2, "decode": "''Good result, good pay'' refers to the VALUE OF THE RESULT to the patient.", "ow": ["The cost of materials is a separate determinant.", "The optometrist''s standing is a separate determinant.", "Correct. The value of the result to the patient.", "The customary local fee is a separate determinant."]}'),
  ('18001d0e-2m','{"options": ["Level of education", "Financial ability", "Choice of frame", "Social standing"], "correct": 1, "decode": "Fee-setting must account for the patient''s FINANCIAL ABILITY (so charity work is expected).", "ow": ["Level of education is not the fee determinant here.", "Correct. Financial ability.", "Choice of frame is a materials cost, not this determinant.", "Social standing is not the stated determinant."]}'),
  ('fdab8357-21','{"options": ["A luxury expense", "Support", "A commercial debt", "A gratuitous act"], "correct": 1, "decode": "Under Civil Code Article 290, medical and optometric care counts as SUPPORT.", "ow": ["It is not classed as a luxury expense.", "Correct. Care counts as support.", "It is support, which is what makes the Art. 291 claim run, not merely a commercial debt.", "It is not a gratuitous act."]}'),
  ('f7f5b261-1x','{"options": ["The patient changed optometrists", "The optometrist was negligent", "The patient is unemployed", "The result was merely disappointing"], "correct": 1, "decode": "A valid formal defense against a fee claim is that the OPTOMETRIST WAS NEGLIGENT.", "ow": ["The patient changing optometrists is not itself a defense.", "Correct. Negligence by the optometrist defeats the fee claim.", "The patient being unemployed is not a formal defense.", "A merely disappointing result is not a defense."]}'),
  ('b5505ece-28','{"options": ["The dictates of his conscience", "The PRC''s annual directive", "The patient''s ability to pay", "The referring doctor''s request"], "correct": 0, "decode": "An optometrist may limit his practice by specialty, location, days and hours, or by the DICTATES OF HIS CONSCIENCE.", "ow": ["Correct. The dictates of his conscience.", "The PRC''s annual directive is not a listed limit.", "The patient''s ability to pay is not a listed limit.", "The referring doctor''s request is not a listed limit."]}'),
  ('1307088c-1t','{"options": ["May stop at any time without notice", "Must transfer it to a specialist", "Must see it through, even outside usual hours", "May only continue during clinic hours"], "correct": 2, "decode": "Having accepted a case needing continuing care, the optometrist MUST SEE IT THROUGH, even outside usual hours.", "ow": ["He may not stop at any time without notice.", "He need not automatically transfer it to a specialist.", "Correct. He must see it through, even outside usual hours.", "He is not limited to continuing only during clinic hours."]}'),
  ('8b6bf3be-33','{"options": ["15 days", "30 days", "3 years", "3 days"], "correct": 0, "decode": "Despite many ''threes'' in the law, the appeal window is 15 DAYS.", "ow": ["Correct. The appeal window is 15 days.", "It is 15 days, not 30.", "3 years is the renewal cycle, not the appeal window.", "It is 15 days, not 3 days."]}'),
  ('65fef13d-x','{"options": ["Never take any risk with a patient", "The benefit must outweigh the harm", "Always refer rather than treat", "Treat every patient identically"], "correct": 1, "decode": "Non-maleficence is best stated as: the BENEFIT must outweigh the harm (not zero risk).", "ow": ["It does not mean never taking any risk.", "Correct. Benefit must outweigh harm.", "It does not mean always referring rather than treating.", "Treating everyone identically is justice, not non-maleficence."]}'),
  ('54c1a707-2l','{"options": ["Record", "Waiver", "Complete expression", "Legal substitute"], "correct": 0, "decode": "Autonomy is the patient''s RIGHT to decide; the consent form is only the RECORD of it.", "ow": ["Correct. The form is only the record.", "The form is not a waiver of the right.", "A signed form is not the complete expression; understanding is.", "The form is evidence, not a legal substitute for consent."]}'),
  ('aea00342-1l','{"options": ["Business name", "Barangay clearance", "Mayor''s permit", "TIN and books of accounts"], "correct": 0, "decode": "The DTI step of business setup registers the BUSINESS NAME (a 5-year certificate).", "ow": ["Correct. DTI registers the business name.", "Barangay clearance is a separate step.", "The Mayor''s permit is a separate step.", "The TIN and books of accounts come from the BIR."]}'),
  ('ee1dea23-36','{"options": ["Whichever the optical owner prefers", "Professionalism over commercialization", "Whichever maximizes patient volume", "Whichever the PRC has not banned"], "correct": 1, "decode": "Where a practice-management item offers a commercial and a professional answer, choose PROFESSIONALISM over commercialization.", "ow": ["The optical owner''s preference does not govern professional judgment.", "Correct. Professionalism over commercialization.", "Maximizing patient volume is a commercial motive.", "Not merely ''whatever the PRC has not banned''; choose the professional answer."]}'),
  ('4b6a8b15-29','{"options": ["RA 8050", "RA 11032", "RA 1998", "RA 7160"], "correct": 0, "decode": "The principal law regulating Philippine optometry is RA 8050 (Revised Optometry Law of 1995).", "ow": ["Correct. RA 8050.", "RA 11032 is the Ease of Doing Business Act.", "RA 1998 is not the current optometry law.", "RA 7160 is the Local Government Code."]}'),
  ('33d2bb24-n','{"options": ["June 7, 1995", "June 22, 1957", "January 1, 1996", "August 17, 1995"], "correct": 0, "decode": "RA 8050 was approved on June 7, 1995.", "ow": ["Correct. June 7, 1995.", "June 22, 1957 is not the RA 8050 date.", "January 1, 1996 is not the approval date.", "August 17, 1995 is a close-sounding distractor."]}'),
  ('3811b9e3-2o','{"options": ["DTI", "PRC", "CHED only", "DOH only"], "correct": 1, "decode": "The body that regulates optometry through the Board of Optometry is the PRC.", "ow": ["The DTI handles trade, not licensure.", "Correct. The PRC.", "CHED handles education, not licensure.", "The DOH handles health services, not licensure."]}'),
  ('5d7955a9-2a','{"options": ["Selling ordinary non-prescription sunglasses over the counter", "Manufacturing eyeglass cases and other optical accessories", "Selling lens-cleaning cloths and spray solutions at retail", "Examination of the human eye using objective and subjective procedures"], "correct": 3, "decode": "EXAMINATION of the human eye using objective and subjective procedures is an act constituting the practice of optometry.", "ow": ["Selling non-prescription sunglasses is retail, not practice.", "Manufacturing optical accessories is not clinical practice.", "Selling lens-cleaning supplies is retail, not practice.", "Correct. Examining the eye is optometric practice."]}'),
  ('0d79df42-2a','{"options": ["Only optical merchandising", "Outside optometry", "Acts constituting optometric practice", "Only medical acts"], "correct": 2, "decode": "Prescribing and dispensing ophthalmic lenses, prisms, and contact lenses are ACTS constituting optometric practice.", "ow": ["It is professional practice, not merely merchandising.", "It is within optometry, not outside it.", "Correct. Prescribing and dispensing corrective optics is optometric practice.", "It is not exclusively a medical act."]}'),
  ('d4dc1dae-1g','{"options": ["Only an administrative function", "Part of optometric practice", "Prohibited to optometrists", "Only performed by nurses"], "correct": 1, "decode": "Counseling patients on vision and eye care is PART of optometric practice.", "ow": ["It is a professional duty, not merely administrative.", "Correct. Counseling is part of optometric practice.", "It is not prohibited to optometrists.", "It is not a nurses-only task."]}'),
  ('4d7e2fc8-1y','{"options": ["Buying eyeglasses", "Purchasing optical equipment", "Practicing optometry", "Wearing spectacles"], "correct": 2, "decode": "A valid certificate of registration is required before PRACTICING optometry.", "ow": ["Buying eyeglasses is a consumer act, needing no license.", "Purchasing optical equipment needs no license.", "Correct. A COR is required before practicing.", "Wearing spectacles needs no license."]}'),
  ('77cabf86-13','{"options": ["Issue and regulate professional registration", "Operate all optical shops across the country", "Manufacture ophthalmic lenses and spectacle frames", "Set admission fees for public hospitals"], "correct": 0, "decode": "The Board of Optometry has authority to ISSUE and REGULATE professional registration.", "ow": ["Correct. Issue and regulate registration.", "It does not operate optical shops.", "It does not manufacture lenses or frames.", "It does not set hospital admission fees."]}'),
  ('02a79d01-15','{"options": ["Anger, impatience, and open dismissiveness", "Favoritism toward a few selected patients", "Discrimination based on a patient''s background", "Patience, delicacy, frankness, and respect"], "correct": 3, "decode": "An optometrist should treat patients with PATIENCE, DELICACY, FRANKNESS, and RESPECT.", "ow": ["Anger, impatience, and dismissiveness are unethical.", "Favoritism toward a few patients is unethical.", "Discrimination based on background is unethical.", "Correct. Patience, delicacy, frankness, and respect."]}'),
  ('b46e0a19-1y','{"options": ["Only when the patient asks", "Never", "Only after selling glasses", "In a timely and appropriate manner"], "correct": 3, "decode": "An optometrist should inform a patient about disease manifestations in a TIMELY and APPROPRIATE manner.", "ow": ["Disclosure should be proactive, not only when asked.", "Withholding findings is unethical.", "Disclosure must not be gated behind a sale.", "Correct. Timely and appropriate disclosure."]}'),
  ('7c993052-p','{"options": ["Exaggerate or minimize the seriousness of a patient''s condition", "Refer to another professional whenever it is clearly necessary", "Explain the examination findings clearly to the patient", "Provide appropriate advice about vision and eye care"], "correct": 0, "decode": "An optometrist should NOT EXAGGERATE or MINIMIZE the seriousness of a condition.", "ow": ["Correct. Distorting severity is the violation.", "Referring when clearly necessary is proper.", "Explaining findings clearly is proper.", "Providing appropriate advice is proper."]}'),
  ('89d7cd2b-2g','{"options": ["Hide the finding", "Refer the patient appropriately", "Continue treatment indefinitely", "Ignore it"], "correct": 1, "decode": "If a condition requires another professional''s services, the optometrist should REFER the patient appropriately.", "ow": ["Hiding the finding is unethical.", "Correct. Refer the patient appropriately.", "Continuing treatment indefinitely beyond scope endangers the patient.", "Ignoring it is unethical."]}'),
  ('0f9bd91f-21','{"options": ["Abandon the patient immediately without notice or onward referral", "Continue appropriate care or provide sufficient notice before withdrawal", "Refuse all further follow-up regardless of the clinical need", "Transfer the patient elsewhere without any explanation given"], "correct": 1, "decode": "After formally undertaking a case, the optometrist should CONTINUE care or give SUFFICIENT NOTICE before withdrawing.", "ow": ["Abandoning the patient without notice is unethical.", "Correct. Continue care or give sufficient notice.", "Refusing all follow-up despite need is unethical.", "Transferring without explanation is unethical."]}'),
  ('a58bdd94-11','{"options": ["Refer every emergency without assessment", "Respond to a request for assistance", "Refuse assistance automatically", "Demand payment before any assistance"], "correct": 1, "decode": "In an emergency, an optometrist should RESPOND to a request for assistance (within competence).", "ow": ["Referring every emergency without assessment is improper.", "Correct. Respond to the request for assistance.", "Refusing assistance automatically is improper.", "Demanding payment before assistance is improper."]}'),
  ('a304f0a5-1t','{"options": ["Sale of premium frames", "Visual welfare of the public", "Number of patients seen daily", "Profitability of the clinic"], "correct": 1, "decode": "The primary responsibility of an optometrist under RA 8050 is the VISUAL WELFARE of the public.", "ow": ["The sale of premium frames is a commercial metric, not the primary duty.", "Correct. The visual welfare of the public.", "The number of patients seen is a business metric, not the primary duty.", "Clinic profitability is a business metric, not the primary duty."]}'),
  ('dfacdae2-15','{"options": ["Different quality based on social status", "Preference for friends", "Equal diligence to patients", "Preference for wealthy patients"], "correct": 2, "decode": "Professional care should be provided with EQUAL DILIGENCE to patients.", "ow": ["Different quality by social status is unethical.", "Preference for friends is unethical.", "Correct. Equal diligence to patients.", "Preference for wealthy patients is unethical."]}'),
  ('83d4ccc6-27','{"options": ["Competitors only", "Optical suppliers only", "Patients served", "Advertisers"], "correct": 2, "decode": "An optometrist should respect the confidential nature of information concerning PATIENTS served.", "ow": ["Confidentiality is owed to patients, not competitors.", "Confidentiality is owed to patients, not suppliers.", "Correct. Patients served.", "Confidentiality is owed to patients, not advertisers."]}'),
  ('356f6f36-1u','{"options": ["Unnecessary after licensure", "Required only for students", "Optional", "A professional responsibility"], "correct": 3, "decode": "Continuous improvement of theoretical and practical proficiency is a PROFESSIONAL RESPONSIBILITY.", "ow": ["It is not unnecessary after licensure.", "It is not required only for students.", "It is not optional.", "Correct. A professional responsibility."]}'),
  ('173d826b-1l','{"options": ["Only other optometrists working in the same clinic", "Members of the profession and other professions", "Only patients who are fully able to pay", "Members and suppliers of the optical trade only"], "correct": 1, "decode": "An optometrist should maintain cordial relationships with members of the PROFESSION and OTHER professions.", "ow": ["It is not limited to same-clinic optometrists.", "Correct. Members of the profession and other professions.", "It is not limited to paying patients.", "It is not limited to the optical trade."]}'),
  ('a8803eef-1j','{"options": ["Maximum sales", "Selling the most expensive lenses", "Quality patient care", "Maximum advertising"], "correct": 2, "decode": "The primary objective of an optometric clinic should be QUALITY PATIENT CARE.", "ow": ["Maximum sales puts commerce first.", "Selling the most expensive lenses puts commerce first.", "Correct. Quality patient care.", "Maximum advertising puts commerce first."]}'),
  ('ab999046-1a','{"options": ["Only the total amount that the patient has paid", "Only the patient''s full name and home address", "Only the final spectacle prescription that was given", "Relevant clinical findings and management information"], "correct": 3, "decode": "A well-organized patient record should contain RELEVANT CLINICAL FINDINGS and management information.", "ow": ["The total amount paid alone is incomplete.", "Name and address alone are incomplete.", "The final prescription alone is incomplete.", "Correct. Relevant clinical findings and management information."]}'),
  ('0e3b9d08-19','{"options": ["Supports continuity and quality of patient care", "Replaces informed communication", "Guarantees profit", "Eliminates the need for examination"], "correct": 0, "decode": "Proper record keeping is important because it SUPPORTS CONTINUITY and QUALITY of care.", "ow": ["Correct. It supports continuity and quality.", "Records do not replace informed communication.", "Records do not guarantee profit.", "Records do not eliminate the need for examination."]}'),
  ('4758e967-1d','{"options": ["Receives relevant information and voluntarily agrees", "Signs a blank consent form without reading it", "Must first purchase glasses before being treated", "Is forced to accept the recommended treatment"], "correct": 0, "decode": "Informed consent primarily means the patient RECEIVES relevant information and VOLUNTARILY AGREES.", "ow": ["Correct. Receives information and voluntarily agrees.", "Signing a blank form without reading is not valid consent.", "It does not require purchasing glasses first.", "Being forced to accept treatment is not consent."]}'),
  ('cc70c255-1l','{"options": ["Ignoring expired supplies", "Poor instrument maintenance", "Proper sanitation and infection control", "Unorganized records"], "correct": 2, "decode": "An important component of good clinic management is PROPER SANITATION and INFECTION CONTROL.", "ow": ["Ignoring expired supplies is poor management.", "Poor instrument maintenance is poor management.", "Correct. Proper sanitation and infection control.", "Unorganized records are poor management."]}'),
  ('b47cf427-1b','{"options": ["Properly maintained and disinfected as appropriate", "Used regardless of their actual working condition", "Shared between patients without any cleaning", "Stored anywhere convenient around the clinic"], "correct": 0, "decode": "Instruments should be PROPERLY MAINTAINED and DISINFECTED as appropriate.", "ow": ["Correct. Properly maintained and disinfected.", "Using instruments regardless of condition is unsafe.", "Sharing uncleaned instruments risks infection.", "Careless storage is improper."]}'),
  ('55f27113-1h','{"options": ["Diagnosing glaucoma", "Managing patient flow efficiently", "Measuring visual acuity", "Increasing prescription power"], "correct": 1, "decode": "A clinic''s appointment system is primarily useful for MANAGING PATIENT FLOW efficiently.", "ow": ["It does not diagnose glaucoma.", "Correct. Managing patient flow efficiently.", "It does not measure visual acuity.", "It does not increase prescription power."]}'),
  ('d1741976-1d','{"options": ["Determine IOP", "Monitor supplies and prevent shortages", "Replace clinical examination", "Diagnose refractive errors"], "correct": 1, "decode": "An effective inventory system helps MONITOR supplies and PREVENT shortages.", "ow": ["It does not determine IOP.", "Correct. Monitor supplies and prevent shortages.", "It does not replace clinical examination.", "It does not diagnose refractive errors."]}'),
  ('c98a9138-1e','{"options": ["Misleading claims about guaranteed visual results", "Accurate disclosure of the professional fees", "Proper patient education about their own care", "Careful maintenance of accurate clinical records"], "correct": 0, "decode": "An example of unethical business practice is MISLEADING CLAIMS about guaranteed visual results.", "ow": ["Correct. Misleading claims about guaranteed results.", "Accurate disclosure of fees is ethical.", "Proper patient education is ethical.", "Careful maintenance of records is ethical."]}'),
  ('b4956d44-y','{"options": ["Truthful and consistent with professional standards", "Designed to guarantee a complete cure of disease", "False and exaggerated to attract more patients", "Based only on misleading promotional claims"], "correct": 0, "decode": "Professional advertising should be TRUTHFUL and consistent with professional standards.", "ow": ["Correct. Truthful and standard-consistent.", "It must not guarantee a complete cure of disease.", "It must not be false and exaggerated.", "It must not rely on misleading claims."]}'),
  ('f44d34cd-31','{"options": ["Operate private clinics", "Sell medications", "Manufacture optical lenses", "Adjudicate administrative cases"], "correct": 3, "decode": "The PRC Regulatory Boards investigate violations and ADJUDICATE administrative cases.", "ow": ["They do not operate private clinics.", "They do not sell medications.", "They do not manufacture lenses.", "Correct. Adjudicate administrative cases."]}'),
  ('1b1fb4a6-2k','{"options": ["Closure of every optical shop operating within the region", "Cancellation of all prescriptions previously issued nationwide", "Imprisonment of the optometrist without any court proceedings", "Suspension or revocation of registration for causes provided by law"], "correct": 3, "decode": "The Board may impose SUSPENSION or REVOCATION of registration for causes provided by law.", "ow": ["It cannot close every optical shop in the region.", "It cannot cancel all prescriptions nationwide.", "It cannot imprison without court proceedings.", "Correct. Suspension or revocation of registration."]}'),
  ('8d08b1f4-25','{"options": ["A patient''s workplace without authorization", "A shopping mall hallway", "Premises used appropriately for optometric practice", "Any public place"], "correct": 2, "decode": "Under the IRR, routine examination should be performed in PREMISES used appropriately for optometric practice.", "ow": ["A workplace without authorization is improper.", "A shopping mall hallway is improper.", "Correct. Appropriate optometric premises.", "Any public place is improper."]}'),
  ('3bcae5bd-2p','{"options": ["Examination and dispensing through unauthorized mobile units", "Reading printed books under normal room lighting", "Buying eyeglass frames from an ordinary retail store", "Wearing contact lenses purely for cosmetic purposes"], "correct": 0, "decode": "The PRC advisory on unauthorized practice targets EXAMINATION and DISPENSING through unauthorized MOBILE units.", "ow": ["Correct. Unauthorized mobile examination and dispensing.", "Reading printed books is not a regulated act.", "Buying frames at retail is not a regulated act.", "Wearing cosmetic contact lenses is not a regulated act."]}'),
  ('92299c99-2m','{"options": ["A frame manufacturer that supplies the clinic with its display stock and finished lens blanks", "The next-door neighbor of a patient who lives near the proposed community outreach venue", "Relevant national/local health authorities and/or the recognized professional organization, as applicable", "Any optical salesperson employed at a nearby commercial establishment or shopping mall outlet"], "correct": 2, "decode": "A mobile optometric service may require permission from RELEVANT national/local health authorities and/or the professional organization.", "ow": ["A frame manufacturer has no such authority.", "A patient''s neighbor has no such authority.", "Correct. Relevant health authorities and/or the professional organization.", "An optical salesperson has no such authority."]}'),
  ('2b383d7a-3x','{"options": ["Sell the patient a stronger pair of spectacles instead", "Conceal the finding to avoid alarming the patient", "Ignore the finding and continue routine care as normal", "Refer appropriately and explain the concern to the patient"], "correct": 3, "decode": "On finding a serious disease beyond routine scope, the best action is to REFER appropriately and EXPLAIN the concern.", "ow": ["Selling stronger spectacles instead endangers the patient.", "Concealing the finding is unethical.", "Ignoring the finding is unethical.", "Correct. Refer appropriately and explain the concern."]}'),
  ('b5502651-25','{"options": ["The patient should usually be refused service until able to pay", "The patient should generally receive inferior, lower-standard care", "The patient''s condition should simply be ignored by the clinic", "Humanitarian considerations may warrant professional service without charge"], "correct": 3, "decode": "When a patient cannot afford the fee, HUMANITARIAN considerations may warrant service WITHOUT charge.", "ow": ["Refusing service until able to pay is not the ethical emphasis.", "Providing inferior care is unethical.", "Ignoring the condition is unethical.", "Correct. Humanitarian service without charge may be warranted."]}'),
  ('c8290739-2k','{"options": ["Misleading professional conduct", "Appropriate advertising", "Ethical counseling", "Good practice management"], "correct": 0, "decode": "Telling every patient that a lens will ''cure all eye diseases'' is MISLEADING professional conduct.", "ow": ["Correct. Misleading professional conduct.", "It is not appropriate advertising.", "It is not ethical counseling.", "It is not good practice management."]}'),
  ('8af8fb0f-2l','{"options": ["Maintain confidentiality", "Give the information to the patient''s friends", "Post it online", "Disclose it"], "correct": 0, "decode": "When asked to disclose ANOTHER patient''s diagnosis, the optometrist should MAINTAIN CONFIDENTIALITY.", "ow": ["Correct. Maintain confidentiality.", "Giving it to the patient''s friends violates privacy.", "Posting it online violates privacy.", "Disclosing it violates privacy."]}'),
  ('3c027da8-3r','{"options": ["Hide the incentive from the patient entirely", "Prioritize patient welfare and professional judgment", "Increase the price that is charged to patients", "Accept it and recommend the product to everyone"], "correct": 1, "decode": "Offered a financial incentive to recommend a product regardless of need, PRIORITIZE PATIENT WELFARE and professional judgment.", "ow": ["Hiding the incentive is unethical.", "Correct. Prioritize patient welfare and professional judgment.", "Raising prices to patients is unethical.", "Accepting and pushing the product to everyone is unethical."]}'),
  ('3bd6d74e-3g','{"options": ["Take appropriate steps consistent with professional and regulatory procedures", "Spread the information about the colleague widely on social media platforms", "Publicly insult and humiliate the colleague in front of the staff", "Ignore the questionable conduct completely and say nothing to anyone"], "correct": 0, "decode": "Seeing a colleague repeatedly violating regulations, TAKE APPROPRIATE STEPS through professional and regulatory channels.", "ow": ["Correct. Use proper professional and regulatory procedures.", "Spreading it on social media is unprofessional.", "Publicly insulting the colleague is unprofessional.", "Ignoring the conduct enables harm."]}'),
  ('182f33e1-2u','{"options": ["Provide the prescription immediately", "Guess the prescription", "Ask the optical salesperson to determine it", "Explain that appropriate assessment is necessary"], "correct": 3, "decode": "When a patient requests a prescription without an appropriate exam, EXPLAIN that assessment is necessary first.", "ow": ["Providing it immediately without exam is substandard.", "Guessing the prescription is unsafe.", "Delegating to a salesperson is improper.", "Correct. Explain that appropriate assessment is necessary."]}'),
  ('e1448787-1m','{"options": ["Patient welfare, professional competence, honesty, and confidentiality", "Advertising and marketing placed before clinical patient care", "Profit and personal income placed before patient welfare always", "Competition with peers placed before professional cooperation"], "correct": 0, "decode": "Ethical optometric practice rests on PATIENT WELFARE, COMPETENCE, HONESTY, and CONFIDENTIALITY.", "ow": ["Correct. Patient welfare, competence, honesty, confidentiality.", "Advertising before care inverts the priorities.", "Profit before welfare inverts the priorities.", "Competition before cooperation inverts the priorities."]}'),
  ('72e5801d-1t','{"options": ["Blind acceptance of it without any question", "Purely commercial considerations and nothing else", "Immediate rejection without any proper review", "Scientific judgment and critical evaluation"], "correct": 3, "decode": "New developments should be approached with SCIENTIFIC JUDGMENT and critical evaluation.", "ow": ["Blind acceptance is unscientific.", "Purely commercial motives are unscientific.", "Immediate rejection without review is unscientific.", "Correct. Scientific judgment and critical evaluation."]}'),
  ('69d237bc-1z','{"options": ["Avoid making any referrals to other health professionals at all times", "Maximize clinic profit regardless of the patient''s real needs", "Focus almost exclusively on selling optical retail products", "Balance sound management with ethical, competent, patient-centered care"], "correct": 3, "decode": "The best overall principle is to BALANCE sound management with ethical, competent, patient-centered care.", "ow": ["Avoiding all referrals harms patients.", "Maximizing profit regardless of need harms patients.", "Focusing on retail sales harms patients.", "Correct. Balance management with patient-centered care."]}'),
  ('329ba13f-1g','{"options": ["Optometry laws and regulations", "Traffic laws only", "School regulations only", "Tax laws only"], "correct": 0, "decode": "The Board of Optometry may investigate violations of OPTOMETRY laws and regulations.", "ow": ["Correct. Optometry laws and regulations.", "Traffic laws fall to other agencies.", "School regulations fall to other bodies.", "Tax laws fall to the BIR."]}'),
  ('ab731934-21','{"options": ["Service to humanity and visual welfare", "Sales volume", "Financial gain", "Competition with other professionals"], "correct": 0, "decode": "The optometrist''s prime concern should be SERVICE to HUMANITY and visual welfare.", "ow": ["Correct. Service to humanity and visual welfare.", "Sales volume is secondary at best.", "Financial gain is secondary at best.", "Competition with peers is not the prime concern."]}'),
  ('b2bf18b9-1b','{"options": ["Secondary to professional service", "The primary consideration", "More important than patient welfare", "The only consideration"], "correct": 0, "decode": "Financial gain should be SECONDARY to professional service.", "ow": ["Correct. Secondary to professional service.", "It should not be the primary consideration.", "It must not outrank patient welfare.", "It is not the only consideration."]}'),
  ('c197aaeb-1j','{"options": ["Professional knowledge and proficiency", "Persuasive advertising and marketing skills", "Aggressive product sales techniques only", "Personal business profits above all else"], "correct": 0, "decode": "An optometrist should continuously maintain and improve PROFESSIONAL KNOWLEDGE and proficiency.", "ow": ["Correct. Professional knowledge and proficiency.", "Persuasive advertising skills are a business concern, not the core duty.", "Aggressive sales techniques are not the core duty.", "Personal profit above all is not the core duty."]}'),
  ('e07b589e-27','{"options": ["Posted publicly", "Kept confidential", "Published online", "Shared with competitors"], "correct": 1, "decode": "Patient information obtained during professional attendance should be KEPT CONFIDENTIAL.", "ow": ["Posting it publicly breaches confidentiality.", "Correct. Kept confidential.", "Publishing it online breaches confidentiality.", "Sharing it with competitors breaches confidentiality."]}'),
  ('621b683a-4o','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "Ophthalmoscopy (I, option D) views the internal eye (fundus), and dilating with mydriatics gives a wide view. Retinoscopy is refraction, slit-lamp is anterior segment, transillumination checks the iris/globe. Dilate then look inside = ophthalmoscopy."}'),
  ('0bb9b73d-3t','{"options": ["IV", "III", "I", "II"], "correct": 3, "explanation": "Retinoscopy (II, option D) is the objective refraction; dilating the pupil does not change the neutral point it measures. (A mydriatic alone, without cycloplegia, does not paralyze accommodation, but the retinoscopic reflex reading itself is the objective measure.) Objective refraction = retinoscopy."}'),
  ('a3d99ed3-4g','{"options": ["I", "III", "II", "IV"], "correct": 1, "explanation": "Slit-lamp biomicroscopy (III, option B) with fluorescein dye reveals corneal epithelial staining. Ophthalmoscopy, retinoscopy, and transillumination do not use corneal dye. Fluorescein staining is viewed at the slit lamp."}'),
  ('94c745a4-53','{"options": ["I", "IV", "II", "III"], "correct": 2, "explanation": "Retinoscopy (II, option C) is a purely objective refraction needing no drops. VERIFY: transillumination also needs no DPA, so the item is loose; retinoscopy is the classic no-drug procedure. Ophthalmoscopy may use mydriatics and the slit-lamp exam often uses dye/anesthetic."}'),
  ('baa4207c-4g','{"options": ["IV", "II", "III", "I"], "correct": 2, "explanation": "The slit-lamp biomicroscope (III, option C) magnifies the lids, lashes, conjunctiva, and anterior segment for external/adnexal examination. Ophthalmoscopy is for the fundus and retinoscopy for refraction. External adnexa = slit lamp."}'),
  ('11155e6c-3x','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "Multicoated (anti-reflection) lenses (I, option D) suppress internal/surface reflections, improving clarity and cosmetics. Blu-lens, UV420, and Transitions filter specific wavelengths, not reflections. AR (multicoat) = controls reflections."}'),
  ('de667a25-3t','{"options": ["II", "IV", "III", "I"], "correct": 2, "explanation": "A selective filter like UV420 (III, option C) blocks UV up to 420 nm while allowing visible wavelengths through, a wavelength-selective transmission. VERIFY: the blue-blocking Blu-lens is also a selective filter, so the intended mapping is debatable. Wavelength-selective pass = a UV/blue filter coating."}'),
  ('3891680d-4t','{"options": ["I", "IV", "II", "III"], "correct": 3, "explanation": "The highest-frequency (shortest-wavelength) band is ultraviolet; UV420 (III, option D) fully blocks it. VERIFY: the item''s ''longest frequency'' wording is contradictory, and a blue-blocker could be argued; a UV filter blocks the highest-frequency end. Highest frequency = UV end = UV420 blocks it."}'),
  ('cd969baa-3g','{"options": ["I", "III", "II", "IV"], "correct": 3, "explanation": "Transitions (photochromic) lenses (IV, option D) darken in UV/sunlight and clear indoors. The other tints are fixed. Clear-to-dark = photochromic Transitions."}'),
  ('4fc21cca-4e','{"options": ["II", "I", "IV", "III"], "correct": 3, "explanation": "A UV420 (UV-blocking) lens (III, option D) protects the dentist''s eyes from the ultraviolet curing light. Transitions/blu-lens/multicoat do not specifically block the intense UV. UV curing exposure = UV-blocking lens."}'),
  ('919cfe70-4g','{"options": ["I", "II", "III", "IV"], "correct": 0, "explanation": "A penlight (I, option A) is the basic tool for the pupillary light reflex (a key neurological pupil test). The transilluminator, ophthalmoscope, and Amsler test other things. Pupil reflex = penlight."}'),
  ('554bee84-55','{"options": ["IV", "III", "II", "I"], "correct": 3, "explanation": "A penlight (I, option D) provides the bright light for photostress recovery and also lights the external adnexa. VERIFY: a transilluminator or ophthalmoscope light can also serve for photostress, so the tool is debatable; the penlight doubles for adnexal exam. Bright handheld light for photostress + adnexa = penlight."}'),
  ('53552b1e-40','{"options": ["IV", "III", "I", "II"], "correct": 1, "explanation": "The ophthalmoscope (III, option B) examines the internal eye (fundus). Penlight and transilluminator are surface/anterior tools, and Amsler is a chart. Look inside = ophthalmoscope."}'),
  ('263e2add-46','{"options": ["II", "IV", "III", "II"], "correct": 1, "explanation": "The Amsler grid (IV, option B) tests central macular function, detecting scotomas and metamorphopsia. Penlight, transilluminator, and ophthalmoscope do not directly test macular function. Macular function = Amsler grid."}'),
  ('ecd41c12-4t','{"options": ["III", "I", "IV", "I"], "correct": 2, "explanation": "The Amsler grid (IV, option C) is a printed chart the patient views; it does not emit light to assess the retina, unlike the light-using penlight, transilluminator, and ophthalmoscope. So it is the EXCEPT. Amsler is a chart, not a light source."}'),
  ('12eb1ff9-4g','{"options": ["IV", "II", "III", "I"], "correct": 3, "explanation": "Muriatic acid (I, option D) is the corrosive CHEMICAL used in bathroom cleaning. Slipping and improper lifting are physical/ergonomic, and fungus is biological. Cleaning-agent exposure = chemical (muriatic acid)."}'),
  ('425fc4b9-46','{"options": ["IV", "I", "III", "II"], "correct": 3, "explanation": "Slipping (II, option D) on a spill is a PHYSICAL hazard (fall risk). Muriatic acid is chemical, improper lifting ergonomic, fungus biological. Slippery floor = physical hazard."}'),
  ('72042ef8-4e','{"options": ["IV", "I", "II", "III"], "correct": 3, "explanation": "Improper lifting (III, option D), bending at the back instead of the knees, is an ERGONOMIC hazard (back strain). It is not chemical, physical-fall, or biological. Bad lifting posture = ergonomic hazard."}'),
  ('f51da71f-3n','{"options": ["III", "I", "II", "IV"], "correct": 3, "explanation": "Fungus (IV, option D) (mold/spores in a mushroom facility) is a BIOLOGICAL hazard. Muriatic acid is chemical, slipping physical, improper lifting ergonomic. Living organism exposure = biological hazard."}'),
  ('3935f0ca-5e','{"options": ["I & II", "III & IV", "IV & I", "II & III"], "correct": 3, "explanation": "Slipping (II, physical) plus improper/overloaded lifting (III, ergonomic) gives II & III (option D). Muriatic acid (chemical) and fungus (biological) are not involved here. Slip + overload = physical + ergonomic."}'),
  ('7050d9cc-4c','{"options": ["IV", "I", "II", "III"], "correct": 1, "explanation": "Marfan''s syndrome (I, option B), a connective-tissue disorder, weakens the zonules (suspensory ligaments), causing ectopia lentis (lens subluxation, classically upward). ARMD, Grave''s, and diabetes do not dislocate the lens. Marfan = zonular weakness = lens subluxation."}'),
  ('6477913a-4b','{"options": ["I", "III", "IV", "II"], "correct": 3, "explanation": "Age-related macular degeneration (II, option D) damages the fovea/macula, producing central field loss. Marfan (lens), Grave''s (thyroid eye), and diabetes (retinopathy) affect the eye differently. Foveal disease = central scotoma = ARMD."}'),
  ('ff94ee4b-3s','{"options": ["I", "II", "IV", "III"], "correct": 3, "explanation": "Grave''s disease (III, option D), thyroid eye disease, classically causes exophthalmos (proptosis) from orbital tissue swelling. Marfan, ARMD, and diabetes do not push the eye forward. Bulging eyes = Grave''s."}'),
  ('5400550c-4b','{"options": ["I", "IV", "III", "II"], "correct": 1, "explanation": "Diabetes (IV, option B), through chronic hyperglycemia, accelerates cataract formation (and the acute ''sugar'' snowflake cataract). Marfan, ARMD, and Grave''s are not sugar-driven. High blood sugar = early cataract."}'),
  ('5628331f-4p','{"options": ["II", "III", "I", "IV"], "correct": 0, "explanation": "Age-related macular degeneration (II, option A) is, by definition, an aging-driven condition. Marfan is genetic, Grave''s autoimmune, and diabetes metabolic. Aging root cause = age-related macular degeneration."}'),
  ('afd01c22-40','{"options": ["IV", "III", "II", "I"], "correct": 3, "explanation": "The chief complaint (I, option D) is the patient''s own statement of why they came. Medical, family, and medication histories are additional gathered data. Patient''s own words = chief complaint."}'),
  ('d4b66a3c-58','{"options": ["I", "III", "II", "IV"], "correct": 3, "explanation": "Current drug use (aspirin) belongs under Medications (IV, option D). It is not the complaint, general medical history heading, or family history. Drugs the patient takes = medications history."}'),
  ('599923bc-4u','{"options": ["II", "I", "III", "IV"], "correct": 0, "explanation": "A patient''s own diagnosed condition (diabetes) is his personal Medical History (II, option A). Family history covers relatives, medications covers drugs, and the complaint is the presenting problem. Own systemic disease = medical history."}'),
  ('85945823-5p','{"options": ["IV", "II", "III", "I"], "correct": 2, "explanation": "Diseases in relatives are recorded under Family Medical History (III, option C). Parents'' conditions = family history."}'),
  ('590739ff-4r','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "The reason for the visit is the Chief Complaint (I, option D), the starting point of the history. Reason for visit = chief complaint."}'),
  ('beba3936-62','{"options": ["I", "III", "IV", "II"], "correct": 0, "explanation": "Tapping the forehead/glabella to elicit a blink tests the Glabellar reflex (I, option A). Vestibulo-ocular, tonic-neck reflexes are unrelated to forehead tapping. Tap glabella, get a blink = glabellar reflex."}'),
  ('05415733-5l','{"options": ["IV", "III", "II", "I"], "correct": 2, "explanation": "The vestibulo-ocular (II, option C) reflex is the tonic labyrinthine reflex, using vestibular (labyrinth) input to stabilize gaze via the oculomotor muscles. Vestibular-driven eye stabilization = vestibulo-ocular (tonic labyrinthine)."}'),
  ('2529f497-5f','{"options": ["III", "II", "I", "IV"], "correct": 0, "explanation": "The Symmetrical Tonic Neck reflex (III, option A) links neck flexion/extension to arm/eye focus shifts (near-far), important for crossing the visual midline. Symmetrical (both sides) neck-driven focus = STNR."}'),
  ('588e31ce-4r','{"options": ["III", "IV", "II", "I"], "correct": 1, "explanation": "The Asymmetrical Tonic Neck reflex (IV, option B) turns the head/eyes to one side (the ''fencer'' posture), tied to laterality, tracking, and balance. One-sided head-eye reflex = ATNR (laterality)."}'),
  ('eb7cec9c-7m','{"options": ["IV", "I", "III", "II"], "correct": 1, "explanation": "That V-in, VII-out blink arc is the Glabellar (blink/corneal) reflex (I, option B): trigeminal sensory in, facial motor out to orbicularis oculi. Trigeminal afferent + facial efferent blink = glabellar/blink reflex."}'),
  ('c43c43d3-3h','{"options": ["II", "III", "I", "IV"], "correct": 2, "explanation": "Dribbling (as in basketball) needs Eye-hand coordination (I, option C). Soccer-type control is eye-foot-body, vergence is eye teaming, and focusing is accommodation. Hands controlling a ball = eye-hand coordination."}'),
  ('811c5ce5-3f','{"options": ["III", "IV", "II", "I"], "correct": 2, "explanation": "Soccer relies on Eye-foot-body coordination (II, option C), guiding the feet and body from what the eyes see. Feet controlling the ball = eye-foot-body coordination."}'),
  ('05f4e87d-3i','{"options": ["III", "IV", "II", "I"], "correct": 0, "explanation": "Vergence facility is the eyes converging/diverging together, that is, Eye teaming (III, option A). Teaming the two eyes = vergence."}'),
  ('75ff50e5-3k','{"options": ["II", "I", "III", "IV"], "correct": 3, "explanation": "Accommodative facility is the eye''s focusing agility, that is, Eye focusing (IV, option D). Changing focus quickly = accommodation/focusing."}'),
  ('f408e6eb-3o','{"options": ["II", "I", "III", "IV"], "correct": 3, "explanation": "Plus/minus flipper lenses train Eye focusing (IV, option D) (accommodative facility). Flippers = accommodation/focusing training."}'),
  ('445659f5-44','{"options": ["II", "I", "IV", "III"], "correct": 1, "explanation": "The Saccadic Fixator (I, option B), a lighted button panel the patient presses to hits targets, trains eye-hand coordination. Saccadic fixator = eye-hand coordination."}'),
  ('c2782464-4h','{"options": ["I", "II", "III", "IV"], "correct": 1, "explanation": "The Directionality Sequencer (II, option B) trains left/right (laterality) and directional concepts. Directionality sequencer = laterality/directionality."}'),
  ('3ac6107a-5j','{"options": ["III", "IV", "II", "I"], "correct": 0, "explanation": "The Balance Board (III, option A) challenges balance and the vestibular-ocular system, improving spatial awareness. Balance board = vestibular/spatial training."}'),
  ('d7f1e372-3s','{"options": ["III", "IV", "II", "I"], "correct": 1, "explanation": "The Visflex (IV, option B) trains binocular teaming/vergence flexibility. VERIFY: device-to-skill mapping is brand-specific and may vary; among these, Visflex is the teaming/flexibility trainer while the saccadic fixator is eye-hand. Eye teaming trainer = Visflex."}'),
  ('c84bd38c-56','{"options": ["III", "I", "IV", "II"], "correct": 1, "explanation": "The Wayne Saccadic Fixator (I, option B) is the lighted 33-button panel used to assess and train visual-motor skills. 33-button light board = saccadic fixator."}'),
  ('d27b34cc-45','{"options": ["I", "II", "III", "IV"], "correct": 0, "explanation": "Phenylephrine (I, option A) is commonly used at 2.5% (a sympathomimetic mydriatic). Tropicamide/cyclopentolate are lower, benoxinate is 0.4%. 2.5% dilating drop = phenylephrine."}'),
  ('c3c1d23a-45','{"options": ["III", "IV", "II", "I"], "correct": 2, "explanation": "Tropicamide (II, option C) is used at 0.5% (and 1%). Phenylephrine is 2.5%, benoxinate 0.4%. 0.5% short-acting mydriatic = tropicamide."}'),
  ('33a3d8cd-43','{"options": ["IV", "I", "II", "III"], "correct": 3, "explanation": "Cyclopentolate (III, option D) is commonly 1.0% (a cycloplegic). 1% cycloplegic = cyclopentolate."}'),
  ('37b98aee-43','{"options": ["III", "I", "II", "IV"], "correct": 3, "explanation": "Benoxinate HCl (IV, option D) (oxybuprocaine), a topical anesthetic, is used at 0.4%. 0.4% anesthetic = benoxinate."}'),
  ('4877e360-3e','{"options": ["IV", "I", "III", "II"], "correct": 0, "explanation": "Benoxinate (IV, option A) is a topical ANESTHETIC, not a mydriatic, so it does not dilate the pupil. Phenylephrine, tropicamide, and cyclopentolate all dilate. The anesthetic (benoxinate) is the non-dilator."}'),
  ('89aa56fb-3m','{"options": ["IV", "II", "III", "I"], "correct": 3, "explanation": "The first step is to Check the surrounding (I, option D), ensuring the scene is safe before approaching. Safety of the scene first = check the surrounding."}'),
  ('968c37ca-3m','{"options": ["I", "III", "II", "IV"], "correct": 2, "explanation": "After securing the scene, Call for help (II, option C) to activate emergency services. Then call for help = second step."}'),
  ('c9a2c7ca-3j','{"options": ["III", "IV", "I", "II"], "correct": 0, "explanation": "Third is to Assess the victim (III, option A) (responsiveness, breathing, injuries). Assess the casualty = third step."}'),
  ('87756e73-3k','{"options": ["I", "II", "IV", "III"], "correct": 2, "explanation": "Fourth is to Start the First Aid (IV, option C) (deliver care). Begin care = fourth step."}'),
  ('2325470c-4z','{"options": ["IV", "I", "III", "II"], "correct": 1, "explanation": "Assessing the nearby place for danger is Checking the surrounding (I, option B), the scene-safety step. Scene survey = check the surrounding."}'),
  ('09b036bc-3u','{"options": ["IV", "I", "II", "III"], "correct": 1, "explanation": "Hypertensive retinopathy stems from the Cardiovascular system (I, option B) (high blood pressure damaging retinal vessels). Blood pressure = cardiovascular system."}'),
  ('ecd598f9-3o','{"options": ["II", "I", "III", "IV"], "correct": 0, "explanation": "Tuberculosis primarily affects the Respiratory system (II, option A) (the lungs). TB = respiratory (lungs)."}'),
  ('737929b5-3m','{"options": ["II", "III", "IV", "I"], "correct": 1, "explanation": "Diabetes is an Endocrine system (III, option B) disorder (insulin/glucose regulation). Diabetes = endocrine."}'),
  ('cc3ea088-3x','{"options": ["IV", "I", "III", "II"], "correct": 0, "explanation": "Marfan''s syndrome is a Connective Tissue (IV, option A) disorder (fibrillin defect). Marfan = connective tissue."}'),
  ('057850d2-3q','{"options": ["II", "IV", "III", "I"], "correct": 2, "explanation": "The thyroid is part of the Endocrine system (III, option C). Thyroid = endocrine gland."}'),
  ('4238bf24-3n','{"options": ["IV", "III", "II", "I"], "correct": 3, "explanation": "A dentist (I, option D) using ultraviolet curing lights needs UV420 (UV-blocking) protection. VERIFY: outdoor workers (field/seafarer) also get heavy UV, so the intended mapping is debatable; the dentist has a specific artificial-UV exposure. UV curing exposure = dentist needs UV420."}'),
  ('2d3bfe42-3u','{"options": ["III", "I", "II", "IV"], "correct": 2, "explanation": "A field worker (II, option C) who moves between bright outdoors and shade/indoors benefits from photochromic Transitions that darken and clear automatically. VERIFY: any indoor-outdoor worker fits, so this is soft; the field worker is the intended answer. Frequent light changes = Transitions."}'),
  ('692b5c10-4k','{"options": ["II", "IV", "III", "I"], "correct": 2, "explanation": "Seafarers (III, option C) face intense glare reflected off water; polarized (Polaroid) lenses cut that glare and protect the macula. Water glare = polarized lenses for seafarers."}'),
  ('555b41f9-3t','{"options": ["III", "II", "IV", "I"], "correct": 2, "explanation": "A weekend athlete (IV, option C) needs impact-resistant polycarbonate for sports safety. Impact protection = polycarbonate for athletes."}'),
  ('7c1dcc8e-3l','{"options": ["IV", "II", "I", "III"], "correct": 3, "explanation": "Seafarers (III, option D), surrounded by water and sun glare, need glare protection. VERIFY: outdoor field workers also face glare, so it overlaps the polarized item; seafarers are the intended glare-exposed group. Sea/sun glare = seafarers."}'),
  ('381aac81-52','{"options": ["II", "III", "I", "IV"], "correct": 2, "explanation": "Amblyopia presents as Blurred vision (I, option C) (reduced acuity not correctable by lenses alone), a functional problem central to optometric care. Amblyopia = reduced/blurred vision."}'),
  ('bd92a080-4p','{"options": ["IV", "I", "III", "II"], "correct": 3, "explanation": "Diplopia (II, option D) (double vision) signals a binocular alignment/teaming problem. Double vision = binocular problem."}'),
  ('88aa735d-46','{"options": ["IV", "II", "III", "I"], "correct": 2, "explanation": "Loss of visual field (III, option C) is the most serious/severe symptom, often signaling significant retinal or neurological disease. VERIFY: flashes (retinal detachment warning) are also serious, so ''severe'' is debatable; field loss is the graver deficit. Field loss = severe."}'),
  ('a974a395-4a','{"options": ["IV", "III", "II", "I"], "correct": 0, "explanation": "Flashes of light/photopsia (IV, option A) can be a phenomenon of vascular events (for example ophthalmic migraine). VERIFY: vascular occlusions more often cause sudden field/vision loss, so field loss is a defensible answer; ''phenomenon'' points to photopsia. Light-flash phenomenon = vascular/migraine."}'),
  ('b68fee01-4w','{"options": ["IV", "III", "I", "II"], "correct": 0, "explanation": "Retinal detachment classically presents with Flashes of light (IV, option A) and floaters (from vitreoretinal traction), progressing to a curtain over the field. Photopsia + floaters = retinal detachment warning."}'),
  ('b52e1c76-3q','{"options": ["II", "III", "IV", "I"], "correct": 3, "explanation": "The autorefractometer (I, option D) gives an objective, automated measurement of refractive error. Slit lamp, keratometer, and lensmeter do other jobs. Objective auto-refraction = autorefractometer."}'),
  ('04db58c4-43','{"options": ["IV", "II", "III", "I"], "correct": 1, "explanation": "The slit lamp (II, option B) magnifies and illuminates the external adnexa and anterior segment. External adnexa = slit lamp."}'),
  ('d55409c6-41','{"options": ["III", "IV", "II", "I"], "correct": 0, "explanation": "The keratometer (III, option A) measures corneal curvature (K readings / base curve). Corneal curvature = keratometer."}'),
  ('bfa02e8b-49','{"options": ["III", "II", "I", "IV"], "correct": 3, "explanation": "The lensmeter (IV, option D) reads the power of a lens, including a contact lens (with a special support). Lens power = lensmeter."}'),
  ('5d88d943-3z','{"options": ["I", "IV", "III", "II"], "correct": 2, "explanation": "The keratometer (III, option C) measures corneal curvature to select the base curve and judge fit. VERIFY: the slit lamp (with fluorescein) evaluates the on-eye fit pattern, so it is a defensible answer; keratometry drives the initial fit determination. Fit selection = keratometry (with slit-lamp confirmation)."}'),
  ('385e83ce-4p','{"options": ["II", "III", "IV", "I"], "correct": 3, "explanation": "Refractive amblyopia (I, option D) arises from uncorrected refractive error, so the prescription itself describes the cause. Refractive error cause = refractive amblyopia."}'),
  ('80e9af0b-4h','{"options": ["IV", "I", "III", "II"], "correct": 0, "explanation": "Organic amblyopia (IV, option A) results from actual ocular disease/pathology and is often irreversible, unlike the functional types. Pathology-based, irreversible = organic amblyopia."}'),
  ('cb89e190-3q','{"options": ["IV", "II", "I", "III"], "correct": 1, "explanation": "Deprivation amblyopia (II, option B) results from something (like a congenital cataract or ptosis) blocking visual stimulation during development. Blocked/deprived input = deprivation amblyopia."}'),
  ('cb904046-47','{"options": ["I", "IV", "III", "II"], "correct": 2, "explanation": "Strabismic amblyopia (III, option C) develops when misaligned eyes (strabismus) cause the brain to suppress one eye. Eye turn/misalignment = strabismic amblyopia."}'),
  ('492e7c82-3x','{"options": ["I", "IV", "II", "III"], "correct": 1, "explanation": "Functional amblyopia includes refractive, deprivation, and strabismic types. Organic amblyopia (IV, option B) is caused by disease, not a functional deficit, so it is the EXCEPT. Organic is disease-based, not functional."}'),
  ('f94210f4-3a','{"options": ["II", "I", "IV", "III"], "correct": 1, "explanation": "The Brain (I, option B) is the command center of the nervous system. Brain = command center."}'),
  ('53e4ee9a-35','{"options": ["IV", "III", "II", "I"], "correct": 0, "explanation": "The Thalamus (IV, option A) (its lateral geniculate nucleus) is the first major CNS relay/processing station after the retina. VERIFY: the midbrain (superior colliculus) is an alternative early visual site, so the intended answer may differ; the geniculostriate pathway relays first in the thalamus. First CNS relay = thalamus (LGN)."}'),
  ('645f8f45-3i','{"options": ["I", "III", "II", "IV"], "correct": 2, "explanation": "After the thalamus, the Visual Cortex (II, option C) (V1) does the next stage of processing. Second stage = visual cortex."}'),
  ('af93a4ce-3h','{"options": ["IV", "I", "III", "II"], "correct": 1, "explanation": "Higher processing continues in the Brain (I, option B) association areas beyond V1. VERIFY: ''Brain'' is a broad category overlapping the cortex, so the split is loose; after V1 the signal goes to higher cortical/brain areas. Third stage = higher brain/association areas."}'),
  ('77eeb5c5-2v','{"options": ["II", "I", "IV", "III"], "correct": 0, "explanation": "Brodmann areas 17 (V1), 18, and 19 are the Visual Cortex (II, option A) in the occipital lobe. Areas 17-19 = visual cortex."}'),
  ('19baf186-2n','{"options": ["IV", "I", "III", "II"], "correct": 1, "explanation": "Orthokeratology is a Special contact lens (I, option B), a specialty rigid lens that reshapes the cornea overnight. VERIFY: ortho-K is a rigid GP lens, so ''Rigid'' is arguable; as a specialty modality it is grouped under Special. Ortho-K = special (specialty) lens."}'),
  ('600665ee-3x','{"options": ["IV", "III", "I", "II"], "correct": 3, "explanation": "The earliest contact lenses were Rigid (II, option D) (glass/PMMA scleral and corneal), which were relatively uncomfortable/painful. Original hard lenses = rigid (painful)."}'),
  ('ef023041-3j','{"options": ["I", "II", "IV", "III"], "correct": 3, "explanation": "Soft contact lenses (III, option D) dominate the market for comfort and ease. Most common = soft lenses."}'),
  ('4b49f1f2-33','{"options": ["IV", "III", "I", "II"], "correct": 0, "explanation": "Aesthetic (IV, option A) (cosmetic/colored) lenses are worn to change or enhance appearance. Looks/cosmetic = aesthetic lens."}'),
  ('f20698a3-2y','{"options": ["III", "I", "IV", "II"], "correct": 0, "explanation": "Daily disposables are Soft contact lenses (III, option A) designed to be discarded each day. Daily disposable = soft lens."}'),
  ('0518fcc0-38','{"options": ["IV", "III", "I", "II"], "correct": 2, "explanation": "A Progressive (multifocal) contact lens (I, option C) provides distance and near correction for presbyopes. Presbyopia = progressive/multifocal lens."}'),
  ('b382be33-3e','{"options": ["IV", "II", "I", "III"], "correct": 1, "explanation": "Ortho-K (II, option B) lenses flatten/reshape the central cornea to reduce myopia. Reshape/flatten cornea = ortho-K."}'),
  ('9af0a419-35','{"options": ["I", "II", "IV", "III"], "correct": 3, "explanation": "Scleral contact lenses (III, option D) are large-diameter lenses that vault the cornea and rest on the sclera. Large diameter = scleral lens."}'),
  ('4f764081-37','{"options": ["IV", "III", "II", "I"], "correct": 0, "explanation": "Colored (cosmetic) contact lenses (IV, option A) are frequently misused, bought without prescription or shared, causing infections. Cosmetic/colored = often abused."}'),
  ('99da69fa-3h','{"options": ["IV", "II", "III", "I"], "correct": 1, "explanation": "Ortho-K (II, option B) is specifically designed to reshape the cornea. Corneal reshaping = ortho-K."}'),
  ('256190c2-38','{"options": ["II", "IV", "I", "III"], "correct": 2, "explanation": "Peripheral vision is Sensory (I, option C) input (detecting stimuli in the visual field). Visual input = sensory."}'),
  ('ba45a300-32','{"options": ["II", "IV", "III", "I"], "correct": 0, "explanation": "Eye teaming (coordinating the two eyes'' movements) is a Motor (II, option A) skill. Coordinated eye movement = motor."}'),
  ('f9eb73da-34','{"options": ["II", "IV", "III", "I"], "correct": 2, "explanation": "Visual closure (recognizing a whole from parts) is a Cognitive (III, option C) perceptual skill. Perceptual completion = cognitive."}'),
  ('b1308d18-2z','{"options": ["I", "IV", "II", "III"], "correct": 1, "explanation": "Balance depends on Proprioception (IV, option B) (body/position sense with vestibular input). Balance/position sense = proprioception."}'),
  ('dbfb6440-41','{"options": ["IV", "II", "III", "I"], "correct": 0, "explanation": "Depth perception is often attributed to sensory (retinal disparity), motor (vergence), and cognitive (cue interpretation) systems, leaving Proprioception (IV, option A) as the EXCEPT. VERIFY: proprioceptive eye-position sense does contribute to depth, so the grouping is debatable. Sensory + motor + cognitive drive stereopsis."}'),
  ('5eeb728e-4x','{"options": ["IV", "II", "I", "III"], "correct": 2, "explanation": "Piaget''s sensorimotor stage is birth to about 2 years, that is, Birth to Toddler (I, option C). Sensorimotor = birth to toddler."}'),
  ('1275173d-50','{"options": ["IV", "III", "II", "I"], "correct": 0, "explanation": "The preoperational stage (about 2 to 7 years) corresponds to Early childhood to school age (IV, option A). Preoperational = early childhood to school age."}'),
  ('8c1176d3-5a','{"options": ["IV", "II", "I", "III"], "correct": 3, "explanation": "The concrete operational stage (about 7 to 11 years) is School age to Adolescence (III, option D). Concrete operational = school age to adolescence."}'),
  ('e788dfa8-4v','{"options": ["I", "II", "IV", "III"], "correct": 1, "explanation": "The formal operational stage (about 11 years onward) is Adolescence to Adulthood (II, option B). Formal operational = adolescence to adulthood."}'),
  ('282429dc-55','{"options": ["II", "IV", "III", "I"], "correct": 1, "explanation": "Developmental (behavioral) optometry focuses most on the visual development and learning years, Early childhood to school age (IV, option B). VERIFY: developmental care extends into the school-age/adolescent years too, so the target band is debatable. Developmental focus = the childhood learning years."}'),
  ('d442eb87-6i','{"options": ["I", "IV", "II", "III"], "correct": 0, "explanation": "Discriminating wavelengths of light is Color vision (I, option A). Wavelength discrimination = color vision."}'),
  ('4feefe5a-65','{"options": ["I", "III", "IV", "II"], "correct": 3, "explanation": "Intraocular light scatter that veils the retina is Glare (II, option D) (disability/veiling glare). Scattered light veil = glare."}'),
  ('a1413c7c-4c','{"options": ["I", "II", "III", "IV"], "correct": 2, "explanation": "The Photostress test (III, option C) bleaches photopigment with a bright light and times its regeneration (recovery of acuity), probing macular function. Bleach-and-recover = photostress test."}'),
  ('16307635-3z','{"options": ["IV", "I", "III", "II"], "correct": 0, "explanation": "A Contrast (sensitivity) test (IV, option A) uses gratings of alternating light and dark (max/min luminance) bands. Light-dark gratings = contrast test."}'),
  ('185c8890-4z','{"options": ["III", "IV", "II", "I"], "correct": 3, "explanation": "Experiencing many wavelengths as different hues is Color vision (I, option D). Many hues = color vision."}'),
  ('6aa8716b-6u','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "Vergence facility (I, option D) measures how quickly the eyes converge/diverge (team) using prism flippers, in cycles per minute. Prism flipper cpm = vergence facility."}'),
  ('778add1f-72','{"options": ["III", "I", "IV", "II"], "correct": 3, "explanation": "The Parks three-step test is used in Paretic Muscle Evaluation (II, option D) to localize a paretic (usually cyclovertical) muscle. Parks 3-step = paretic muscle evaluation."}'),
  ('e33fb5be-5j','{"options": ["IV", "II", "III", "I"], "correct": 2, "explanation": "Accommodative Response (III, option C) (for example MEM or Nott retinoscopy) measures the actual accommodation the patient exerts at near. Actual accommodation = accommodative response."}'),
  ('dfd7c5da-5v','{"options": ["III", "IV", "II", "I"], "correct": 1, "explanation": "Accommodative Facility (IV, option B), tested with plus/minus flippers, measures how well the eye changes (alters) focus. Change focus speed = accommodative facility."}'),
  ('19c5317c-70','{"options": ["II", "IV", "I", "III"], "correct": 1, "explanation": "Accommodative Facility (IV, option B) reflects the quality/flexibility of accommodation supporting comfortable binocular vision. VERIFY: this overlaps the accommodative-response and facility items, so the intended distinction is loose. Quality/flexibility of focus = accommodative facility."}'),
  ('46ac9f14-43','{"options": ["III", "II", "I", "IV"], "correct": 2, "explanation": "A Concussion (I, option C) is a brain injury causing brief loss of consciousness. Temporary knockout = concussion."}'),
  ('ddfd3e24-45','{"options": ["III", "I", "IV", "II"], "correct": 3, "explanation": "A cerebrovascular accident is a Stroke (II, option D), which can cause hemiplegia (one-sided paralysis). CVA = stroke."}'),
  ('45ce7fb3-3r','{"options": ["IV", "II", "III", "I"], "correct": 2, "explanation": "Multiple sclerosis destroys the Myelin Sheath (III, option C) (demyelination) of nerves. MS = demyelination (myelin sheath)."}'),
  ('5417976c-4d','{"options": ["I", "II", "III", "IV"], "correct": 3, "explanation": "Cerebral palsy impairs Motor skills (IV, option D), affecting muscle movement and tone. CP = motor skill impairment."}'),
  ('53dfd2db-3s','{"options": ["IV", "III", "II", "I"], "correct": 3, "explanation": "Helmets protect the head from impact, preventing Concussion (I, option D). Head protection = prevents concussion."}'),
  ('74b74e3e-3c','{"options": ["III", "IV", "II", "I"], "correct": 3, "explanation": "Chemical-resistant Gloves (I, option D) protect the hands from corrosive muriatic acid. Handling acid = gloves."}'),
  ('11334c1f-3l','{"options": ["I", "II", "IV", "III"], "correct": 1, "explanation": "A welding Face shield (II, option B) protects the face/front of the head from sparks and radiation. Welding = face shield."}'),
  ('30bf92d3-3t','{"options": ["III", "II", "IV", "I"], "correct": 0, "explanation": "A Scrub suit (III, option A) is the protective/sterile attire in the operating room. OR attire = scrub suit."}'),
  ('f2ddd0ef-3g','{"options": ["II", "IV", "III", "I"], "correct": 1, "explanation": "Safety Shoes (IV, option B) (steel-toed) protect a construction worker''s feet. Foot protection = safety shoes."}'),
  ('55ace2aa-3z','{"options": ["IV", "II", "I", "III"], "correct": 2, "explanation": "Insulating Gloves (I, option C) prevent electrocution when handling the welding electrode/arc. Electrical insulation = gloves."}'),
  ('fbde2236-5r','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "A balance board builds Spatial awareness (I, option D) via vestibular activation. VERIFY: ''strengthen eye muscle'' or general coordination could be argued, but the balance/vestibular emphasis points to spatial awareness. Balance/vestibular = spatial awareness."}'),
  ('b54eacd7-58','{"options": ["IV", "II", "I", "III"], "correct": 1, "explanation": "Strobe training under visual noise builds the Slow-motion phenomenon (II, option B), the trained perception of fast action as slower/clearer. Strobe training = slow-motion perception."}'),
  ('76862a57-4z','{"options": ["I", "III", "II", "IV"], "correct": 1, "explanation": "Visflex training strengthens the eye muscles (III, option B) to improve ocular motility. Motility trainer = strengthen eye muscle."}'),
  ('dcefeb35-57','{"options": ["III", "II", "I", "IV"], "correct": 3, "explanation": "A tachistoscope flashes images briefly to speed recognition, enhancing mental processing (IV, option D). Rapid recognition = enhanced mental processing."}'),
  ('a2786285-4o','{"options": ["II", "III", "IV", "I"], "correct": 3, "explanation": "The vestibular system underlies Spatial awareness (I, option D) (balance and orientation). Vestibular = spatial awareness/balance."}'),
  ('392d5b9a-6l','{"options": ["II", "III", "IV", "I"], "correct": 3, "explanation": "Failing color/contrast discrimination despite 20/20 acuity is a Contrast Problem (I, option D). VERIFY: this is strictly a color-discrimination deficit, and ''contrast'' is the closest of the offered categories. Good acuity but poor color/contrast = contrast problem."}'),
  ('9a36d834-57','{"options": ["IV", "III", "II", "I"], "correct": 2, "explanation": "Reduced acuity of 20/70 is an Acuity Problem (II, option C). Low acuity = acuity problem."}'),
  ('b4e25b3c-5m','{"options": ["III", "I", "II", "IV"], "correct": 0, "explanation": "Seeing double (diplopia) is an Eye Teaming Problem (III, option A), a binocular misalignment. Double vision = eye teaming problem."}'),
  ('33c2df5f-4c','{"options": ["III", "II", "I", "IV"], "correct": 3, "explanation": "Tunnel vision (loss of peripheral field) is a Visual Field Problem (IV, option D). Constricted field = visual field problem."}'),
  ('3c2ce827-5c','{"options": ["II", "I", "IV", "III"], "correct": 1, "explanation": "Glare sensitivity with good acuity reflects a Contrast Problem (I, option B). Glare/contrast trouble = contrast problem."}'),
  ('c3ccd7d5-4l','{"options": ["I", "III", "II", "IV"], "correct": 0, "explanation": "The poorest acuity range (20/400 to 20/1600) belongs to the youngest, 1 month (I, option A), on Teller cards. Youngest infant = poorest acuity."}'),
  ('e1693a9b-4k','{"options": ["III", "IV", "II", "I"], "correct": 2, "explanation": "About 20/100 to 20/400 corresponds to 4 months (II, option C). Acuity improves steadily with age on Teller testing."}'),
  ('4373ba89-4j','{"options": ["II", "III", "IV", "I"], "correct": 2, "explanation": "About 20/80 to 20/300 corresponds to 12 months (IV, option C), better than the 4-month level but not yet the 18-month level."}'),
  ('ae562903-4j','{"options": ["II", "IV", "I", "III"], "correct": 3, "explanation": "The best of the listed ranges (20/50 to 20/150) corresponds to the oldest, 18 months (III, option D). Oldest infant = best acuity."}'),
  ('89cd2717-41','{"options": ["IV", "II", "I", "III"], "correct": 3, "explanation": "A 30-month-old should approach near-adult acuity, so even the 18-month range (20/50 to 20/150) (III, option D) would be subnormal and alarming for that age. VERIFY: the ''least alarming acuity'' wording is ambiguous; a 30-month-old performing only at an 18-month level signals delay. Below-age acuity = alarming."}'),
  ('02711856-5y','{"options": ["I", "II", "III", "IV"], "correct": 0, "explanation": "The Broken Wheel test (I, option A) pairs cards and asks the child to pick the wheel with the broken (incomplete) circle. Incomplete-circle matching = broken wheel."}'),
  ('113eff07-4i','{"options": ["II", "I", "IV", "III"], "correct": 0, "explanation": "The Allen chart (II, option A) uses recognizable picture optotypes with assigned acuity values. Picture optotypes = Allen chart."}'),
  ('7272968d-5y','{"options": ["IV", "III", "II", "I"], "correct": 1, "explanation": "The Tumbling E (III, option B) requires the child to indicate the direction the ''E'' points, which is hard for children who cannot yet handle directional concepts. Direction-pointing optotype = Tumbling E."}'),
  ('eca967c8-40','{"options": ["IV", "I", "II", "III"], "correct": 0, "explanation": "The STYCAR letter tests use a small set of letters matched by the child, corresponding to the HOTV (IV, option A) letter-matching approach. STYCAR letter matching = HOTV-type test."}'),
  ('e6bbe97d-4q','{"options": ["III", "IV", "II", "I"], "correct": 1, "explanation": "STYCAR (Screening Test for Young Children and Retardates) includes the letter-matching test represented by HOTV (IV, option B). STYCAR = the HOTV-style letter-matching screen."}'),
  ('7d96ba5f-5a','{"options": ["II", "IV", "III", "I"], "correct": 3, "explanation": "Slit-lamp examination is part of the Eye & Vision examination (I, option D) stage (assessment). Slit-lamp exam = examination stage."}'),
  ('4bf4ebfc-5v','{"options": ["I", "III", "II", "IV"], "correct": 2, "explanation": "Prescribing contact lenses to widen the field is the Correction (II, option C) stage. Prescribing lenses = correction stage."}'),
  ('30907c33-4u','{"options": ["IV", "I", "II", "III"], "correct": 3, "explanation": "Advising protective goggles is the Protection (III, option D) stage. Protective eyewear = protection stage."}'),
  ('8f64adfe-50','{"options": ["IV", "II", "I", "III"], "correct": 0, "explanation": "Improving visual-motor skills is Sports vision training (IV, option A). Skill training = sports vision training."}'),
  ('877b1287-50','{"options": ["II", "III", "I", "IV"], "correct": 2, "explanation": "Contrast sensitivity testing is part of the Eye & Vision examination (I, option C) stage (assessing visual function). VERIFY: contrast can also be addressed in training, so the stage is debatable; measuring it is an examination activity. Testing contrast = examination stage."}'),
  ('b9fc9101-1r','{"options": ["Visual Disorder.", "Visual Impairment.", "Visual Handicap.", "Visual Disability ."], "correct": 3, "explanation": "Difficulty NAVIGATING because of a field defect is a VISUAL DISABILITY — the functional ACTIVITY limitation resulting from the impairment. The field loss itself is the impairment (Q5); navigation is the disabled activity. WHO/ICF chain: impairment → disability (activity) → handicap (social role)."}'),
  ('c83914a1-1q','{"options": ["20 degrees of the visual field", "<20 Degrees from the fixation point", "10 degrees of the visual field", "<10 Degrees from the fixation point"], "correct": 0, "explanation": "The Amsler grid (held ~28-33 cm) assesses the central ~20° of field (≈10° radius around fixation) for metamorphopsia/scotoma in maculopathy. So ''20 degrees of the visual field'' is the standard extent. Cross-link: central distortion on Amsler is an early AMD/macular sign (Q18)."}'),
  ('5407c691-2q','{"options": ["Cataracts", "Glaucoma", "Monochromacy", "Stargardt"], "correct": 2, "explanation": "Monochromacy (a cone disorder) reduces acuity and color vision without producing a field defect, so it is the exception among conditions giving blur plus field loss. VERIFY: cataract also blurs without a true field defect, so confirm the key; monochromacy is the better ''no field defect'' answer."}'),
  ('2ae3aa5d-2v','{"options": ["Visual acuity", "Visual field", "Contrast sensitivity", "Color vision"], "correct": 2, "explanation": "Contrast sensitivity is often cited as the visual function most predictive of real-world daily activities (mobility, face recognition, reading in poor contrast). VERIFY: some keys answer visual acuity, so confirm; for daily living, contrast sensitivity is the better measure."}'),
  ('a334ad08-1m','{"options": ["Typoscope", "Felt-tip marker", "Yellow filter", "Walking cane"], "correct": 2, "explanation": "A yellow filter is an absorptive (optical) aid, so it is the one that is NOT a non-optical aid; the typoscope, felt-tip marker, and cane are non-optical."}'),
  ('d3d82cd5-3e','{"options": ["+14.50D", "+10.00D", "+5.50D", "+4.50D"], "correct": 1, "explanation": "Convert the working distance to dioptres first, then subtract what the lens already supplies. Accommodative demand at 5 cm = 1 / 0.05 = 20.00 D. The +10.00 D spectacle provides 10.00 D of that. Accommodation employed = 20.00 - 10.00 = +10.00 D. Answer: +10.00 D. The habit worth building: any near problem starts by turning centimetres into dioptres. 5 cm is 20 D, 10 cm is 10 D, 20 cm is 5 D, 40 cm is 2.50 D."}'),
  ('9b7ff3f6-1o','{"options": ["White cane", "Braille", "Absorptive lenses", "Magnification"], "correct": 2, "explanation": "Albinism causes marked photophobia, so absorptive (tinted) lenses are a key rehabilitation tool (with magnification for the reduced acuity)."}'),
  ('97621f5c-33','{"options": ["Humphrey Field Analyzer", "Goldmann Perimetry", "Amsler Grid", "Tangent Screen"], "correct": 2, "explanation": "The Amsler grid is the common bedside test of the central 10 degrees in low-vision/macular patients."}'),
  ('cd4edf8c-39','{"options": ["Monocular telescope", "Hand-held magnifier with illumination", "Electronic magnifier", "Bifocal glasses"], "correct": 1, "explanation": "For AMD reading, an illuminated hand-held magnifier is a practical choice (magnification plus added light for the macula). VERIFY: an electronic magnifier (CCTV) is also excellent for heavier reading needs, so confirm the key''s preference."}'),
  ('3e0d4085-2y','{"options": ["High contrast magnifiers", "Use of tinted lenses", "Laser surgery", "Increasing the brightness of ambient lighting"], "correct": 0, "explanation": "High-contrast magnifiers help improve effective contrast for low-vision patients. VERIFY: increasing ambient lighting also improves contrast, so confirm the key''s intended single best answer."}'),
  ('989fe60b-1x','{"options": ["The visual acuity with corrective lenses", "The visual acuity without any correction", "The visual acuity with the use of a magnifier", "The visual acuity with ambient lighting adjustments"], "correct": 0, "explanation": "''Achieved visual acuity'' generally refers to the best acuity reached with appropriate correction. VERIFY: in some low-vision frameworks it means acuity attained with the aid/magnifier, so confirm the source''s definition."}'),
  ('817dc9d3-4w','{"options": ["+6.25D", "+7.50D", "+10.00D", "+12.50D"], "correct": 0, "explanation": "Reciprocal-of-vision method: magnification needed = 20/100 to 20/40 = 100/40 = 2.5X, giving an add of about 2.5/0.4 = +6.25 D at 40 cm."}'),
  ('2c662b3f-56','{"options": ["15.00 D", "12.50 D", "10.00 D", "7.50 D"], "correct": 2, "explanation": "Step 1, how much larger does the print need to be? 9M / 1.5M = 6X. Step 2, convert that to dioptres at the 40 cm reference: 6 x 2.50 = 15.00 D of equivalent power. Step 3, the patient already supplies 5.00 D of usable accommodation, so the lens only has to cover the remainder: 15.00 - 5.00 = 10.00 D. Answer: 10.00 D. Step 3 is the one people skip. Accommodation the patient still has reduces the microscope power you need to prescribe, which is why the same acuity goal gives a different lens in a presbyope."}'),
  ('facd75af-7t','{"options": ["Convergence insufficiency", "Color vision deficiency", "Ocular alignment", "Visual field defect"], "correct": 0, "explanation": "Difficulty keeping near vision clear with normal stereopsis and no phorias points toward a vergence/accommodative inefficiency, with convergence insufficiency the listed best fit. VERIFY: this picture can also be accommodative infacility (not an option), so confirm the intended answer."}'),
  ('fb290215-7v','{"options": ["Increase the duration of occlusion therapy", "The child is not using their prescribed corrective lenses properly", "The child may have developed a new visual or neurological condition", "The amblyopia treatment needs to be intensified further"], "correct": 1, "explanation": "[Note: option text imperfect.] Compliant occlusion but no acuity gain in a 7-year-old amblyope → the most actionable next consideration is that the optical correction may be the limiting factor (not worn properly / residual error) — verify the refraction/wear before declaring treatment failure. Beyond the critical period, also reset expectations. Re-examine compliance with the GLASSES, not just the patch."}'),
  ('695a4997-6r','{"options": ["Initiate vision therapy to improve fusional control and eye coordination", "Increase the duration of occlusion therapy", "Recommend corrective lenses and monitor for spontaneous improvement", "Refer for immediate surgical intervention"], "correct": 0, "explanation": "Recent-onset large-angle exotropia with poor fusion and depth → INITIATE VISION THERAPY to build fusional control and coordination as first-line; reserve surgery for large/poorly controlled cases after assessing therapy response. Don''t jump to immediate surgery or rely on lenses/observation for a symptomatic large deviation."}'),
  ('ce8f32d7-30','{"options": ["Epithelial ingrowth", "Corneal ectasia", "Dry eye syndrome", "Endothelial cell loss"], "correct": 2, "explanation": "Post-refractive-surgery patients commonly develop DRY EYE (corneal nerve disruption reduces tear reflex), which contact lens wear can worsen. Epithelial ingrowth/ectasia/endothelial loss are surgical or other complications, but the CL-related risk highlighted is dry eye. Post-LASIK + CL = watch for dry eye."}'),
  ('6f642daf-2s','{"options": ["Corneal neovascularization", "Lens dehydration", "Improved oxygen permeability", "Reduced tear film stability"], "correct": 3, "explanation": "Prolonged HIGH-WATER-content soft lens wear can REDUCE TEAR-FILM STABILITY — high-water lenses dehydrate by drawing water from the tear film, destabilizing it and causing dryness. (They also have their own dehydration; the systemic effect on the eye is tear-film instability.) Counter-intuitive: high water → more surface drying."}'),
  ('69067b74-3l','{"options": ["Switch to monovision correction", "Increase the add power", "Refit with a different multifocal design", "Use reading glasses over the contact lenses"], "correct": 2, "explanation": "Presbyope unhappy with NEAR vision on multifocal CLs → REFIT with a DIFFERENT multifocal DESIGN (center-near vs center-distance, different add/zone geometry) before abandoning the approach. Switching to monovision sacrifices binocularity; just raising add or adding readers are lesser fixes. Optimize the multifocal design first."}'),
  ('ad0a4df8-37','{"options": ["Inadequate tear production", "Lens material", "Lens solution incompatibility", "Environmental factors"], "correct": 1, "explanation": "End-of-day dryness with silicone hydrogel lenses is often attributed to the lens material (surface/deposit interaction). VERIFY: inadequate tear production and environment also contribute, so confirm the intended single cause."}'),
  ('ee97719b-3n','{"options": ["8.0 mm", "8.4 mm", "8.7 mm", "9.0 mm"], "correct": 1, "explanation": "Convert the K reading to a radius before choosing anything: r (mm) = 337.5 / D = 337.5 / 46.50 = 7.26 mm. That is a steep cornea. Soft lenses are fitted FLATTER than flat K, typically by about 0.7 to 1.3 mm, so the target base curve is roughly 7.96 to 8.56 mm. Of the choices, 8.4 mm sits inside that band and is the standard steep base curve in most soft fitting sets. Answer: 8.4 mm. Keep the direction straight: a SMALLER radius in mm means a STEEPER lens. A steep cornea takes a steeper base curve, so 9.0 mm would be far too flat here."}'),
  ('e6313b75-2a','{"options": ["Full correction of myopia", "Partial correction of myopia", "Increased corneal curvature", "Development of corneal ectasia"], "correct": 1, "explanation": "VERIFY (truncated stem): the myopia value was cut in extraction; for low-to-moderate myopia orthokeratology gives at least partial (often full) correction overnight. Confirm the actual power in the source; partial correction is the safe placeholder."}'),
  ('7fa3ff97-2b','{"options": ["The lens is too flat", "The lens is too tight", "The lens is too small", "The lens is too large"], "correct": 0, "explanation": "EXCESSIVE rotation of a soft (toric) lens usually means the lens is too FLAT (loose) — it slides/rotates rather than seating stably, so the cylinder axis won''t hold. Too tight would limit movement; size is secondary. Excess rotation/movement → too flat. Cross-link: stabilize torics with ballast (physio Q105)."}'),
  ('14e27730-63','{"options": ["Right and Left Nasal Retina", "Right and Left Temporal Retina", "Right Nasal and Left Temporal Retina", "Right Temporal and Left Nasal Retina"], "correct": 3, "explanation": "Bumping objects on the LEFT = a LEFT field defect (left homonymous hemianopia). The LEFT visual field images onto the RIGHT TEMPORAL retina (of OD) and the LEFT NASAL retina (of OS) — those are the non-functioning areas. Retina-to-field rule: each field half maps to the opposite retinal half. Cross-link: localizes to the right retrochiasmal pathway (Q4)."}'),
  ('b04bb789-3q','{"options": ["Optic Nerve", "Uncrossed Optic Chiasm", "Optic Tract", "Crossed Optic Chiasm"], "correct": 2, "explanation": "Work out which field those two retinal halves serve. Temporal retina sees the NASAL field and nasal retina sees the TEMPORAL field, so the right temporal retina and the left nasal retina both handle the LEFT visual field. Losing both gives a left homonymous hemianopia, which localises to the RIGHT optic tract. Answer: Optic Tract. Why not the chiasm: crossing fibres at the chiasm carry the two nasal retinas, producing a BItemporal defect, not a homonymous one. Homonymous means the lesion sits behind the chiasm."}'),
  ('a65f00be-1m','{"options": ["Ipsilateral blindness with present direct light reflex", "Ipsilateral blindness with absent direct light reflex", "Contralateral blindness with present direct light reflex", "Contralateral blindness with absent direct light reflex"], "correct": 1, "explanation": "A COMPLETE left optic NERVE lesion = ipsilateral (left) blindness with an ABSENT direct light reflex (no afferent input from that eye), but the CONSENSUAL response in the other eye is preserved when the good eye is lit. Afferent (sensory) defect: light in the blind eye drives neither pupil; light in the good eye drives both. Cross-link: contrast efferent (motor) defects (Q17)."}'),
  ('b9a6c7ad-3z','{"options": ["1.2in", "3in", "7.7in", "10in"], "correct": 1, "explanation": "Hold the material at the lens''s focal point: focal length = 1 ÷ F = 1 ÷ 13 = 0.077 m = 7.7 cm. Convert to inches: 7.7 ÷ 2.54 ≈ 3.0 in. The trap is the ''7.7'' distractor, which is the correct number but in centimetres, not inches. Rule: focal length in metres = 1/F, then convert units before matching the option."}'),
  ('8e9bf3ab-34','{"options": ["Cataracts,,", "Glaucoma,,", "Cone Monochromacy ,,", "Stargardt’s Disease ,,"], "correct": 0, "explanation": "EXCEPT question. Conditions giving overall blur PLUS significant FIELD defects: glaucoma (arcuate/peripheral loss), cone monochromacy (central + poor acuity/photophobia), Stargardt (central scotoma). CATARACT causes diffuse blur/glare but NOT a true field defect (the whole field dims uniformly) — so cataract is the exception. Distinguish media blur from neural field loss."}'),
  ('62862fe4-24','{"options": ["Trochlear", "Abducens", "Oculomotor", "Optic"], "correct": 2, "explanation": "The OCULOMOTOR nerve (CN III) carries the parasympathetic motor fibers (via Edinger-Westphal → ciliary ganglion → short ciliary nerves) that drive pupil CONSTRICTION (sphincter pupillae). Optic (II) is the afferent limb; trochlear/abducens are pure motor to EOMs. Light reflex arc: CN II in, CN III out."}'),
  ('68789645-3t','{"options": ["Presence of Absolute Scotoma,", "Presence of Relative Scotoma,", "Presence of Negative Scotoma,", "Presence of Positive Scotoma,"], "correct": 1, "explanation": "Suprathreshold perimetry: MISSING the first (dimmer/standard) presentation but SEEING a second (brighter/repeated) one = REDUCED but present sensitivity = a RELATIVE scotoma (depressed, not dead). Missing BOTH = absolute (Q23). Logic: if a stronger stimulus is eventually seen, the area still has some function."}'),
  ('06e532d9-2y','{"options": ["OD – DLR +", "OD – CLR +", "OS – DLR +", "OS – CLR -"], "correct": 2, "explanation": "EXCEPT. A LEFT POST-GANGLIONIC (efferent, e.g., CN III/ciliary) lesion impairs the LEFT pupil''s ability to constrict: OS direct (OS-DLR) and OS consensual would be absent/abnormal. The question''s ''except'' is the option stating OS-DLR is PRESENT (+) — false, because the left efferent path is out. OD reflexes stay normal. Efferent left defect = OS can''t constrict to any light."}'),
  ('a5ade4a5-2w','{"options": ["OD – DLR +.", "OD – CLR -.", "OS – DLR +.", "OS – CLR +."], "correct": 2, "explanation": "EXCEPT. A complete LEFT optic NERVE (afferent) lesion: light in OS drives NEITHER pupil (OS-DLR absent, OD consensual to OS absent), but light in OD drives both. The false ''except'' option claims OS-DLR is PRESENT (+) — impossible with a dead afferent. Afferent defect: the blind eye can''t initiate either response, but its pupil still constricts consensually when the good eye is lit."}'),
  ('2d1f9de5-66','{"options": ["2.5X.", "5X.", "7.5X.", "12.5X."], "correct": 3, "explanation": "Two separate magnifications are in play and they MULTIPLY, they do not add. Device magnification: the screen turns a 20/40-sized target into a 20/200-sized image, so 200/40 = 5X. Relative distance magnification: moving from 50 cm to 20 cm gives 50/20 = 2.5X. Total = 5 x 2.5 = 12.5X. Answer: 12.5X. Read the distractor set and the design is obvious: 2.5X is the approach alone, 5X is the screen alone, 7.5X is 5 + 2.5 for anyone who adds instead of multiplying, and 12.5X is the product. The old key was 2.5X, which counts only the approach and discards the screen''s own enlargement, but the question asks for TOTAL magnification."}'),
  ('603b7883-4m','{"options": ["20/70", "20/30", "20/100", "20/160"], "correct": 3, "explanation": "Required print size scales with the distance change: going from 20 cm (where 20/70 is read) out to 45 cm, the demand grows by 45/20 = 2.25×, so 20/70 becomes ≈ 20/160 at 45 cm (the letter must be ~2.25× larger to stay readable). Convert acuity proportionally with working distance. Sets up the magnification need in Q35."}'),
  ('f4a13bbb-3u','{"options": ["2.5x", "2.2x", "2.3x", "2x"], "correct": 2, "explanation": "Magnification required = acuity you need / acuity you have = 160 / 70 = 2.29, so about 2.3X. Answer: 2.3x. The numerators are what matter here because both are written over 20. Compare the two M or Snellen values directly and the ratio is the magnification. Trap: rounding to 2.5X or dropping to 2X. 160/70 sits between them and the option set is deliberately tight, so carry the division out rather than eyeballing it."}'),
  ('6720d274-17','{"options": ["Galilean", "Keplerian", "Astronomical", "Newtonian"], "correct": 0, "explanation": "A GALILEAN telescope (convex objective + CONCAVE eyepiece) yields an ERECT image and is compact — standard for low-vision spectacle telescopes. Keplerian/astronomical (two convex lenses) gives an INVERTED image needing erecting prisms. Galilean = erect, short, lower magnification/field."}'),
  ('f1f9a53e-1y','{"options": ["Trichromacy.", "Dichromacy.", "Monochromacy.", "Anomalous Trichromacy."], "correct": 1, "explanation": "If only TWO of the three cone types function = DICHROMACY (a true dichromat: protanopia/deuteranopia/tritanopia). All three working = trichromacy; one or none = monochromacy; three present but one anomalous = anomalous trichromacy. Count functioning cone classes: 3=trichromat, 2=dichromat, 1/0=monochromat."}'),
  ('3e0df3f4-66','{"options": ["RSM", "RDM", "Optical magnification", "Angular magnification"], "correct": 1, "explanation": "Enlarging the retinal image with no bigger object and no lens = RELATIVE DISTANCE MAGNIFICATION (RDM): bring the material closer so it subtends a larger angle. RSM (relative size) enlarges the object itself; optical/angular magnification use lenses. By exclusion, approach (RDM) is the only non-optical, non-enlarging method."}'),
  ('649250f6-6k','{"options": ["2.3x", "10cm", "3.3x", "7cm"], "correct": 1, "explanation": "RDM enlarges the retinal image by shortening the working distance: new distance = habitual distance ÷ magnification = 40 cm ÷ 4 = 10 cm. The answer is a DISTANCE, not a magnification factor, because RDM is expressed as where to hold the material. The ''×'' options are distractors that confuse the method (a distance) with optical magnification (a power)."}'),
  ('a6f7c330-5o','{"options": ["+11.25D", "+7.00D", "+14.00D", "+10.00D"], "correct": 1, "explanation": "A near task at 10 cm needs +10.00 D total (1 ÷ 0.10 m). Accommodation supplies +3.00 D, so the spectacle add fills the deficit: 10.00 − 3.00 = +7.00 D. The lens only makes up what accommodation cannot. Working rule: add = total dioptric demand − usable accommodation."}'),
  ('8ed87a0d-5q','{"options": ["+8.00D", "+10.00D", "+12.00D", "+16.00D"], "correct": 3, "explanation": "A worn (spectacle) magnifier rates its magnification as M = F/4 on a 25 cm reference, so F = 4 × M = 4 × 4 = +16.00 D. Object sits at the lens''s focal point, image to infinity, eye relaxed. Distractors come from wrong references or conventions: 40 cm (F/2.5) gives +10 D, and the hand-convention F/4 + 1 gives +12 D."}'),
  ('771f6c1f-5e','{"options": ["4 cm", "6.25 cm", "8 cm", "10 cm"], "correct": 1, "explanation": "With the object at the focal point, the working distance equals the focal length: 100 ÷ 16 = 6.25 cm. Key correction: switching from a spectacle magnifier to a hand-held one does NOT change the power or the magnification for a given lens — the same +16.00 D gives the same 4×. What changes is field of view (smaller, because the eye moves away from the lens) and working comfort. 10 cm is the earlier relative-distance figure, not this magnifier''s focal length."}'),
  ('73600066-26','{"options": ["By providing a consistent visual target for both eyes", "By diagnosing binocular vision disorders", "By offering exercises that require coordinated use of both eyes", "By fitting corrective lenses for eye alignment", "By measuring color vision performance"], "correct": 2, "explanation": "The CAM Vision Stimulator improves binocular vision by providing EXERCISES that require COORDINATED USE OF BOTH EYES (rotating high-contrast gratings that drive cortical/binocular activity). It''s therapeutic, not diagnostic, and doesn''t fit lenses or test color. CAM = active binocular/coordination stimulation."}'),
  ('683cd610-2q','{"options": ["Depth perception and eye-hand coordination", "Near point accommodation", "Static color discrimination", "Peripheral vision enhancement", "Contrast sensitivity measurement"], "correct": 0, "explanation": "CAM Stimulator interactive exercises primarily target DEPTH PERCEPTION and EYE-HAND COORDINATION (visual-motor engagement with the rotating stimulus). Not accommodation, static color, peripheral, or contrast measurement. Match: CAM = binocularity + visual-motor."}'),
  ('0315eecc-22','{"options": ["1 month", "2 months", "3 months", "6 months", "12 months"], "correct": 2, "explanation": "Clear, consistent eye contact is generally established by about 3 months. VERIFY: developmental-milestone ranges vary by source, so confirm; 3 months is the common answer for steady eye contact."}'),
  ('3d0ce855-2z','{"options": ["2 months", "4 to 6 months", "6 to 9 months", "9 to 12 months", "12 to 18 months"], "correct": 1, "explanation": "Smooth visual tracking (pursuit) generally matures around 4 to 6 months. VERIFY: some sources cite earlier (2 to 3 months) for the onset of tracking, so confirm whether the key wants onset or smooth pursuit."}'),
  ('bae6d815-1y','{"options": ["By 4 to 6 months", "By 6 to 9 months", "By 9 to 12 months", "By 12 to 18 months", "By 18 to 24 months"], "correct": 0, "explanation": "Visually guided hand-eye coordination (reaching/grasping) typically begins around 4 to 6 months. VERIFY: ranges overlap between sources, so confirm the intended window."}'),
  ('8ffa4898-1w','{"options": ["Visual depth perception", "Visual acuity at 20/20", "Ability to recognize faces in a crowd", "Ability to read simple words", "Ability to detect subtle color differences"], "correct": 0, "explanation": "Depth perception is generally well developed by about 12 months. VERIFY: 20/20 acuity is NOT reached by 12 months (it comes years later), so depth perception is the better answer; confirm the key."}'),
  ('750b295c-1z','{"options": ["Improved depth perception", "Ability to perform rapid saccadic eye movements", "Advanced visual motor integration", "Detailed visual discrimination", "Complete color vision development"], "correct": 0, "explanation": "By about 18 months, improved depth perception is emerging along with other visual-motor skills. VERIFY: milestone lists vary, so confirm the intended skill for 18 months."}'),
  ('a66befdd-2d','{"options": ["Moro reflex’’", "Rooting reflex’’", "Stepping reflex’’", "Grasp reflex’’", "Tonic neck reflex’’"], "correct": 0, "explanation": "The MORO (startle) reflex = symmetric ARM/LEG EXTENSION then flexion in response to a sudden stimulus/head-drop. Rooting (cheek), stepping (upright feet), grasp (palm), tonic neck (head-turn) have different triggers. Sudden startle → Moro extension-then-embrace."}'),
  ('68330689-3i','{"options": ["1 month", "3 months", "12 months", "18 months", "2 years"], "correct": 2, "explanation": "The Babinski reflex (toes fanning when the sole is stroked) is normally present until about 12 months (as the child begins walking). VERIFY: some texts allow it up to 2 years, so confirm the cutoff the key uses."}'),
  ('e88eaf72-2x','{"options": ["Variable prism settings and adjustable visual targets", "Fixed aperture sizes and non- adjustable lenses", "Static color filters and unchangeable target distances", "Standardized contrast levels and pre- set visual acuity tests", "Immovable target positions and uniform lighting conditions"], "correct": 0, "explanation": "The Vodnoy trainer''s adjustability comes from VARIABLE PRISM settings and ADJUSTABLE visual targets — letting the clinician grade vergence/fusion demand to the patient. Fixed apertures/static filters/immovable targets would be the opposite. Feature = variable prism + targets."}'),
  ('1d27a31d-23','{"options": ["To enhance visual processing and coordination through interactive exercises", "To correct refractive errors with specialized lenses", "To measure visual acuity for diagnostic purposes", "To provide static visual acuity assessments", "To assess intraocular pressure for disease management"], "correct": 0, "explanation": "The CAM Vision Stimulator''s primary function is enhancing visual PROCESSING and COORDINATION through interactive exercises (rotating contrast stimuli engaging the visual cortex/binocularity). Not lens correction, acuity measurement, or IOP. CAM = active visual stimulation/processing. Reinforces Q46/Q47."}'),
  ('99771793-2s','{"options": ["Fixed target size and distance", "Non-variable target colors", "Adjustable task difficulty levels and interactive visual exercises", "Standardized lighting conditions", "Static aperture sizes"], "correct": 2, "explanation": "The CAM Stimulator grades task complexity via ADJUSTABLE difficulty levels and interactive visual exercises (e.g., changing stimulus speed/contrast/spatial frequency). Fixed sizes/colors/lighting would prevent grading. Feature = adjustable task difficulty."}'),
  ('888ac3e8-2z','{"options": ["3 to 4 years", "4 to 5 years", "5 to 6 years", "6 to 7 years", "7 to 8 years"], "correct": 0, "explanation": "Visual-motor integration shows significant improvement starting around 3 to 4 years. VERIFY: this range is approximate and source-dependent, so confirm."}'),
  ('ff25ee33-3o','{"options": ["8.0 mm", "8.4 mm", "8.7 mm", "9.0 mm"], "correct": 0, "explanation": "A STEEP cornea (flat-K 46.50 D is high power = steep) needs a STEEP (small-radius) base curve; 8.0 mm is the steepest option (smaller mm = steeper). 8.4-9.0 mm would be too flat and ride loose. Rule: steeper cornea → smaller BC radius. Cross-link: same steep-K logic in CL fitting."}'),
  ('e80f80d9-3k','{"options": ["Full correction of myopia", "Partial correction of myopia", "Increased corneal curvature", "Development of corneal ectasia"], "correct": 0, "explanation": "Low myopia (1.50 D) is within ortho-K''s effective range, so the expected overnight outcome is FULL correction of the myopia (the cornea reshapes enough to neutralize it). Higher myopia gives only partial correction. Ortho-K works best for low-to-moderate myopia → full correction here."}'),
  ('6eac2637-5a','{"options": ["7.89", "8.0", "7.76", "7.54"], "correct": 0, "explanation": "Ortho-K base curve = corneal radius flattened for the target: BC power = flat-K − myopia − Jessen factor = 45.50 − 2.00 − 0.75 = 42.75 D → radius = 337.5/42.75 ≈ 7.89 mm. The Jessen factor adds extra flattening for regression. Method: target power then convert to radius (r = 337.5/D for the keratometric index)."}'),
  ('c53f4f8a-17','{"options": ["Visual Disability", "Visual Impairment", "Visual Disorder", "Visual Handicap"], "correct": 2, "explanation": "Visual disorder, the direct result of an ocular abnormality (the disease/condition itself). The chain then runs disorder -> impairment (measurable function loss) -> disability (skill changes) -> handicap (social disadvantage). Hint: match Q10/11/12; the leftover top of the chain is the disorder."}'),
  ('717ca4d3-36','{"options": ["<20° of the visual field", "<20° from the point of fixation", "≤10° of the visual field", "≤10° from the point of fixation"], "correct": 3, "explanation": "Field constricted to about 10 degrees or less from the point of fixation is the WHO cutoff (severe field loss counts as blindness regardless of acuity). Hint: WHO counts a field of 10 degrees or less around fixation as blinding, even with good central acuity."}'),
  ('c5b55ee0-2q','{"options": ["Mild", "Moderate", "Severe", "Blindness"], "correct": 2, "explanation": "Severe visual impairment (WHO category 2), VA worse than 6/60 down to 3/60. Mild/moderate are better than 6/60; blindness is worse than 3/60. Hint: 6/60 to 3/60 band = severe; below 3/60 = blind."}'),
  ('8018d9a9-36','{"options": ["Relative Size Magnification", "Relative Distance Magnification", "Angular Magnification", "Projection Magnification"], "correct": 2, "explanation": "Angular magnification, an optical system (telescope/magnifier) enlarges the apparent angular size. Hint: ''optical system increases angular size'' = angular magnification."}'),
  ('b8ad4b57-35','{"options": ["Relative Size Magnification", "Relative Distance Magnification", "Angular Magnification", "Projection Magnification"], "correct": 1, "explanation": "Relative distance magnification, bringing the target closer enlarges the retinal image. Hint: closer target = relative DISTANCE magnification."}'),
  ('9c406167-2y','{"options": ["Relative Size Magnification", "Relative Distance Magnification", "Angular Magnification", "Projection Magnification"], "correct": 0, "explanation": "Relative size magnification, physically enlarging the object (large-print) makes it bigger. Hint: bigger object = relative SIZE magnification."}'),
  ('f3a91b30-1q','{"options": ["Diabetic Retinopathy", "Uncorrected refractive error", "Cataracts", "Presbyopia"], "correct": 2, "explanation": "Cataract is the leading cause of low vision (and blindness) in the geriatric population. Hint: age-related lens clouding tops elderly low vision."}'),
  ('95439303-2k','{"options": ["Cataracts", "Uncorrected refractive error", "Glaucoma", "Presbyopia"], "correct": 1, "explanation": "Uncorrected refractive error is the WHO''s leading cause of (distance) vision impairment; cataract leads blindness. Hint: the biggest fixable cause of impairment is simply uncorrected refractive error."}'),
  ('127f00b2-2q','{"options": ["Mild", "Moderate", "Severe", "Blindness"], "correct": 3, "explanation": "Blindness, BCVA worse than 20/400 (3/60) is WHO blindness. Hint: 20/400 is the blindness threshold; worse than that = blind."}'),
  ('26a96fac-2o','{"options": ["Visual Disorder", "Visual Impairment", "Visual Disability", "Visual Handicap"], "correct": 1, "explanation": "Visual impairment, the measurable loss of function from eye disease. Hint: ''measurable loss of function'' = impairment (the quantifiable step)."}'),
  ('73a04076-2f','{"options": ["Visual Disorder", "Visual Impairment", "Visual Disability", "Visual Handicap"], "correct": 3, "explanation": "Visual handicap, the social/societal disadvantage resulting from impairment and disability. Hint: ''disadvantage in society'' = handicap."}'),
  ('f6d36f93-2t','{"options": ["Visual Disorder", "Visual Impairment", "Visual Disability", "Visual Handicap"], "correct": 2, "explanation": "Visual disability, the change in a person''s skills/abilities from the impairment. Hint: ''changes in skills and abilities'' = disability."}'),
  ('19ed7a0c-1s','{"options": ["Protanopia", "Deuteranopia", "Protanomaly", "Deuteranomaly"], "correct": 1, "explanation": "Deuteranopia, the M (green) cones are non-functional. Hint: Deutan = D = the seconD cone = green (M)."}'),
  ('a1f45919-2j','{"options": ["Protanopia", "Deuteranopia", "Protanomaly", "Deuteranomaly"], "correct": 2, "explanation": "Protanomaly, the L (red) cones have reduced (not absent) sensitivity. ''-anomaly'' = weakened; ''-anopia'' = absent. Hint: Prot = red; -anomaly = weak, not gone."}'),
  ('eac61a2e-28','{"options": ["Anomalous Trichromacy", "Dichromacy", "Incomplete Monochromacy", "Complete Monochromacy"], "correct": 2, "explanation": "Incomplete monochromacy, two cone types are non-functional so only ONE cone type works. Complete monochromacy has NO working cones (rod-only). Hint: one cone left = incomplete monochromat; zero cones = complete."}'),
  ('cd085f2e-y','{"options": ["Protanopia", "Deuteranopia", "Tritanopia", "Deuteranomaly"], "correct": 1, "explanation": "Deuteranopia (green defect) is the most common dichromacy. Hint: red-green defects dominate, and deutan is the commonest."}'),
  ('e5eecba9-2v','{"options": ["Pseudoisochromatic plates", "Lanterns", "D-15 Color Arrangement Test", "Anomaloscope"], "correct": 3, "explanation": "The anomaloscope is the most accurate/definitive color-vision test (color-match, quantitative). Plates and D-15 are screeners. Hint: gold standard for color vision = anomaloscope."}'),
  ('35743010-2m','{"options": ["Rods", "L-cones", "M-cones", "S-cones"], "correct": 0, "explanation": "Rods remain functional in complete achromatopsia (no working cones), so vision is rod-driven (poor acuity, photophobia). Hint: no cones = you see with rods only."}'),
  ('52e95a21-1d','{"options": ["Autosomal dominant", "Autosomal recessive", "X-linked recessive", "Mitochondrial"], "correct": 1, "explanation": "Complete achromatopsia is autosomal recessive. Hint: complete rod monochromatism = autosomal recessive."}'),
  ('05e6233a-17','{"options": ["Complete achromatopsia", "Incomplete achromatopsia", "Cerebral achromatopsia", "Hereditary Monochromatism"], "correct": 1, "explanation": "Incomplete achromatopsia, the X-linked blue-cone monochromatism affects almost only males. If the key labels it ''hereditary monochromatism,'' that is the same X-linked entity, VERIFY. Hint: ''only men'' = X-linked = blue-cone (incomplete) monochromatism."}'),
  ('5e55dee8-3m','{"options": ["Area Striata", "Optic Radiation", "Lateral Geniculate Body", "Optic Tract"], "correct": 2, "explanation": "The lateral geniculate body (LGB/LGN) is the thalamic relay (''subcortical visual center'') between retina and cortex. Hint: LGB = the thalamic relay station on the way to the cortex."}'),
  ('1c32346b-1x','{"options": ["Superior Right Homonymous Quadrantanopsia", "Inferior Right Homonymous Quadrantanopsia", "Superior Left Homonymous Quadrantanopsia", "Inferior Left Homonymous Quadrantanopsia"], "correct": 0, "explanation": "Left Meyer''s loop (temporal radiations carry inferior fibers) gives a superior RIGHT homonymous quadrantanopsia (''pie in the sky''). Hint: temporal loop = superior contralateral quadrant defect; left lesion -> right superior ''pie in the sky.''"}'),
  ('35f255d3-2l','{"options": ["Optic Nerve", "Optic Chiasm", "Optic Tract", "Lateral Geniculate Body"], "correct": 1, "explanation": "Bitemporal heteronymous hemianopsia localizes to the optic chiasm (crossing nasal fibers). Hint: bitemporal = chiasm (the crossing point)."}'),
  ('6fc7c754-1m','{"options": ["Ipsilateral blindness with an absent direct light reflex", "Ipsilateral blindness with a present direct light reflex", "Contralateral blindness with an absent direct light reflex", "Contralateral blindness with a present direct light reflex"], "correct": 0, "explanation": "A complete left optic nerve lesion gives ipsilateral (left) blindness with an ABSENT direct light reflex (afferent limb cut), though the consensual reflex to the other eye persists. Hint: cut the afferent nerve -> that eye is blind and its direct reflex is gone."}'),
  ('9e263b62-2v','{"options": ["Positive Relative Scotoma", "Positive Absolute Scotoma", "Negative Relative Scotoma", "Negative Absolute Scotoma"], "correct": 3, "explanation": "The physiologic blind spot is a NEGATIVE (unnoticed) ABSOLUTE (no perception at all) scotoma. Hint: blind spot = absolute (total) and negative (you do not notice it)."}'),
  ('82a13271-38','{"options": ["Diabetic Retinopathy", "Hypertensive Retinopathy", "Retinopathy of Prematurity", "Retinitis Pigmentosa"], "correct": 1, "explanation": "Hypertensive retinopathy, retinal vessel damage from chronic high blood pressure. Hint: chronic BP damage to retinal vessels = hypertensive retinopathy."}'),
  ('a098b26b-1z','{"options": ["Mild NPDR", "Moderate NPDR", "Severe NPDR", "Proliferative DR"], "correct": 3, "explanation": "Proliferative diabetic retinopathy is defined by neovascularization (new vessels). NPDR stages have no new vessels. Hint: ''proliferative'' = new vessels growing."}'),
  ('df20949c-2d','{"options": ["Cotton-wool spots", "Hard exudates", "Microaneurysms", "Dot-blot hemorrhages"], "correct": 0, "explanation": "Cotton-wool spots, fluffy white nerve-fiber-layer infarcts from ischemia. Hard exudates are lipid; microaneurysms are vascular outpouchings. Hint: cotton-wool = a soft white NFL micro-infarct."}'),
  ('5ee01a1f-2u','{"options": ["Cotton-wool spots", "Microaneurysms", "Neovascularization", "Venous beading"], "correct": 1, "explanation": "Microaneurysms, tiny capillary outpouchings, the earliest visible sign of diabetic retinopathy. Hint: first DR sign = microaneurysm (a little red dot)."}'),
  ('d4bdb00b-1s','{"options": ["Flame-shaped", "Dot-and-blot", "Splinter", "Subhyaloid"], "correct": 1, "explanation": "Dot-and-blot hemorrhages are typical of diabetic retinopathy (deep intraretinal). Flame-shaped ones are more hypertensive (nerve-fiber layer). Hint: DIABETES = dot-blot (deep); hypertension = flame (superficial)."}'),
  ('1de0b1ab-2m','{"options": ["Retinitis Pigmentosa", "Retinopathy of Prematurity", "Diabetic Retinopathy", "Coats Disease"], "correct": 1, "explanation": "Retinopathy of prematurity, retinal neovascularization in premature (often oxygen-exposed) infants. Hint: premature baby + retinal new vessels = ROP."}'),
  ('14542a9f-22','{"options": ["Cone Dystrophy", "Rod Dystrophy", "Rod-Cone Dystrophy", "Cone-Rod Dystrophy"], "correct": 2, "explanation": "Retinitis pigmentosa is a rod-cone dystrophy (rods fail first, hence night blindness, then cones). Hint: RP = rods die first, so rod-cone dystrophy."}'),
  ('f897369d-1s','{"options": ["Melanin", "Rhodopsin", "Lipofuscin", "Xanthophyll"], "correct": 0, "explanation": "Melanin is deficient in albinism (affecting skin, hair, and ocular pigment, with foveal hypoplasia/nystagmus). Hint: albino = missing melanin."}'),
  ('bb781205-6c','{"options": ["2.5X", "4X", "5X", "8X"], "correct": 2, "explanation": "Magnification needed = starting acuity / goal = 200/40 = 5X (to take 20/200 to a 20/40 task). Hint: needed magnification = have-over-want in Snellen denominators, 200/40 = 5."}'),
  ('2f17c431-2x','{"options": ["+12.50D", "+16.00D", "+20.00D", "+25.00D"], "correct": 2, "explanation": "For 5X, spectacle add power = 4 x M = 4 x 5 = +20.00 D (using the M = F/4 reference). Hint: F = 4 x magnification (25 cm reference), so 5X needs +20 D."}'),
  ('0cf561b7-3k','{"options": ["5 cm", "10 cm", "20 cm", "25 cm"], "correct": 0, "explanation": "A +20.00 D lens focuses at its focal length, 1/20 m = 0.05 m = 5 cm, so hold the print at 5 cm. Hint: focal distance (cm) = 100 / power, 100/20 = 5 cm."}'),
  ('81222d41-4d','{"options": ["+8.00D", "+12.00D", "+20.00D", "+28.00D"], "correct": 1, "explanation": "To keep the 5 cm (+20 D) demand met when the patient can only accommodate +8 D, the add must supply the remaining +12.00 D (20 minus 8). Hint: needed add = total demand minus available accommodation, 20 - 8 = +12."}'),
  ('7c508b92-54','{"options": ["+2.50D", "+10.00D", "+12.50D", "+20.00D"], "correct": 3, "explanation": "Using the 25 cm reference (M = F/4), a 5X stand/dome magnifier likewise needs +20.00 D. Hint: same M = F/4 rule, 5 x 4 = +20 D."}'),
  ('098fa56f-5p','{"options": ["2X", "5X", "10X", "12.5X"], "correct": 2, "explanation": "Screen enlarges 20/40 to 20/200 = 5X, then halving the viewing distance (50 cm to 25 cm) doubles it, 5 x 2 = 10X total. Hint: multiply the on-screen magnification by the relative-distance factor (50/25 = 2)."}'),
  ('8f9b7070-48','{"options": ["20/20", "20/100", "20/250", "20/500"], "correct": 0, "explanation": "5X on a 20/100 target improves it to 20/(100/5) = 20/20. Hint: divide the Snellen denominator by the magnification, 100/5 = 20."}'),
  ('9ffba664-9d','{"options": ["Refraction under cycloplegia", "Discussion of cost and replacement schedule", "Evaluation of anterior chamber depth", "Measurement of corneal topography and corneal curvature"], "correct": 3, "explanation": "Corneal topography/curvature measurement is the key first step in ortho-k candidacy (the lens is designed to the corneal shape). Hint: ortho-k reshapes the cornea, so you must map the cornea first."}'),
  ('01b0ab58-7y','{"options": ["Scleral lenses", "RGP lenses with distance correction only", "Multifocal soft contact lenses", "Plano soft contact lenses"], "correct": 2, "explanation": "Multifocal soft contact lenses give this pseudophake near vision without sacrificing distance and without readers. Hint: monofocal IOL + wants glasses-free near = multifocal contact lens."}'),
  ('4e3154cf-5m','{"options": ["Switch the patient to a monthly lens with higher water content", "Refit with lenses that have higher oxygen transmissibility", "Prescribe topical antibiotics", "Advise the patient to reduce lens wear to 2 hours daily"], "correct": 1, "explanation": "Refit with higher oxygen transmissibility (Dk/t) lenses, neovascularization signals hypoxia. Hint: new vessels = the cornea is starved for oxygen, so raise the Dk/t."}'),
  ('50f42705-5h','{"options": ["Switch to scleral lenses and recommend preservative-free artificial tears", "Use hydrogen peroxide solution instead of a multipurpose solution", "Recommend daily disposable contact lenses", "Refit with rigid gas permeable lenses"], "correct": 2, "explanation": "Daily disposable lenses best relieve the deposit-driven dryness and foreign-body feeling of a dusty worker (a fresh, clean lens each day). Hint: end-of-day dryness with reusable lenses often resolves by moving to dailies."}'),
  ('493afd9d-41','{"options": ["Poor lens centration", "Incomplete blinking", "Corneal abrasion", "Over-correction of refractive error"], "correct": 0, "explanation": "Poor lens centration (decentered treatment zone) causes ortho-k night halos/glare (the pupil straddles the reshaped/untreated junction). Hint: good day vision but night halos in ortho-k = a decentered treatment zone."}'),
  ('36df84e1-5z','{"options": ["Easy insertion and removal", "Low cost and easy availability", "Vaulting of the irregular cornea with tear reservoir", "High water content providing oxygen to the cornea"], "correct": 2, "explanation": "Scleral lenses vault the irregular keratoconic cornea and hold a tear reservoir, giving a smooth new optical surface. Hint: scleral = vault + tear lake over the cone."}'),
  ('57798fcd-4j','{"options": ["Scleral lenses with plunger-assisted insertion", "Daily disposable soft contact lenses", "Monthly replacement toric lenses", "Rigid gas permeable lenses"], "correct": 1, "explanation": "Daily disposable soft lenses suit reduced dexterity/arthritis best, no cleaning, no storage, fresh each day (simplest, most hygienic). Hint: less handling and zero maintenance = daily disposables for arthritic patients."}'),
  ('8f8180f8-5y','{"options": ["160°", "180°", "170°", "190°"], "correct": 3, "explanation": "LARS = Left Add, Right Subtract. The mark rotated 10 degrees left, so ADD 10 to the intended 180 axis, order 190 (i.e., 10). Hint: rotation to the LEFT means ADD that amount to the axis."}'),
  ('26ba9923-41','{"options": ["Increase lens power by 0.50D", "Encourage consistent wear and reassess after a week", "Switch to rigid gas permeable lenses", "Discontinue ortho-k and prescribe spectacles"], "correct": 1, "explanation": "Encourage consistent nightly wear and reassess in a week, ortho-k effect regresses with skipped nights and returns with regular use. Hint: inconsistent ortho-k wear = regression; fix the compliance first."}'),
  ('fa91626e-6t','{"options": ["Switch to RGP lenses", "Refit with daily disposable lenses", "Use hydrogen peroxide disinfection", "Recommend wearing safety goggles over the lenses"], "correct": 1, "explanation": "Refit with daily disposables, end-of-day deposits/irritation on monthlies are solved by a fresh lens daily. Hint: recurrent deposit problems on reusables = switch to dailies."}'),
  ('cc0711fd-5m','{"options": ["Aspheric RGP lenses", "High-plus silicone hydrogel lenses", "Scleral lenses with front surface toricity", "Custom soft lenticular contact lenses"], "correct": 0, "explanation": "Aspheric RGP lenses give the crispest optics for high-plus aphakia (+9 D). A scleral is also reasonable if the surface is irregular, so VERIFY. Hint: for high powers and best acuity, rigid optics beat soft."}'),
  ('6b3401a1-5f','{"options": ["Decrease overall diameter", "Increase central sagittal depth and adjust peripheral curves", "Refit with hybrid lenses", "Prescribe lubricating eye drops"], "correct": 1, "explanation": "Increase central sagittal depth (and adjust peripheral curves), minimal apical clearance with peripheral blanching means too little vault and too-tight edges. Hint: raise the vault (sag) and loosen the landing to relieve blanching."}'),
  ('cbbfc59c-69','{"options": ["Discontinue contact lens wear permanently", "Switch to daily disposable lenses with high lubricity", "Prescribe antihistamine eye drops", "Refit with RGP lenses"], "correct": 1, "explanation": "Switch to daily disposables with high lubricity, low TBUT and staining point to dryness aggravated by an aging reusable lens. Hint: dryness + staining on reusables = try high-lubricity dailies first."}'),
  ('5b101e21-3l','{"options": ["Daily disposable lenses with tight-fitting swim goggles", "Monthly silicone hydrogel lenses", "Scleral lenses with preservative-free solution", "RGP lenses with UV filter"], "correct": 0, "explanation": "Daily disposable lenses under tight-fitting swim goggles, minimizes contamination/loss risk in water. Hint: swimming + lenses = dailies plus sealed goggles (never open water without protection)."}'),
  ('a89e4e6f-58','{"options": ["Switch to hydrogen peroxide system", "Prescribe rewetting drops", "Recommend lens polishing every 6 months", "Reduce wearing time to 6 hours"], "correct": 0, "explanation": "Switch to a hydrogen peroxide system, it cleans RGP deposits and fog better than a multipurpose solution. Hint: recurrent RGP deposits/fog = go to peroxide disinfection."}'),
  ('3e7f01cd-6z','{"options": ["Prescribe lubricating eye drops for use every 2 hours", "Flatten the peripheral curves of the scleral lens", "Recommend reduced wear time", "Increase the lens diameter"], "correct": 1, "explanation": "Flatten the peripheral (landing/haptic) curves, conjunctival vessel impingement/blanching at the landing zone means the edge is too tight. Hint: blanching at the scleral landing = edge too steep, so flatten it."}'),
  ('c06497f8-52','{"options": ["Monthly hydrogel lenses + multipurpose solution", "Daily silicone hydrogel lenses + preservative-free lubricating drops", "Quarterly RGP lenses + hydrogen peroxide solution", "Hybrid lenses + lipid-based artificial tears"], "correct": 1, "explanation": "Daily silicone hydrogel lenses plus preservative-free lubricating drops, high oxygen and a fresh clean lens for a dusty, dry workplace. Hint: harsh dry/dusty environment = high-Dk dailies + PF lubricants."}'),
  ('370d4285-43','{"options": ["They cannot correct astigmatism", "They do not conform well to the corneal shape", "They drape over the cornea and fail to neutralize irregular astigmatism", "They block oxygen transmission in advanced keratoconus"], "correct": 2, "explanation": "Soft lenses drape over the cornea and fail to neutralize the irregular astigmatism of keratoconus (only a rigid tear lens can). Hint: soft lenses conform to the cone, so they cannot mask its irregular astigmatism."}'),
  ('2f330b64-2l','{"options": ["Visual acuity test", "Schirmer’s test", "Keratometry", "Tonometry"], "correct": 1, "explanation": "Schirmer''s test assesses tear (aqueous) production before fitting (of the options, it is the only tear test). Ideally TBUT gauges quality, but here Schirmer is the tear measure. Hint: among these, only Schirmer touches the tears."}'),
  ('3a2fe15d-2u','{"options": ["Corneal hypoxia", "Giant papillary conjunctivitis", "Corneal abrasion", "Dry eye syndrome"], "correct": 2, "explanation": "Corneal abrasion (and 3-and-9 o''clock staining) is a common RGP complication from the rigid edge/foreign bodies. Hypoxia is less likely with high-Dk rigids. Hint: rigid lens on the cornea = mechanical abrasion risk."}'),
  ('2f1578bb-5z','{"options": ["Hypoxia-related swelling", "Mechanical trauma from lens edge", "Allergic conjunctivitis", "Solution toxicity"], "correct": 1, "explanation": "Superior epithelial arcuate lesions (SEALs) are mechanical trauma from a tight lens edge. Hint: an arcuate superior scrape = a mechanical (edge) SEAL, not infection."}'),
  ('90883b8b-3v','{"options": ["Small diameter corneal lens", "Large diameter corneal lens", "Scleral lens", "Hybrid lens"], "correct": 2, "explanation": "A scleral lens gives the best acuity and comfort in moderate keratoconus (vault + tear reservoir over the cone). Hint: moderate-to-advanced KC comfort champion = scleral."}'),
  ('90a539a9-5b','{"options": ["Prescribe topical corticosteroids", "Discontinue lens wear and start broad-spectrum antibiotics", "Refit with daily disposable lenses", "Increase frequency of lens cleaning"], "correct": 1, "explanation": "Discontinue lens wear and start broad-spectrum antibiotics, a contact-lens corneal ulcer is presumed microbial keratitis (steroids are contraindicated first-line). Hint: CL wearer + ulcer = stop lenses, cover with antibiotics, never steroids first."}'),
  ('bc0b215b-34','{"options": ["Multipurpose solution containing preservatives", "Hydrogen peroxide-based solution", "Saline solution only", "Enzymatic cleaner"], "correct": 1, "explanation": "A hydrogen peroxide-based (preservative-free) system suits sensitive/allergic eyes. Hint: preservative sensitivity = peroxide (no preservatives once neutralized)."}'),
  ('faafb160-3c','{"options": ["Corneal edema", "Regression of corneal reshaping effect", "Lens deposit buildup", "Infection"], "correct": 1, "explanation": "Regression of the corneal reshaping effect, the ortho-k mold fades without nightly wear. Hint: skip ortho-k nights and the cornea springs back = regression."}'),
  ('438b01a5-2r','{"options": ["Hydrogel", "Silicone hydrogel", "Polymethyl methacrylate (PMMA)", "Gas permeable fluorosilicone acrylate"], "correct": 1, "explanation": "Silicone hydrogel provides the highest oxygen permeability (Dk) among these (PMMA is essentially zero). Hint: silicone hydrogel = the high-Dk soft material."}'),
  ('013a7826-30','{"options": ["Continue lens wear and prescribe steroids", "Discontinue lens wear and switch to daily disposables", "Increase lens wearing time", "Change to a different multipurpose solution"], "correct": 1, "explanation": "Discontinue lens wear and switch to daily disposables, GPC is driven by lens-surface antigen/deposits, so remove the trigger. Hint: GPC = stop the offending lens, then move to a fresh-daily, deposit-free lens."}'),
  ('65ff8f30-56','{"options": ["Increase lens diameter", "Add preservative-free lubricant drops under the lens", "Use hydrogen peroxide solution for cleaning", "Reduce wearing time"], "correct": 1, "explanation": "Add preservative-free lubricant under the lens (fill the bowl), scleral midday fog with low tear meniscus reflects tear-film/debris issues. Hint: scleral fogging + dryness = better fill fluid / PF lubricant in the bowl."}'),
  ('0a80a8b6-3i','{"options": ["Monthly hydrogel lenses + multipurpose solution", "Daily disposable silicone hydrogel lenses", "RGP lenses + hydrogen peroxide solution", "Scleral lenses + preservative-containing solution"], "correct": 1, "explanation": "Daily disposable silicone hydrogel lenses, simplest and most hygienic for an elderly patient worried about handling/cleaning. Hint: handling/hygiene concerns = no-maintenance dailies."}'),
  ('1c888552-2y','{"options": ["Corneal neovascularization", "Infectious keratitis", "Giant papillary conjunctivitis", "Dry eye syndrome"], "correct": 1, "explanation": "Infectious (microbial) keratitis is the most serious/most notable complication of overnight ortho-k (Pseudomonas, Acanthamoeba). Hint: the feared ortho-k risk is infectious keratitis in overnight wearers."}'),
  ('3c7ec602-58','{"options": ["Worth 4 Dot", "King-Devick Test", "TNO Test", "Maddox Rod"], "correct": 1, "explanation": "King-Devick test, rapid number naming to screen saccadic/oculomotor dysfunction (losing place while reading). Hint: rapid number-naming for reading eye movements = King-Devick."}'),
  ('8c7a20eb-3f','{"options": ["DEM Test", "RAF Rule", "Krimsky Test", "Bagolini Test"], "correct": 0, "explanation": "DEM (Developmental Eye Movement) test assesses saccadic eye movements. Hint: DEM = the saccade/ocular-motor number-naming test."}'),
  ('ed3f0a83-31','{"options": ["Worth 4 Dot", "DEM Test", "Synoptophore", "Maddox Rod"], "correct": 1, "explanation": "DEM test gives an objective measure of visual-verbal (saccadic) oculomotor skill. Hint: ''visual-verbal oculomotor'' = DEM."}'),
  ('847aa50c-2y','{"options": ["RAF Rule", "Hirschberg Test", "Worth 4 Dot", "Krimsky Test"], "correct": 0, "explanation": "RAF rule (Royal Air Force rule) measures accommodative amplitude (and NPC). Hint: push-up amplitude of accommodation = RAF rule."}'),
  ('12b3f216-3b','{"options": ["Accommodative insufficiency", "Convergence excess", "Divergence excess", "Suppression"], "correct": 0, "explanation": "A significantly receded near point of accommodation indicates accommodative insufficiency. Hint: receded NPA / can''t sustain near = accommodative insufficiency."}'),
  ('ac2f7e09-22','{"options": ["Normal accommodation", "Accommodative dysfunction", "Lead of accommodation", "Convergence insufficiency"], "correct": 1, "explanation": "A +1.50 D MEM lag is high (normal is about +0.25 to +0.75 D), indicating accommodative dysfunction/insufficiency. Hint: MEM lag well above +0.75 = under-accommodating."}'),
  ('9aa4754b-33','{"options": ["Lag of accommodation", "Accommodative excess", "Lead of accommodation", "Presbyopia"], "correct": 2, "explanation": "A response greater than the stimulus is a LEAD of accommodation (over-accommodation). Hint: response > stimulus = lead (too much); response < stimulus = lag."}'),
  ('704765ab-25','{"options": ["+1.50 D lag", "+0.75 D lag", "Lead of accommodation", "Orthophoria"], "correct": 2, "explanation": "A LEAD of accommodation (a minus/against MEM finding) is associated with accommodative spasm. Hint: spasm = over-focusing = a lead."}'),
  ('1f7bed85-2m','{"options": ["Abnormal", "Excessive", "Within normal limits", "Indicative of spasm"], "correct": 2, "explanation": "A +0.50 D MEM lag is within normal limits (normal about +0.25 to +0.75 D). Hint: a small plus lag around a half diopter is normal."}'),
  ('6625c63d-2e','{"options": ["Worth 4 Dot", "Hirschberg", "Krimsky", "DEM"], "correct": 0, "explanation": "Worth 4 Dot evaluates suppression AND fusion at once (and diplopia). Hint: 4-dot lights = fusion vs suppression vs diplopia in one test."}'),
  ('b1df1de8-2u','{"options": ["Fusion", "Diplopia", "Suppression", "Stereopsis"], "correct": 2, "explanation": "Seeing only two lights on Worth 4 Dot indicates suppression (one eye''s image is ignored). Hint: 2 lights = suppression; 5 lights = diplopia; 4 = fusion."}'),
  ('bfe46108-2i','{"options": ["Worth 4 Dot", "Maddox Rod", "DEM", "RAF Rule"], "correct": 1, "explanation": "The Maddox rod turns a point light into a line to measure phorias/deviations. Hint: point-to-line conversion = Maddox rod."}'),
  ('e85b1cd0-1u','{"options": ["Double Maddox Rod", "Worth 4 Dot", "Krimsky", "TNO"], "correct": 0, "explanation": "A double Maddox rod is used to detect/measure cyclodeviation (torsion). Hint: torsion/cyclo = DOUBLE Maddox rod."}'),
  ('9c9423c3-1x','{"options": ["Bagolini Test", "Worth 4 Dot", "Double Maddox Rod", "Hirschberg Test"], "correct": 2, "explanation": "The double Maddox rod specifically measures torsional (cyclo) misalignment. Hint: same as Q83, torsion = double Maddox rod."}'),
  ('0dabe30d-45','{"options": ["Prism Cover Test", "Maddox Rod Test", "Worth 4 Dot Test", "DEM Test"], "correct": 0, "explanation": "The prism cover test objectively measures deviation using prisms during cover testing. Hint: neutralize the movement with prism during cover = prism cover test."}'),
  ('5e5b863e-27','{"options": ["Hirschberg Test", "Krimsky Test", "Prism Cover Test", "Brock String"], "correct": 2, "explanation": "The prism cover test is the gold standard for measuring ocular deviation. Hint: objective, prism-neutralized cover test = gold standard."}'),
  ('94122b79-2s','{"options": ["Hirschberg Test", "Synoptophore", "DEM Test", "TNO Test"], "correct": 0, "explanation": "The Hirschberg (corneal reflex) test estimates deviation rapidly without prisms. Hint: quick reflex-position estimate = Hirschberg."}'),
  ('08e9e495-22','{"options": ["5°", "15°", "30°", "45°"], "correct": 3, "explanation": "A corneal reflex at the LIMBUS corresponds to roughly 45 degrees of deviation (about 1 mm = 7 degrees, ~15 prism D per mm). Hint: reflex at the limbus = ~45 degrees (a large deviation)."}'),
  ('183002b3-2r','{"options": ["5°", "15°", "30°", "45°"], "correct": 1, "explanation": "A reflex at the PUPILLARY MARGIN is about 15 degrees. Hint: pupil margin ~15 degrees; limbus ~45 degrees."}'),
  ('1d56688c-2e','{"options": ["Esotropia", "Exotropia", "Normal positive angle kappa", "Hypertropia"], "correct": 2, "explanation": "A reflex displaced about 5 degrees nasally is a NORMAL positive angle kappa (the fovea sits slightly temporal, so the reflex is nasal). Hint: a small nasal reflex is normal positive angle kappa, not a true tropia."}'),
  ('315fe15a-2j','{"options": ["Synoptophore", "RAF Rule", "Retinoscope", "Keratometer"], "correct": 0, "explanation": "The synoptophore both diagnoses and treats binocular-vision disorders (measures deviation, fusion, and trains them). Hint: synoptophore = diagnose AND train binocular vision."}'),
  ('76e2cc75-34','{"options": ["Brock String", "Synoptophore", "Worth 4 Dot", "DEM"], "correct": 1, "explanation": "The synoptophore measures sensory and motor fusion (and fusional amplitudes). Hint: fusion ranges and grades = synoptophore."}'),
  ('eaa0a587-1x','{"options": ["Titmus Stereofly Test", "Hirschberg Test", "Maddox Rod Test", "Cover Test"], "correct": 0, "explanation": "The Titmus (Stereofly) test gives a quantitative stereoacuity in seconds of arc. Hint: graded stereo test = Titmus."}'),
  ('6fbd92fc-2y','{"options": ["Lang 2 Pencil Test", "Titmus Stereofly Test", "Brock String", "Worth 4 Dot"], "correct": 1, "explanation": "The Titmus Stereofly test quantifies stereopsis in seconds of arc. Hint: need arc-seconds = Titmus."}'),
  ('265b7fd5-1z','{"options": ["Titmus Stereofly", "Random Dot Stereogram", "Lang Pencil Test", "Synoptophore"], "correct": 1, "explanation": "A random-dot stereogram minimizes monocular cues (only stereopsis reveals the target). Hint: random dots hide the shape from one eye, so only true stereo sees it."}'),
  ('4d1cbb80-2c','{"options": ["Reduced binocular vision", "Improved binocular integration", "Increased suppression", "Accommodative insufficiency"], "correct": 1, "explanation": "Reaching 60 seconds of arc reflects improved binocular integration (good stereopsis). Hint: lower arc-seconds = finer, improved stereo."}'),
  ('6a49268a-2x','{"options": ["Anti-suppression therapy", "Tonometry", "Cycloplegia", "Keratometry"], "correct": 0, "explanation": "Anti-suppression therapy directly targets a suppressing eye. Hint: suppression -> anti-suppression therapy."}'),
  ('af6f1942-2n','{"options": ["Worth 4 Dot", "Brock String", "Bagolini Test", "TNO Test"], "correct": 1, "explanation": "The Brock string is the classic convergence (and physiological-diplopia awareness) activity. Hint: bead-on-a-string = convergence training = Brock string."}'),
  ('085c2e66-2b','{"options": ["Persistent suppression", "Improved binocular awareness", "Reduced accommodation", "Monocular fixation"], "correct": 1, "explanation": "Recognizing physiological diplopia during Brock string work shows improved binocular awareness (both eyes now engaged). Hint: seeing the two crossed strings = you are using both eyes = better binocular awareness."}'),
  ('438352e9-2f','{"options": ["TVPS-based activities", "Maddox Rod", "RAF Rule", "Worth 4 Dot"], "correct": 0, "explanation": "TVPS-based activities (Test of Visual Perceptual Skills) train visual spatial and sequential memory. Hint: visual perceptual/memory work = TVPS activities."}'),
  ('af31571d-1q','{"options": ["Suppression and amblyopia", "Presbyopia", "Cataract", "Color deficiency"], "correct": 0, "explanation": "Absent stereopsis here relates to suppression and amblyopia (no binocular input to build depth). Hint: no stereo usually traces to suppression/amblyopia."}'),
  ('40a68b73-1p','{"options": ["Suppression of the left eye", "Orthophoria", "Normal stereopsis", "Normal NPC"], "correct": 0, "explanation": "Suppression of the left eye is the sensory ADAPTATION (the brain ignoring one image to avoid diplopia). Hint: suppression = the sensory adaptation to misalignment."}'),
  ('44e97944-1x','{"options": ["Complete blindness", "Improved visual acuity and stereopsis", "Increased exotropia", "Reduced accommodation"], "correct": 1, "explanation": "Improved visual acuity and stereopsis was the primary outcome of therapy. Hint: successful BV therapy = better acuity + restored stereo."}'),
  ('8a51c613-1u','{"options": ["Deterioration of binocular vision", "Enhanced depth perception", "Reduced accommodation", "Increased suppression"], "correct": 1, "explanation": "Going from 3600 to 60 arc-seconds means enhanced depth perception. Hint: big drop in arc-seconds = much better depth perception."}'),
  ('0cc027cb-5m','{"options": ["Convergence insufficiency", "Constant esotropia", "Exotropia", "Divergence excess"], "correct": 1, "explanation": "Constant esotropia, a constant inward turn present at distance and near since early childhood. Hint: always-in, distance and near = constant esotropia."}'),
  ('8a0eea73-4w','{"options": ["Partially accommodative in nature", "Secondary to sixth nerve palsy", "Purely sensory", "Mechanical in origin"], "correct": 0, "explanation": "Partially accommodative esotropia, the angle shrinks (but does not vanish) with the full hyperopic/cycloplegic correction. Hint: correction reduces but does not eliminate the turn = partially accommodative."}'),
  ('8753d19c-4v','{"options": ["Cosmetic appearance and psychosocial well-being", "Color vision enhancement", "Corneal topography improvement", "Intraocular pressure reduction"], "correct": 0, "explanation": "Cosmetic appearance and psychosocial well-being should be prioritized when a child is being teased. Hint: bullying about an eye turn = address the psychosocial/cosmetic goal."}'),
  ('d1e39c9f-4s','{"options": ["Sensory binocular function", "Refractive status", "Ocular health", "Color discrimination"], "correct": 0, "explanation": "Stable fusion and physiological-diplopia awareness indicate improved sensory binocular function. Hint: fusion + diplopia awareness = sensory (binocular) gain."}'),
  ('77c2f33b-3q','{"options": ["Develop sensory and motor fusion skills", "Measure corneal curvature", "Assess visual acuity", "Evaluate accommodative lag"], "correct": 0, "explanation": "The synoptophore''s therapeutic purpose is developing sensory and motor fusion skills. Hint: synoptophore therapy = build fusion."}'),
  ('9f9c573b-47','{"options": ["Aperture Rule Trainer activities", "Color vision training", "Amsler Grid testing", "Occlusion therapy alone"], "correct": 0, "explanation": "Aperture Rule Trainer activities build vergence FACILITY (speed of change) when ranges are normal. Hint: normal range but slow to change = train vergence facility (Aperture Rule)."}'),
  ('f083decc-4k','{"options": ["Accommodative flipper therapy", "Worth 4 Dot testing", "Hirschberg testing", "Bruckner testing"], "correct": 0, "explanation": "Accommodative flipper therapy trains rapid focus change near-to-far. Hint: slow near-far focus shifts = accommodative flippers."}'),
  ('e901d4c8-3e','{"options": ["Improve visual comfort and binocular coordination", "Reduce corneal astigmatism", "Eliminate hyperopia", "Increase pupil size"], "correct": 0, "explanation": "Yoke prisms aim to improve visual comfort and binocular coordination (shifting both eyes together). Hint: yoke prisms move both eyes the same way to aid coordination/posture."}'),
  ('f27d12b0-5u','{"options": ["Restoration of functional binocular vision for daily activities", "Complete elimination of refractive error", "Improvement of color vision only", "Permanent dependence on vision therapy devices"], "correct": 0, "explanation": "Restoration of functional binocular vision for daily activities is the marker of successful rehabilitation. Hint: success = usable everyday binocular vision, not device dependence."}'),
  ('91083dae-1f','{"options": ["Restore binocular sensory processing", "Reduce corneal curvature", "Eliminate refractive error", "Increase pupil size"], "correct": 0, "explanation": "The ultimate goal of anti-suppression therapy is to restore binocular sensory processing. Hint: anti-suppression aims to get both eyes'' signals used together again."}'),
  ('e2e64290-2a','{"options": ["Simultaneous perception", "True fusion", "Stereoscopic effect", "Suppression"], "correct": 2, "explanation": "The stereoscopic effect (stereopsis) is the highest grade of binocular vision (Grade III). Hint: BV grades I (perception) -> II (fusion) -> III (stereopsis, the peak)."}'),
  ('154ca0e9-1k','{"options": ["Grade I binocular vision", "Grade II binocular vision", "Grade III binocular vision", "Monocular vision"], "correct": 2, "explanation": "Depth perception = Grade III binocular vision (stereopsis). Hint: depth perception = the top grade, Grade III."}'),
  ('71523ed0-2k','{"options": ["Sensory", "Motor", "Perceptual", "Optical"], "correct": 2, "explanation": "The perceptual process interprets and assigns meaning to visual stimuli. Hint: making sense/meaning of what is seen = perceptual."}'),
  ('4b1ab167-1h','{"options": ["Perceptual system", "Motor system", "Sensory system", "Retinal system"], "correct": 1, "explanation": "Fixations, versions, and vergences are MOTOR-system components (eye movements). Hint: eye movements = the motor system."}'),
  ('089ce537-2p','{"options": ["Sensory component", "Motor component", "Perceptual component", "Cognitive component"], "correct": 1, "explanation": "Intact sensory input but poor alignment = a MOTOR-component dysfunction. Hint: signal is fine but the eyes will not aim = motor problem."}'),
  ('9bad21c9-2a','{"options": ["Improve ocular health only", "Eliminate all refractive error", "Enhance visual function and quality of life", "Increase accommodative demand"], "correct": 2, "explanation": "The overall objective of binocular-vision management is to enhance visual function and quality of life. Hint: the goal is better function/life, not perfect refraction or pressure."}'),
  ('b73a0d79-4i','{"options": ["Hypoxia due to low oxygen permeability of lenses", "Allergic conjunctivitis", "Incorrect spectacle prescription", "Dry eye syndrome"], "correct": 0, "explanation": "Hypoxia from low-Dk lenses causes corneal edema, giving blur and night halos. Hint: soft-lens edema + halos = the cornea is oxygen-starved."}'),
  ('7e6c9508-26','{"options": ["Base curve radius", "Diameter", "Center thickness", "Peripheral curve design"], "correct": 0, "explanation": "Base curve radius most influences an RGP''s sagittal depth (steeper base curve = greater sag). Hint: steeper base curve = deeper sag/vault."}'),
  ('bde293db-2o','{"options": ["Daily disposable silicone hydrogel", "Monthly hydrogel", "RGP lenses", "Scleral lenses"], "correct": 3, "explanation": "Scleral lenses suit dry-eye patients best (a fluid reservoir bathes the cornea all day). Hint: dry eye + wants lenses = scleral (a built-in tear bath)."}'),
  ('e5ab5767-3k','{"options": ["Flatten base curve", "Steepen base curve", "Decrease diameter", "Increase edge lift"], "correct": 1, "explanation": "Steepen the base curve, excessive central bearing (touch) in ortho-k means too little central clearance, so steepen. Hint: central touch = not enough vault = steepen the base curve."}'),
  ('fb6c42ff-36','{"options": ["Soft toric lens", "Scleral lens", "Daily disposable soft lens", "Rigid gas permeable lens with small diameter"], "correct": 1, "explanation": "A scleral lens best corrects an irregular post-trauma cornea (vaults it with a smooth optical surface). Hint: irregular cornea = scleral vault."}'),
  ('48a896a8-1r','{"options": ["To control centration and movement", "To provide optical power", "To add color to the lens", "To increase oxygen permeability"], "correct": 0, "explanation": "Peripheral curves control RGP centration and movement (and tear exchange). Hint: the edge/peripheral curves steer fit, centration, and movement, not power."}'),
  ('fc789702-43','{"options": ["Contact lens-induced papillary conjunctivitis", "Corneal abrasion", "Bacterial keratitis", "Lens overwear syndrome"], "correct": 0, "explanation": "Contact-lens-induced papillary conjunctivitis (CLPC/GPC), severe itching and intolerance after months of soft-lens wear. Hint: months of wear then itch/intolerance with upper-lid papillae = CLPC/GPC."}'),
  ('b14a56a7-1j','{"options": ["Daily cleaning with enzymatic cleaner", "Rinse with saline only before wear", "Use multipurpose solution once a week", "Clean with soap and water daily"], "correct": 0, "explanation": "Daily cleaning is the core RGP regimen (with periodic enzymatic protein removal); this option captures the ''clean daily'' idea, though enzymatic is usually periodic not daily, so VERIFY the key''s wording. Hint: RGP care = clean daily + disinfect, plus periodic enzyme; never soap/water or saline-only."}'),
  ('59466c2f-1s','{"options": ["Increased risk of ocular trauma", "Reduced visual acuity", "Lens discoloration", "Allergic conjunctivitis"], "correct": 0, "explanation": "The primary sports concern with lenses is increased risk of ocular trauma (plus dislodgement/loss). Hint: contact sports + lenses = trauma/displacement risk is the main worry."}'),
  ('84a218b7-3e','{"options": ["Multipurpose solution with preservatives", "Hydrogen peroxide-based solution", "Saline solution only", "Enzymatic cleaner"], "correct": 1, "explanation": "A hydrogen peroxide system suits recurrent contact-lens-associated red eye (removes preservative reactions). Hint: recurrent red eye from solutions = go preservative-free (peroxide)."}'),
  ('bdab498e-3k','{"options": ["Lens dehydration", "Corneal ulcer", "Incorrect prescription", "Contact lens overwear"], "correct": 0, "explanation": "Lens dehydration causes intermittent daytime fogging/blur (the lens dries and the surface degrades). Hint: midday fluctuating blur on soft lenses = the lens is drying out."}'),
  ('37c37f4c-22','{"options": ["Base curve radius", "Overall diameter", "Center thickness", "Edge design"], "correct": 0, "explanation": "Base curve radius (which sets the central sagittal vault/clearance) is the critical scleral parameter, get the corneal clearance right first. If the key names ''sagittal depth/overall diameter,'' that is the same idea, VERIFY. Hint: sclerals are fit by VAULT (sagittal depth), driven by the base curve."}'),
  ('63be503c-2j','{"options": ["Tear breakup time (TBUT)", "Visual acuity", "Retinoscopy", "Fundus examination"], "correct": 0, "explanation": "Tear breakup time (TBUT) is the most reliable measure of dry-eye severity in lens wearers. Hint: dry-eye severity = TBUT (tear-film stability)."}'),
  ('dfffee03-2o','{"options": ["Base curve", "Add power design", "Diameter", "Edge thickness"], "correct": 1, "explanation": "Add-power design most affects near-vision quality in a multifocal contact lens. Hint: it is the near ADD design that drives near performance."}'),
  ('9ba136f4-3h','{"options": ["Giant papillary conjunctivitis", "Microbial keratitis", "Dry eye syndrome", "Corneal abrasion"], "correct": 0, "explanation": "Giant papillary conjunctivitis, mucous discharge with large papillae on the upper tarsal conjunctiva. Hint: upper-lid cobblestone papillae + mucus = GPC."}'),
  ('341e4acf-2r','{"options": ["Soft spherical lenses", "Toric soft lenses", "RGP lenses", "Hybrid lenses"], "correct": 2, "explanation": "RGP lenses best correct combined high myopia and astigmatism (the rigid tear lens neutralizes cylinder). Hint: high astigmatism = rigid (RGP) for crisp correction."}'),
  ('d87ffe5e-2b','{"options": ["Hydrogen peroxide-based solution", "Multipurpose solution", "Enzymatic cleaner", "Saline solution"], "correct": 2, "explanation": "Enzymatic cleaners are most effective at removing PROTEIN deposits. Hint: protein = enzyme cleaner (it digests protein)."}'),
  ('772cc5ce-4o','{"options": ["Allergic conjunctivitis", "Mechanical irritation due to poor lens fit", "Infectious keratitis", "Lens contamination"], "correct": 1, "explanation": "Mechanical irritation from a poor ortho-k lens fit causes post-insertion discomfort/injection. Hint: discomfort right after inserting a rigid lens = a fit/mechanical problem."}'),
  ('a95f1792-28','{"options": ["Daily", "Weekly", "Monthly", "Quarterly"], "correct": 0, "explanation": "Daily disposables are replaced every day (worn once, then discarded). Hint: ''daily'' disposable = one day, one lens."}'),
  ('240f3c0b-29','{"options": ["Base curve", "Thickness", "Diameter", "Material color"], "correct": 1, "explanation": "Thickness (the ''t'' in Dk/t) primarily determines transmissibility for a given material, thinner = more oxygen through. Hint: Dk/t, so thinner lens = higher oxygen transmissibility."}'),
  ('2b143a66-3j','{"options": ["Switch to silicone hydrogel lenses", "Prescribe corticosteroid eye drops", "Stop lens wear permanently", "Recommend longer wearing time"], "correct": 0, "explanation": "Switch to silicone hydrogel lenses for persistent dryness despite drops (higher oxygen, less on-eye dehydration). Hint: chronic soft-lens dryness = move up to silicone hydrogel."}'),
  ('bc58e8fc-1z','{"options": ["Excessive lens movement during blink", "Central fluorescein pooling", "Slight movement with blink and even fluorescein pattern", "Edge lift causing conjunctival staining"], "correct": 2, "explanation": "A well-fitted RGP shows slight movement on blink with an even (aligned) fluorescein pattern. Hint: ideal RGP = a little blink movement + even fluorescein, not central pooling or excess rock."}'),
  ('1064d8c0-2f','{"options": ["Base curve", "Diameter", "Cylinder axis", "Edge thickness"], "correct": 2, "explanation": "The cylinder axis (in a toric lens) is adjusted to correct astigmatism in soft lenses. Hint: astigmatism correction lives in the toric cylinder/axis."}'),
  ('8be6a154-1y','{"options": ["Corneal neovascularization", "Conjunctival injection", "Corneal abrasion", "Papillary conjunctivitis"], "correct": 0, "explanation": "Corneal neovascularization is the hallmark sign of chronic contact-lens hypoxia. Hint: chronic low oxygen grows new vessels = neovascularization."}'),
  ('aaa91472-38','{"options": ["Lens surface deposits", "Incorrect base curve", "Solution allergy", "Lens overwear syndrome"], "correct": 1, "explanation": "An incorrect base curve on a NEW pair causes a fit/optical mismatch, producing halos and glare (deposits are unlikely on fresh lenses). Hint: brand-new lenses with glare = wrong base curve/fit, not deposits."}'),
  ('94d55cb4-28','{"options": ["Multipurpose solution", "Hydrogen peroxide-based solution", "Saline solution", "Enzymatic cleaner"], "correct": 1, "explanation": "Hydrogen peroxide-based solutions must be NEUTRALIZED before the lens touches the eye. Hint: peroxide burns, so it needs neutralizing/disc-catalyst before wear."}'),
  ('6a446ce5-3l','{"options": ["Soft contact lenses", "Monovision contact lenses", "RGP contact lenses", "Spectacles"], "correct": 2, "explanation": "RGP contact lenses give the best binocular outcome in high myopia with anisometropia (least aniseikonia, crisp optics). Hint: anisometropia = contact lenses over glasses; RGP for the sharpest, most equal images."}'),
  ('72d828ab-23','{"options": ["Corneal topography", "Slit lamp fluorescein pattern assessment", "Tear breakup time", "Tonometry"], "correct": 1, "explanation": "Slit-lamp fluorescein pattern assessment evaluates scleral-lens fit (central vault, limbal clearance, landing). Hint: judge a scleral fit by its fluorescein/clearance pattern at the slit lamp."}'),
  ('c4e456ac-21','{"options": ["Corneal ulcer", "Giant papillary conjunctivitis", "Conjunctival hyperemia", "Corneal edema"], "correct": 3, "explanation": "Corneal edema is the most common contact-lens overwear complication (hypoxic swelling). Hint: overwear = oxygen debt = corneal edema."}'),
  ('ee4ef914-2u','{"options": ["8 hours", "12 hours", "16 hours", "24 hours"], "correct": 0, "explanation": "New soft-lens wearers should cap daily wear around 8 hours during adaptation, then build up gradually. Hint: start low (about 8 hours) and increase as the eyes adapt."}'),
  ('a530fdcb-2n','{"options": ["Jones I test", "Lacrimal prism test", "TBUT test", "Schirmer''s test"], "correct": 2, "explanation": "TBUT (tear break-up time) directly measures tear film stability, which collapses first when the film is deficient, so it is the good indicator of the tear FILM itself. Jones I checks nasolacrimal drainage patency, not the film. Lacrimal prism (tear meniscus) height only roughly estimates aqueous volume. Schirmer measures aqueous PRODUCTION (quantity) and is the go-to for aqueous-deficient dry eye, so keep it in mind if the stem says aqueous deficiency instead of tear film."}'),
  ('06942b85-1c','{"options": ["hydrophobic layer", "interspersed with protein", "bilayer of lipid", "hydrophilic layer"], "correct": 0, "explanation": "Defective item: the fluid-mosaic membrane genuinely has all four features (a lipid bilayer with hydrophilic phosphate heads outward, hydrophobic tails inward, proteins interspersed), so no clean EXCEPT exists. If the writer pictured the membrane as ONE layer of a single polarity, then calling it a simple hydrophobic layer is the least accurate, since the defining trait is that it is a BI-layer that is amphipathic. VERIFY against the source key."}'),
  ('08a8065e-2c','{"options": ["Stain collagen", "Is mucolytic", "Penetrate intact corneal epithelium", "Stain devitalized tissue"], "correct": 3, "explanation": "Rose Bengal is a vital dye that stains devitalized (dead/degenerating) epithelial cells and mucus that has lost its protective mucin coat, which is why it maps dry-eye surface damage. It does not stain collagen, is not mucolytic, and (unlike fluorescein at a break) it does not simply penetrate an intact epithelium. Memory hook: Rose Bengal = Rotten cells; fluorescein = Fills defects."}'),
  ('32c6d971-1o','{"options": ["Daily Conventional lens", "Daily disposable lens", "Extended wear lenses", "Rigid contact lens"], "correct": 2, "explanation": "A bandage contact lens must stay on continuously to protect a healing cornea, so a soft high-water, high-Dk extended-wear lens is best. Daily conventional and daily disposable lenses are meant to come out each day, defeating the purpose, and a rigid lens would mechanically abrade the compromised surface. Key idea: bandage = worn continuously = extended wear."}'),
  ('6879762d-2a','{"options": ["Neostigmine", "Pilocarpine", "Timolol", "Atropine"], "correct": 3, "explanation": "Atropine is an antimuscarinic (cycloplegic/mydriatic) that relaxes the ciliary muscle, slackens the trabecular meshwork, and can crowd the angle, RAISING IOP, so it is contraindicated in glaucoma. Neostigmine (anticholinesterase) and pilocarpine (direct cholinergic) both cause miosis and pull the meshwork open to increase outflow; timolol (beta-blocker) lowers aqueous production. Anything that dilates the pupil in a glaucoma stem is your EXCEPT."}'),
  ('f0ae5d7f-5z','{"options": ["Ibuprofen", "Paracetamol", "Isotretinoin", "Tylenol"], "correct": 2, "explanation": "Isotretinoin (Accutane) is a recognized cause of drug-induced transient myopia and dry eye, from ciliary body edema/lens changes. Ibuprofen, paracetamol, and Tylenol (which is paracetamol/acetaminophen, so B and D are literally the same drug, a giveaway that neither is the answer) are not classic myopia inducers. Other exam culprits for acute myopia: sulfonamides and topiramate."}'),
  ('e2835003-1m','{"options": ["Tetracaine", "Cocaine", "Proparacaine", "Benoxinate"], "correct": 1, "explanation": "Cocaine is unique among topical anesthetics because it also blocks norepinephrine reuptake, so the extra adrenergic tone at the dilator muscle produces mydriasis (the basis of the cocaine test for Horner''s). Tetracaine, proparacaine, and benoxinate are pure local anesthetics with no adrenergic action, so no dilation. Cocaine = anesthetic PLUS sympathomimetic."}'),
  ('a37611bb-34','{"options": ["Pilocarpine", "Epinephrine", "Levobunolol", "Betaxolol"], "correct": 3, "explanation": "Betaxolol is beta-1 SELECTIVE, so it lowers IOP while largely sparing the beta-2 receptors in the bronchi, making it the safest beta-blocker in an asthmatic. Levobunolol (and timolol) are NON-selective and can trigger bronchospasm. Epinephrine raises blood pressure, bad in a hypertensive. Pilocarpine works but the stem wants the drug matched to the comorbidities, and cardioselective betaxolol threads asthma + hypertension best. Contrast with the plain-hypertensive item where nonselective timolol is fine."}'),
  ('946f91ff-1z','{"options": ["use 0.5% Tropicamide for 3 doses every 5 minutes since side effects are rare", "used 1% Atropine instead of 2% Cyclopentolate", "use 0.5% of Cyclopentolate so that even 3 doses every 5 minutes will not produce CNS toxicity", "use 2% of Cyclopentolate so that only 1 dose is enough to dilate the pupils"], "correct": 2, "explanation": "Cyclopentolate''s CNS toxicity (ataxia, hallucinations, disorientation) is dose/concentration related, so the safest move is to keep the SAME drug but drop to the lower 0.5% concentration in a small child. Option A switches to a different, weaker drug (tropicamide) rather than fixing the cyclopentolate dose; B switches to atropine, which has its own greater systemic toxicity and long duration; D raises the concentration to 2%, increasing risk. Lower concentration = less systemic load in pediatrics."}'),
  ('7febcffc-k','{"options": ["interfere with far vision", "increase heart rate", "constrict bronchi", "increase blood pressure"], "correct": 2, "explanation": "Beta antagonists (blockers) oppose sympathetic tone, so they DECREASE heart rate and blood pressure and, by blocking beta-2 in the airway, cause bronchoconstriction (why they are dangerous in asthma). They do not increase heart rate or blood pressure, ruling out B and D. Constricting bronchi is the classic beta-2 blockade effect."}'),
  ('6bbbec8f-3o','{"options": ["Isoflurophate", "Demecarium", "Echothiophate", "Physostigmine"], "correct": 3, "explanation": "Pilocarpine is a DIRECT cholinergic agonist; pairing it with an anticholinesterase raises available acetylcholine so both mechanisms drive miosis and outflow. Physostigmine (eserine) is the short-acting reversible anticholinesterase classically combined with pilocarpine. Isoflurophate, echothiophate, and demecarium are long-acting IRREVERSIBLE anticholinesterases that also lower IOP but carry more risk (cataract, iris cysts), so they are not the routine add-on. VERIFY: some keys accept any anticholinesterase here."}'),
  ('baea6562-f','{"options": ["indicates the start of biotransformation", "indicates the rate of absorption of drug", "indicates the rate at which drug is eliminated", "indicates the end of absorption"], "correct": 3, "explanation": "Peak plasma level (Cmax, reached at Tmax) is the moment where the rate of absorption has fallen to equal the rate of elimination, so the plasma concentration stops climbing. That inflection marks the effective END of the net absorption phase. It is not a measure of biotransformation start, nor the raw absorption rate, nor the elimination rate. Picture the concentration-time curve: the peak is where the uphill absorption limb hands off to the downhill elimination limb."}'),
  ('52fd7064-2d','{"options": ["cholinergic agonists", "nicotinic agonists", "muscarinic antagonist drug", "muscarinic agonist drugs"], "correct": 2, "explanation": "Atropine competitively BLOCKS muscarinic acetylcholine receptors, so it is the textbook muscarinic ANTAGONIST (antimuscarinic/parasympatholytic), giving mydriasis, cycloplegia, tachycardia, and dry secretions. It is not an agonist of any kind. Belladonna (bella-donna, ''beautiful woman'') is the memory cue: Renaissance women used it to dilate their pupils."}'),
  ('6d641169-1t','{"options": ["Lipid profile", "Protein Purified Derivative", "Hemoglobin test", "Chest X-ray"], "correct": 2, "explanation": "The hemoglobin test here means glycosylated hemoglobin (HbA1c), which reflects average blood glucose over about 3 months and is the standard test for diabetes control/diagnosis. Lipid profile screens cardiovascular risk, PPD (Purified Protein Derivative) is the tuberculosis skin test, and chest X-ray images the lungs. Link HbA1c to sugar-coated red cells."}'),
  ('89161574-38','{"options": ["Pharmacotherapeutic phase", "Pharmaceutic phase", "Pharmacokinetic phase", "Pharmacodynamic phase"], "correct": 1, "explanation": "The pharmaceutic phase is the first stage of oral drug action: the tablet must DISINTEGRATE and then DISSOLVE into solution before anything can be absorbed. Pharmacokinetic covers ADME once dissolved, pharmacodynamic is the drug-receptor effect, and pharmacotherapeutic is the clinical outcome. Sequence: pharmaceutic (get into solution) then kinetic then dynamic."}'),
  ('fcc3536b-38','{"options": ["Gramicidin", "Bacitracin", "Prednisolone", "Erythromycin"], "correct": 3, "explanation": "Erythromycin 0.5% ophthalmic ointment is the modern replacement for silver nitrate in newborn eye prophylaxis; it covers Neisseria gonorrhoeae AND Chlamydia (which silver nitrate misses) without the chemical conjunctivitis silver nitrate causes. Gramicidin and bacitracin have narrower, mainly gram-positive coverage, and prednisolone is a steroid, never a prophylactic anti-infective. Newborn eyes: erythromycin."}'),
  ('205e4bc8-25','{"options": ["cause bradycardia", "increase bowel (large intestine) activity", "increase body temperature in children", "constrict bronchi"], "correct": 2, "explanation": "Anticholinergics block parasympathetic (rest-and-digest) tone, so you get the opposite of SLUDGE: tachycardia (not bradycardia), reduced gut motility (not increased), bronchoDILation (not constriction), and reduced sweating that raises body temperature, the ''atropine fever'' children are especially prone to. That anhidrosis-driven hyperthermia is the correct effect. Mnemonic: dry as a bone, hot as a hare, red as a beet, blind as a bat, mad as a hatter."}'),
  ('02465d59-1w','{"options": ["Neisseria gonorrhaea", "Neisseria meningitides", "Viruses", "Streptococcus pneumonia"], "correct": 2, "explanation": "Penicillins inhibit bacterial cell-wall (peptidoglycan) synthesis, and VIRUSES have no cell wall, so penicillins are useless against them. The three bacterial options (both Neisseria species and Streptococcus pneumoniae) do have cell walls and are classic penicillin targets. No wall, no penicillin effect."}'),
  ('5be79606-37','{"options": ["A", "E", "C", "K"], "correct": 2, "explanation": "Scurvy is vitamin C (ascorbic acid) deficiency; without it collagen cannot be hydroxylated, so you get bleeding gums, poor wound healing, and bruising. Vitamin A deficiency causes night blindness/xerophthalmia, vitamin E deficiency causes neuro/hemolytic problems, and vitamin K deficiency causes bleeding from clotting-factor failure. C for sCurvy and Collagen."}'),
  ('ad945f44-2v','{"options": ["Absorption", "Disintegration", "Dissolution", "Biotransformation"], "correct": 0, "explanation": "Absorption is specifically the passage of dissolved drug from the GI lumen across the mucosa into the blood/body fluids. Disintegration is the tablet breaking into fragments, dissolution is those fragments dissolving into solution, and biotransformation is the liver chemically altering the drug. Order: disintegration, dissolution, absorption, then distribution/metabolism."}'),
  ('83be7ab8-z','{"options": ["water - soluble", "fat - soluble", "protein - bounded", "lipid - bounded"], "correct": 1, "explanation": "A drug that dissolves in fat is by definition fat-soluble (lipophilic/non-polar), which lets it cross lipid membranes and the blood-brain barrier easily. Water-soluble means it dissolves in aqueous fluid, and ''protein-bound'' or ''lipid-bound'' describe how a drug is carried or stored, not its solvent. Like dissolves like: fat-soluble drug in a fatty solvent."}'),
  ('e967e8bd-1u','{"options": ["pilocarpine and acetylcholine", "albuterol and dopamine", "atropine and scopolamine", "clonidine and methyl dopa"], "correct": 2, "explanation": "Atropine and scopolamine block muscarinic receptors on the iris sphincter, so the sphincter cannot contract and the pupil stays dilated (mydriasis) - they ''inhibit constriction.'' Pilocarpine and acetylcholine are cholinergic agonists that DO constrict the pupil. Albuterol/dopamine are adrenergic, and clonidine/methyldopa are central alpha-2 agents; none are antimuscarinics. Antimuscarinic = no sphincter contraction = big pupil."}'),
  ('306be17f-1o','{"options": ["Staphylococcus aureus", "Pseudomonas aeruginosa", "Escherichia coli", "Fusarium"], "correct": 1, "explanation": "Pseudomonas aeruginosa is the classic contaminant of fluorescein solutions and moist ophthalmic supplies; it thrives in water and is especially dangerous because it can cause a rapidly perforating corneal ulcer. This is exactly why single-use fluorescein strips replaced multi-dose bottles. Staph, E. coli, and the fungus Fusarium are not the signature fluorescein contaminant. Pseudomonas loves water = loves fluorescein bottles."}')
)
UPDATE question_reviews r
SET payload = r.payload || d.patch::jsonb
FROM d
WHERE r.question_id = d.qid;
